('a, an', 'indef.art (ئۈزۈك تاۋۇش بىلەن باشلانغان سۆزلەرنىڭ ئالدىدا a، سوزۇق تاۋۇش بىلەن باشلانغان سۆزلەرنىڭ ئالدىدا an ئىشلىتىلىدۇ) ① بىر، بىر دانە: a pen بىر قەلەم/ an hour بىر سائەت (ۋاقىت)/ a book بىر كىتاب/a university بىر داشۆ/a house بىر ئېغىز ئۆي. ② ھەر، ھەر بىر: once a mounth (ھەر) ئايدا بىر قېتىم. ③ (تۈرداش شەيئىلەرنى كۆرسىتىدۇ) ھەرقانداق (خىل، تۈر): A square has four sides. ھەرقانداق كۋادراتنىڭ تۆت تەرىپى بولىدۇ. ④ ئوخشاش: of a size ئوخشاش دەرىجىلىك (ئاياغ ۋە باشقىلار).', 'A'),
