('as', 'adv.Ⅰ شۇنچە، شۇنچىلىك، ئاشۇنداق، ئوخشاش،  بىردەك: Ⅰ have  as  many. مەندىمۇ شۇنچىلىك بار. ① conj.Ⅱ ... -دەك، ... -غا ئوخشاش: Do as  I say مەن دېگەندەك قىلغىن He is as clever  as  his sister./ ئۇ ھەدىسىگە ئوخشاش چېچەن. (مۇشۇ جۈملىدىكى بىرىنچى as رەۋىش، ئىككىنچى as باغلىغۇچى بولۇپ كېلىدۇ). ② ئىكەن، بولۇپ تۇرۇقلۇق، سەۋەبتىن: home  as  she was ill. She stayed at ئۇ كېسەل سەۋەبىدىن ئۆيدە قالغانىدى. ③ شۇ پەيتتە، شۇ چاغدا، شۇ ۋاقىتتا:  looking for him He appeared  as  we were بىز ئۇنى ئىزدەۋاتقىنىمىزدا ئۇ پەيدا بولۇپ قالدى. ④ گەرچە، تەقدىردىمۇ: not buy it. Much  as  I like it, I will گەرچە ئۇنى ياخشى كۆرسەممۇ، لېكىن سېتىۋالغۇم يوق. pron.Ⅲ (such بىلەن بىرگە كېلىپ ... -غان، -قان، -گەن، -كەن، -دەك، -تەك، ... قاتارلىق دېگەنگە ئوخشاش قوشۇمچىلار بىلەن ئىپادىلىنىدۇ): such liquors  as  beer پىۋا قاتارلىق ئىچىملىكلەر/ such questions  as  are often asked by stedents. ئوقۇغۇچىلار دائىم سورايدىغان سوئاللار. ② (same بىلەن بىرگە ئىشلىتىلىدۇ)... بىلەن ئوخشاش ... دەك: Bees like the same oders  as  we do ھەسەل ھەرىسى بىز بىلەن ئوخشاش خۇش پۇراقنى ياخشى كۆرىدۇ. ③(as بىلەن بىرگە ئىشلىتىلىدۇ) ... -غان، ...-قان بارلىق: as many children as  came كەلگەن بارلىق بالىلار. ④ ئۇنى، ئۇ، بۇ: He was absent,  as  is often the case. ئۇ كەلمىدى، بۇ دائىم بولۇپ تۇرىدىغان ئەھۋال. ① prep.Ⅳ ... نىڭ رولىدا، ئورنىدا، ... قىياپىتى بىلەن: work as  an engineer ئىنژېنېرنىڭ ئورنىدا ئىشلىمەك. ② ... دەپ قارىماق، ... دەپ ھېسابلىماق: I regard him  as  a guest. مەن ئۇنى مېھمان دەپ قارايمەن.  as  (so) far  as ...گىچە، ... كىچە:  as  far  as  I konw مېنىڭ بىلىشىمچە  as  for (to)/ -گە كەلگەندە، ... -گە كەلسەك، ... دىن سورىساق:  as  to his study ئۇنىڭ ئوقۇشىغا كەلسەك  as if (though)/... دەك، خۇددى long  as  so)  as / پەقەت، ... لا، پەقەت ...لا  as  well  as / ھەم... ھەم... يەنە ( in order to) so  as  to/ ئۈچۈن، مەقسىتىدە، يولىدا.', 'A'),
