('divorce', '①n.Ⅰ نىكاھدىن ئاجراش، نىكاھدىن ئاجرىشىش. ② بۆلۈش، پارچىلاش. ①v.Ⅱ ... بىلەن ئاجراشماق، ئاجرىشىپ كەتمەك (نىكاھدىن). ② ئايرىلماق، ... بىلەن مۇناسىۋەتنى ئۈزمەك.', 'D'),
('do', 'ux.v.Ⅰ (did      ؛ done      ) (do نىڭ ئۈچىنچى شەخس ھازىرقى زامان بىرلىك شەكلى does، dz dz، ھازىرقى زامان سۈپەتداش شەكلى doing      ). ① ئىگىنڭ ئالدىدا كېلىپ، سوراق جۈملىلەر ياسىلىدۇ). Do you like music? سىز مۇزىكىنى ياخشى كۆرەمسىز؟ ② (not بىلەن بىرگە كېلىپ، ئىنكار جۈملىلەر ياسىلىدۇ): Do not forget it. ئۇنتۇپ قالما. ③ (سۆز ئورامىنى كۈچەيتىدۇ): Do come tomorrow morning. ئەتە ئەتىگەن چوقۇم كېلىڭ-ھە! ① v.Ⅱ قىلماق، ئەتمەك، ئىشلىمەك، ھەرىكەتلەنمەك:  do  one’s work خىزمەت قىلماق ◇  do washing / كىر يۇماق ◇ What can I  do / for you سىزگە نېمە كېرەك؟ / ◇ Do as you please ئىختىيار سىزدە. ② تۈگىمەك، تۈگەتمەك، ئاياغلاشماق، ئاياغلاشتۇرماق، ئورۇندىماق، ئورۇندالماق (ئۆتكەن زامان سۈپەتداش شەكلى ئىشلىتىلىدۇ): The work is done. خىزمەت ئاياغلاشتى، ئىش تۈگىدى. ③ لايىق بولماق، مۇۋاپىق كەلمەك، باب كەلمەك، بولماق: Any time will do. قاچان بولسا بولىۋېرىدۇ. ④ راۋاجلاندۇرماق. ⑤ رەتلىمەك. ⑥ پىشۇرماق. ⑦ رول ئالماق. ⑧ (يۇقىرىدا ئېيتىلغان پېئىللارنىڭ ئورنىدا كېلىدۇ):He speaks English better than I do. ئۇ ئىنگلىزچىنى مەندىن ياخشى سۆزلەيدۇ.  do  away with// ئەمەلدىن قالدۇرماق ①  do  up/ تازىلىماق، تەرتىپكە سالماق، رەتلىمەك. ② ئورىماق: ئەتمەك. ③ جايلاشتۇرماق  do  with/ بىر تەرەپ قىلماق have something       to do with ...بىلەن مۇناسىۋىتى بولماق(بولماسلىق).', 'D'),
