('drink', 'v.Ⅰ (drank      ؛ drunk      ) ① ئىچمەك، سۈمۈرمەك. ② ... ئۈچۈن قەدەھ كۆتۈرمەك. ③ قوبۇل قىلماق. ①v.Ⅱ ئۇسسۇزلۇق. ② ئىچىملىك، ھاراق. ③ بىر قەدەھ (ئىچىش).', 'D'),
('drip', 'v.Ⅰ ( drip ped،  drip ped،  drip ping) تامماق، تامچىلىماق، تېمىتماق. n.Ⅱ تامچىلاش، تامچىلىتىش.', 'D'),
('drive', 'v.Ⅰ (drove      ؛ driven      ) ① ھەيدىمەك. (ھارۋا، ماشىنا قاتارلىقلارنى). ② قوغلىماق. ③ ھەرىكەتلەنمەك، ھەرىكەتلەندۈرمەك. ④ مەجبۇر قىلماق، زورلىماق. ⑤ ئۇرماق، ئۇرۇلماق (توپ). ⑥ ئۇچقاندەك يۈگۈرمەك؛ تېز ئىلگىرىلىمەك. ⑦ قاقماق (مىق). ①.Ⅱ ماشىنا ھەيدەش، ئاپتوموبىل ھەيدەش. ② (شەخسىي قورا-جايلاردىكى) ماشىنا يولى. ③ ئۇرۇش، ئۇرۇلۇش (توپ). ④ ھەرىكەتلەندۈرۈش كۈچى. ⑤ (ئامېرىكا تىلىدا) سىياسىي ھەرىكەت؛ مۇسابىقە.', 'D'),
('driven', 'v. → drive.', 'D'),
('driver', '①n. پادىچى. ② شوپۇر.', 'D'),
('droop', 'v. ساڭگىلىماق، ساڭگىلاتماق.', 'D'),
('drop', '①n.Ⅰ تامچە، سۇ تامچىسى. ② چۈشۈش، چۈشۈپ كېتىش، تۆۋەنلەش. ③ مىكرو مىقدار. ①v.Ⅱ چۈشمەك، چۈشۈپ كەتمەك. ② تامچىلىماق، تامچىلاتماق. ③ چۈشۈپ قالماق، چۈشۈرۈپ قويماق (ماشىنا قاتارلىقلاردىن). ④ ئاجىزلاشماق، ئاجىزلاشتۇرماق. ⑤ تۇيۇقسىز ئېيتماق. ⑥ تۇيۇقسىز ئەۋەتمەك.  drop behind ‖ سەپتىن چۈشۈپ قالماق  drop  in (on sb.) / تاسادىپىي يوقلىماق. ① drop off / تەدرىجىي ئازايماق، بارا-بارا كېمەيمەك. ② ئاستا-ئاستا تارقالماق. ③ ئۇخلىماق.', 'D'),
('drought', 'n. قۇرغاقچىلىق، قۇرغاقچىلىق ئاپىتى.', 'D'),
('drove 1', 'v. → drive.', 'D'),
('drove 2', '①n. كىشىلەر توپى. ② پادا.', 'D'),
('drown', '①v. تۇنجۇقۇپ ئۆلمەك، تۇنجۇقتۇرۇپ ئۆلتۈرمەك. ② چۆكمەك، چۆكۈرمەك، غەرق قىلماق، غەرق بولماق.', 'D'),
('drowsy', '①adj. ئۇيقۇ باسقان، ئۈگدەپ قالغان. ② ئۇيقۇسىنى كەلتۈرىدىغان.', 'D'),
('drug', '①n.Ⅰ دورا، دورا-دەرمەك. ② ھوشسىزلاندۇرۇش دورىسى، مەست قىلىش دورىسى. ③ كاسات مال، بازىرى كاساتلاشقان مال. v.Ⅱ ( drug ged،  drug ged،  drug ging) ① مەست قىلىش دورىسى يېمەك (ئىچمەك)، مەست قىلىش دورىسى يېگۈزمەك (ئىچكۈزمەك). ② زەھەرلىك چېكىملىكلەرنى چەكمەك، زەھەرلىك چېكىملىكلەرنى چەككۈزمەك.', 'D'),
('drum', '①n.Ⅰ دۇمباق. ② ناغرا. ③ داپ. ④ دۇمباقسىمان نەرسىلەر. ⑤ غالتەك (يىپ يۆگەيدىغان). v.Ⅱ ( drum med،  drum med،  drum ming) ① دۇمباق چالماق. دۇمباق چېلىنماق. ① ناغرا چالماق، ناغرا چېلىنماق. ③ داپ چېلىنماق.', 'D'),
('drunk', '.drink ←v.Ⅰadj.Ⅱ (كېسىم خەۋەر بولۇپ كېلىدۇ). مەست بولغان، مەست بولۇپ قالغان؛ be  drunk  مەست بولۇپ قالماق.', 'D'),
('drunken', 'adj. مەست، مەست بولۇپ قالغان.', 'D'),
('dry', '①adj.Ⅰ قۇرۇق، قۇرۇپ كەتكەن، قۇرۇپ قالغان. ② بىمەنە، تېتىقسىز. ③ بىۋاسىتە. ④ ھەقىقىي، راست. v.Ⅱ قۇرۇماق؟ قۇرۇتماق. ①up  dry  ‖ قۇرۇپ كەتمەك؟ قۇرۇتۇۋەتمەك. ② (ئوي-پىكىر قاتارلىقلار) تۈگىمەك.', 'D'),
('dual', 'adj. قوش، ئىككى ياقلىما، ئىككىقات.', 'D'),
('duck', 'n. ئۆردەك، ئۆردەك گۆشى.', 'D')
ON CONFLICT (english) DO NOTHING;

