('due', '①adj. بېرىدىغان، بېرىلىدىغان، تاپشۇرىدىغان، تاپشۇرۇلىدىغان، بېرىشكە تېگىشلىك. ② مۇۋاپىق، لايىق. ③ يېتەرلىك. ④ بەلگىلەنگەن (ۋاقىت).', 'D'),
