('dwell', 'v. )dwelt      ؛ dwelt) ① )يېزىقتا) ئولتۇراقلاشماق، تۇرماق. ② ئىنچىكە ئويلانماق. ③ تەپسىلىي سۆزلەشمەك.', 'D'),
