('early', '①adj.Ⅰ بۇرۇن پىشىدىغان (مېۋە). ② ئەتىگەن، بالدۇر. ③ دەسلەپكى، دەسلەپكى مەزگىلدىكى dv.Ⅱ بالدۇر، ئەتىگەن.', 'E'),
