('earthquake', 'n. يەر تەۋرەش.', 'E'),
('ease', '①n.Ⅰ ئوڭايلىق، قولايلىق. ② خاتىرجەملىك. ot (one,s) ease ‖ ئەركىن، ئازادە ill at  ease  / ئەيمەنمەك، قورۇنماق setsb.at ease / بىراۋنى خاتىرجەم قىلماق take(one,s) ease / قورۇنماسلىق، تارتىنماسلىق with ease / ئوڭايلا، ئاسانلا، ئاسانلىق بىلەن.', 'E'),
