('edge', '①n. پىچاق بىسى، چەت. ياقا، كىرۋەك، قىرغاق.①v.Ⅱ ئىتتىكلەتمەك، ئۆتكۈرلەشتۈرمەك. ② جىيەك تۇتماق. ③ يانچىلاپ ماڭماق، يانچىلاپ كىرمەك.', 'E'),
