('eye', '①n.Ⅰ كۆز. ② كۆز نۇرى. ③ كۆز قاراش. ④ كۆرۈش قۇۋۋىتى. ⑤ تۆشۈك (يىڭنىنىڭ) be all  eye  s ‖ دىققەت بىلەن قارىماق، تىكىلىپ قارىماق catch one’s eye / دىققىتىنى قوزغىماق have an  eye s to .../ دىققەت قىلماق، زەن قويۇپ قارىماق. have an  eye  for .../ پەرقلەندۈرۈش ئىقتىدارى بولماق. v.Ⅱ قارىماق، كۆز تىكىپ قارىماق، دىققەت بىلەن قارىماق.', 'E'),
('eyeglasses', 'n. كۆزەينەك.', 'E'),
('eyelash', 'n. كىرپىك.', 'E'),
('eyesight', 'n. كۆرۈش قۇۋۋىتى.', 'E'),
('F,f', 'ئىنگلىز تىلى ئېلىپبەسىنىڭ ئالتىنچى ھەرپى', 'F'),
('fable', '① n. مەسەل، كىنايە. ② رىۋايەت، چۆچەك، ئەپسانە.', 'F'),
('fabric', 'n. گەزلىمە، ماتا. ② قۇرۇلما، تۈزۈلۈش، تۈزۈلمە. ③ تەشكىل، تەشكىلات.', 'F'),
('fabricate', '① ئورناتماق، قۇراشتۇرماق ② ئويدۇرما، ئويدۇرۇپ چىقارماق.', 'F'),
('face', '① n.Ⅰ يۈز، چىراي، چېھرە. ② ئوڭى، تېشى، (رەختنىڭ). ③ ئالدى. ④ تاشقى كۆرۈنۈش  face  to ‖ يۈزمۇ يۈز ① in (the)  face  of.../ ... نىڭ ئالدىدا. ②...گە قارىماي، ... گە قارىماستىن، fly in the  face  of.../ ئاشكارا قارشى تۇرماق look sb. in the  face / بىراۋغا تىكىلىپ قارىماق lose one’s  face / يۈزى چۈشمەك، يۈزىنى چۈشۈرمەك save one’s face / يۈزىنى ساقلاپ قالماق، يۈزى چۈشمەسلىك.', 'F'),
('facetious', 'يۇمۇرلۇق، قىزىقچىلىق', 'F'),
('facilitate', '① v. ئوڭايلىق تۇغدۇرماق، قولايلىق ياراتماق. ② ئىلگىرى سۈرمەك.', 'F'),
('facility', 'n. قولايلىق، ئەپچىللىك، چاققانلىق، ئۇستىلىق.', 'F'),
('fact', 'n. پاكىت، ئەمەلىيەت، ھەقىقىي ئەھۋال as a matter of  fact  ‖، in  fact ، in point of  fact  ئەمەلىيەتتە، راستىنى ئېيتقاندا.', 'F'),
('faction', '① مەزھەپ ② گۇرۇھ ③ مەزھەپلەر ئۇرۇشى', 'F'),
('factor', '① n.ئامىل، ئېلېمېنت.〉 ② ماتېماتىكا〈 كۆپەيتكۈچى.', 'F'),
('factory', 'n. زاۋۇت، فابرىكا.', 'F'),
('factual', 'پاكىتلىق، ئەمىلىيەتلىك', 'F'),
('faculty', '① n. ئىقتىدار، قابىلىيەت. ② ئۆز رولى، خىزمىتى. ③ (مەكتەپنىڭ) بارلىق ئوقۇتقۇچىلىرى. ④ فاكۇلتېت.', 'F'),
('fade', '① v. (گۈل، ئوت-چۆپ قاتارلىقلار) قۇرۇپ قالماق، خازان بولماق. ② رەڭگى ئۆچمەك، ئۆڭمەك. ③ يوقالماق، يوقاتماق (ئاۋاز). ④ سۇسلاشماق، سۇسلاشتۇرماق، ئاجىزلاشماق، ئاجىزلاشتۇرماق.', 'F'),
('fag', '① ئادەمنى چارچىتىدىغان خىزمەت ② شئاڭيەن', 'F'),
('Fahrenheit', 'n. فارېنگېيت تېرمومېتىرى (قىسقارتىلمىسى، F).', 'F'),
('fail', '① v. مەغلۇپ بولماق، مەغلۇپ قىلماق. ② ئىمتىھاندىن ئۆتەلمەسلىك. ③ ۋۇجۇدقا چىقماسلىق. ④ يېتىشمەسلىك. ⑤ ئاجىزلاشقان، ئاجىزلاشتۇرماق (سالامەتلىك، كۆرۈش قۇۋۋىتى قاتارلىقلار) n.Ⅱ (without بىلەن بىرگە كېلىدۇ) چوقۇم، جەزمەن.', 'F'),
('failure', '① n. مەغلۇبىيەت، ② يېتىشمەسلىك. ③ ئاجىزلىشىش، ئاجىزلاشتۇرۇش (كۆرۈش قۇۋۋىتى). ④ مەغلۇبىيەتچى، مەغلۇپ بولغۇچى، يېڭىلگۈچى.', 'F'),
('faint', '① adj.Ⅰ ئاجىز، كۈچسىز. ② بېشى قايغان، بېشىنى قايدۇرىدىغان. ③ سۇس، ئاچ (رەڭ) v.Ⅱ ھوشىدىن كەتمەك، بېشى قايماق. n.Ⅲ ھوشسىزلىنىش، بېشى قېيىش.', 'F'),
('faintly', '① adv. ئاجىز، كۈچسىز. ② سۇس، ئاچ (رەڭ).', 'F'),
('fair', '① adj.Ⅰ ئادىل، خالىس، مۇۋاپىق. ② ياخشى، خېلىلا ياخشى. ③ ئوچۇق (ھاۋا). ④ ئاق (تېرە). ⑤ ساپسېرىق (چاچ).〉 ⑥ قەدىمكى تىلدا〈 گۈزەل، چىرايلىق. ⑦ ئېنىق. ① adv.Ⅱ ئادىل، خالىس، مۇۋاپىق. ② ئوچۇق، ئېنىق، روشەن.', 'F'),
('fairly', '① adv. ئادىل، خالىس، مۇۋاپىق. ② خېلى، خېلىلا. ③ ناھايىتى، بەك، ئىنتايىن.', 'F'),
('fairy', 'n. پەرى، پەرىزات.', 'F'),
('fairyland', 'n. پەرىزاتلار ماكانى، ئاجايىپ جاي، ئاجايىپ كۆرۈنۈش.', 'F'),
('faith', '① n. ئىشەنچ. ② ۋەدە، لەۋزە. ③ ئېتىقاد، دىنىي ئېتىقاد. ④ ساداقەت. put one’s  faith  in sb. ‖ بىراۋغا ئىشەنمەك keep        faith  (with sb.)/ (بىراۋغا قىلغان) ۋەدىسىدە تۇرماق (تۇرماسلىق).', 'F'),
('faithful', '① adj. سادىق، ساداقەتلىك. ② توغرا، ئىشەنچلىك.', 'F'),
('faithfully', '① adv. سادىقلىق بىلەن، ساداقەتلىك بىلەن ② توغرا، ئەينەن.', 'F'),
('fake', '① ساختا مال ② ئالدامچى', 'F'),
('falcon', 'n. شۇڭقار', 'F'),
('fall', 'v. (fell      ؛ )  fall        ① پەسەيمەك، پەسەيتمەك، چۈشمەك، تۆۋەنلىمەك، تۆۋەنلەشمەك، ئاجىزلاشماق. ② ئاجىزلاشتۇرماق. ③ ئۆرۈلمەك، ئۆرۈمەك، غۇلىماق، غۇلاتماق، يىقىلماق، يىقىتماق  fall  back ‖ چېكىنمەك  fall  back on / ياردەم تەلەپ قىلماق، يۆلەنمەك  fall  behind / ئارقىدا قالماق  fall  in/ 〉ھەربىي〈 يىغىلماق  fall  in with.../ بىر ئېغىزدىن ماقۇللىماق قوشۇلماق ①  fall  on       / ھۇجۇم قىلماق، زەربە بەرمەك. ② (بايرام) دەل كەلمەك، دەل ... گە توغرا كەلمەك. ① n.Ⅱ پەسىيىش، پەسەيتىش، تۆۋەنلەش، تۆۋەنلىتىش. ② ئاجىزلاش، ئاجىزلىشىش. ③ ئۆرۈش، ئۆرۈلۈش. ④ مۇنقەرز بولۇش، مۇنقەرز قىلىش. ⑤ (ئامېرىكا تىلىدا) كۈز پەسلى (autumn  ).', 'F'),
('fallacy', 'سەپسەتە، بىمەنە سۆز', 'F'),
('fallen', 'v.→ fall.', 'F'),
('fallow', 'دەم ئالدۇرۇلغان يەر', 'F'),
('false', '① adj. خاتا، ناتوغرا. ② سۈنئىي، ئويدۇرما.', 'F'),
('falsehood', 'n. يالغان گەپ، يالغان سۆز.', 'F'),
('falsify', 'ئۆزگەرتىۋەتمەك', 'F'),
('falter', 'دەلدەڭلەپ ماڭماق، سۆرىلىپ ماڭماق', 'F'),
('fame', 'n. ئاتاق، نام، شۆھرەت، ئابرۇي، ئىناۋەت.', 'F'),
('familiar', '① adj. تونۇش. ② يېقىن، قويۇق.', 'F'),
('family', '① n. ئائىلە، بىر ئائىلە. ② بالا-چاقا، ئەۋلاد.', 'F'),
('famine', 'n. قەھەتچىلىك، ئاچارچىلىق. ② ئازلىق، كەملىك، يەتمەسلىك.', 'F'),
('famous', '① adj. ئاتاقلىق، مەشھۇر، داڭلىق، داڭدار. ② (جانلىق تىلدا) ئىنتايىن ياخشى، بەك ياخشى.', 'F'),
('fan', '① n.Ⅰ يەلپۈگۈچ. ② شامالدۇرغۇچ. v.Ⅱ ( fan  ned؛  fan  ned؛  fan  ning) ① يەلپۈرمەك، يەلپۈنمەك. ② كۈشكۈرتمەك، قۇتراتماق، قۇترىماق.', 'F'),
('fanatic', 'تەلۋىلىك، ئەسەبىيلىك، بىردەملىك قىزغىنلىق', 'F'),
('fancy', '① n.Ⅰ خام-خىيال. ② تەسەۋۋۇر قىلىش كۈچى. ③ ھەۋەس. ① adj.Ⅱ رەڭدار، گۈزەل، چىرايلىق، نەپىس. ② ئاجايىپ، ئادەتتىن تاشقىرى. v.Ⅲ (fancied؛ fancied) ① تەسەۋۋۇر قىلماق. ② ھەۋەس قىلماق، خۇشتار بولماق، ياخشى كۆرمەك. ③ ... دەپ قارىماق، ... دەپ ھېسابلىماق.', 'F'),
('fang', 'ئۆتكۈر چىش (ئىت قاتارلىق ھايۋانلارنىڭ)', 'F'),
('fantastic', '① غەيرىلىك، ئاجايىپلىق، غەلىتىلىك. ② بىمەنىلىك.', 'F'),
('fantasy', 'خىيال، خام خىيال', 'F'),
('far', 'adv. ( far  ther      ؛  far  thest      . ۋە further      ؛ )furthest       ① يىراق، ئۇزاق، ئۇزۇن. ② خېلىلا، خېلى ① as        far  as ... غىچە، ... گىچە ② ... ئىچىدە، ... دائىرىسىدە  far  from / ... خېلى يىراق so  far  / ھازىرغا قەدەر، ھازىرغىچە. adj.Ⅱ يىراق، ئۇزاق، ئۇزۇن، يىراقتىكى.', 'F'),
('faraway', '① adj. يىراق، ئۇزاق، يىراقتىكى. ② چېچىلاڭغۇ، پەرىشان (كۆڭۈل). ③ خىرە، تۇتۇق، غۇۋا.', 'F'),
('farce', 'كۈلكىلىك ئويۇن، قىزىق ئويۇن', 'F'),
('fare', '① n.Ⅰ كىرا، كىرا ھەققى. ② يولۇچى. ③ تاماق.①v.Ⅱ ئىلگىرىلىمەك، راۋاجلانماق. ② تۇرمۇش كەچۈرمەك، جان باقماق.', 'F'),
('farewell', 'n.Ⅱ  . goodbye ← int.Ⅰ خوشلىشىش، خەيرلىشىش.', 'F'),
('farm', 'n.Ⅰ دېھقانچىلىق مەيدانى. ① v.Ⅱ ھەيدىمەك، ئاغدۇرماق. ② تېرىماق، تېرىقچىلىق قىلماق. ③ ئىجارىگە ئالماق. ④ ھۆددىگە ئالماق (باجنى).', 'F'),
('farmer', '① n. دېھقان. ② دېھقانچىلىق مەيدان خوجايىنى.', 'F'),
('farmhand', '① n. دېھقان، دېھقانچىلىق مەيدان ئىشچىسى. ② ياللانما دېھقان. ③ مەدىكار، يىللىقچى.', 'F'),
('farming', 'n. دېھقانچىلىق، تېرىقچىلىق.', 'F'),
('farmland', 'n. ئېتىز، ئېتىز-ئېرىق.', 'F'),
('farther', 'adv.＆adj.→ far.', 'F'),
('farthest', 'adv.＆ adj. → far.', 'F'),
('fascinate', '① v. ئەس-ھوشىنى يوقاتماق، مەستانە بولماق، مەپتۇن قىلماق. ② داڭ قېتىپ قالماق.', 'F'),
('fascinating', 'adj. كىشىنى مەپتۇن قىلىدىغان، ئەس-ھوشىنى يوقىتىپ قويىدىغان.', 'F'),
('fascism', 'n. فاشىزم.', 'F'),
('fascist', 'n.Ⅰ فاشىست، فاشىستلىق. adj.Ⅱ فاشىست.', 'F'),
('fashion', '① n.مودا، يېڭى پاسون، يېڭى نۇسخا. ② ］a  fashion  ياكى       ［ the  fashion  ئۇسۇل، چارە.', 'F'),
('fashionable', 'adj. كەڭ تارقالغان، ئېقىپ يۈرگەن، پاسون بولۇپ قالغان.', 'F')
ON CONFLICT (english) DO NOTHING;

INSERT INTO public.english_uyghur_dictionary (english, uyghur, letter_group) VALUES
('fast', '① adj.Ⅰ چىڭ، قاتتىق، مەھكەم، پۇختا. ② ئىشەنچلىك، سادىق (دوست). ③ ئۆڭمەيدىغان، ئۆچمەيدىغان. ④ تېز، ئىتتىك، چاققان. ① adv.Ⅱ چىڭ، قاتتىق، مەھكەم، پۇختا. ② تېز، ئىتتىك، چاققان، چەبدەس.', 'F'),
('fasten', '① v. چىڭىتماق، چىڭماق. ② مۇقىملاشماق، مۇقىملاشتۇرماق. ③ باغلىماق، باغلانماق، تاڭماق، تېڭىلماق.', 'F'),
('fat', 'n.Ⅰ ياغ، ماي، سېمىز گۆش، بۇلجۇڭ گۆش. adj.Ⅱ سېمىز، مايلىق، ياغلىق. ② قېلىن. ③ مۇنبەت (تۇپراق).', 'F'),
('fatal', '① adj. ئەجەللىك، قاقشاتقۇچ. ② پېشانىگە پۈتۈلگەن، پېشانىدىكى.', 'F'),
('fate', '① n. تەقدىر. ② ھالاكەت، ئۆلۈم، يوقۇلۇش.', 'F'),
('father', '① n. دادا، ئاتا. ② ئاتا-بوۋا، ئەجداد.  ③  <كاتولىك دىنىدا> پوپ. ④ ئىجادكار، كەشپىياتچى.', 'F'),
('father-in-law', '(fathers-in-law      ) n. قېيىناتا.', 'F'),
('fatherland', 'n. ۋەتەن، ئانا ۋەتەن.', 'F'),
('fatigue', 'n.Ⅰ ھاردۇق، دەرمانسىزلىق. v.Ⅱ ھارماق، ھاردۇرماق، چارچىماق، چارچاتماق.', 'F'),
('fatigue', 'ھارماق، چارچىماق', 'F'),
('fatuous', '① نادان، نادانلىق ② ئەخماق، دۆت، كالۋا ③ قوپال، كالانپاي، پالاكەت.', 'F'),
('fault', '① n. كەمچىلىك، نۇقسان، ئەيىب، يېتەرسىزلىك. ② چاتاق، كاشىلا. ③ خاتالىق، قۇسۇر.', 'F'),
('faultless', 'adj. ئەيىبسىز، نۇقسانسىز.', 'F'),
('fauna', 'ھايۋانلار پادىسى، ھايۋانلار توپى', 'F'),
('favo (u) rite', '① n.Ⅰ ئەركە بالا، ئارزۇلۇق بالا، ئالاھىدە ياخشى كۆرىدىغان ئادەم (ياكى نەرسە). ① adj.Ⅱ ئەركە-نايناق، ئەركە، ئامراق، جانىجان، ئالاھىدە ياخشى كۆرىدىغان.', 'F'),
('favo (u) vable', '① adj. ياخشى نىيەتلىك، ياخشى نىيەتتە بېرىلگەن، ياخشى نىيەتتە ئېيتىلغان. ② پايدىلىق. ③ ئەلا. ④ قولايلىق، ئوڭۇشلۇق.', 'F'),
('favo (u)r', '① n.Ⅰ ياخشى نىيەت؛ غەمخورلۇق.② ياردەم، يار-يۆلەك، قوللاش. ③ يان بېسىش. ④ ئارزۇلاش. ⑤ ھەدىيە، سوۋغات، تارتۇق. ① v.Ⅱ قوشۇلماق، قوللىماق، ياقىلىماق، يار-يۆلەك بولماق، ياردەم قىلماق. ② تەقدىم قىلماق، سوۋغات قىلماق، ھەدىيە قىلماق. ③ يان باسماق. ④ پايدىلىق بولماق. ⑤ (جانلىق تىلدا) ئوخشىماق، ئوخشاپ كەتمەك.', 'F'),
('fawn 1', 'كىچىك بۇغا', 'F'),
('fawn 2', '① قۇيرۇق شىپاڭلاتماق ② خۇشامەت قىلماق', 'F'),
('fear', '① n.Ⅰ ۋەھىمە، قورقۇش، تەشۋىش، غەم-غۇسسە. v.Ⅱ قورقماق، ۋەھىمىگە چۈشمەك، غەم قىلماق، قايغۇرماق.', 'F'),
('fearful', '① adj. قورقۇنچلۇق، ۋەھىمىلىك. ② ناھايىتى، ئىنتايىن.', 'F'),
('fearless', 'adj. قورقۇنچسىز، قورقماس، قورقمايدىغان.', 'F'),
('feast', '① n.Ⅰ زىياپەت. ② بايرام، ھېيىت ① v.Ⅱ زىياپەت قىلماق، زىياپەت بەرمەك، زىياپەتكە قاتناشماق. ②راھەت كۆرمەك، كەيپ-ساپا سۈرمەك، ھۇزۇرلانماق. ③ خۇشال-خۇراملىققا چۆممەك.', 'F'),
