('go', 'v. (goes       ؛ went      ؛ gone      ) ① بارماق، ماڭماق، كەتمەك. ② سوزۇلماق، تۇتاشماق. ③ ئايلانماق، ئۆڭمەك. ④ يىقىلماق، ئۆرۈلمەك، بۇزۇلماق، كارىدىن چىقماق. ⑤ جاراڭلىماق. ⑥ مەنسۇپ بولماق، تەئەللۇق بولماق. ⑦ قويماق. ⑧ تارقالماق، ئېقىپ يۈرمەك، يېيىلماق. ⑨        ... ماقچى، ... مەكچى بولماق ①  go  after ‖ قولغا كەلتۈرمەك، تىرىشماق، تىرىشىپ قولغا كەلتۈرمەك. ② قوغلىماق  go  against / قارشى تۇرماق، خىلاپلىق قىلماق  go  all out / بارلىق كۈچى بىلەن، تولۇق غەيرەتكە كېلىپ  go  ahead / ئالدىدا ماڭماق، ئالدىدا تۇرماق، ئالغا باسماق  go  back on      / خىلاپلىق قىلماق؛ خائىنلىق قىلماق ①  go  by / ئۆتمەك. ② ئاساسەن، ئاساسلانماق ①  go  down/ (كېمە) چۆكمەك، چۆكۈپ كەتمەك. ② (شامال، دولقۇن) پەسەيمەك، تىنجىماق. ③ يەتكۈزمەك، يەتكۈزۈپ بەرمەك ①  go  in for / (ئىمتىھانغا) قاتناشماق. ② شۇغۇللانماق، مەشغۇل بولماق، كىرىشمەك. ③ قىزىقماق، ئىنتىلمەك، ھەۋەس قىلماق ①  go  off / (ئوق) ئېتىلماق، پارتلىماق. ② (يېمەكلىك) بۇزۇلماق ①  go  on / داۋاملاشماق، داۋاملاشتۇرماق. ② تۇغۇلماق، پەيدا بولماق  go  out / (ئوت، چىراغ) ئۆچمەك، ئۆچۈپ قالماق  go  over .../ تەكشۈرمەك، تەكرارلىماق ①  go  through / ئۆتكۈزمەك، ئۆتمەك، باشتىن كەچۈرمەك. ② تەپسىلىي تەكشۈرمەك، تەكشۈرمەك  go  through with / ئورۇندىماق، تۈگەتمەك، ئىزچىللاشتۇرماق.', 'G'),
