('if', '① conj. ئەگەر، ئەگەردە، مۇبادا، ناۋادا: I shall see him if he comes. ئەگەر ئۇ كەلسە، مەن (ئۇنى) كۆرىمەن. ② (كۆپ ھاللاردا even بىلەن بىرگە كېلىدۇ) گەرچە... ھالەتتىمۇ، ... تەقدىردىمۇ: courage even  if  we should fail again. We wouldn’t lose يەنە مەغلۇبىيەتكە ئۇچرىغان ھالەتتىمۇ، ھەرگىز بوشىشىپ قالماسلىقىمىز كېرەك. ② (سوراق سۆزلەر بىلەن ئىپادىلىنىدۇ): if he is here. I want to know مەن ئۇنىڭ بۇ يەردە بار-يوقلۇقىنى بىلمەكچى ئىدىم. as  if  ‖ خۇددى، گويا.', 'I'),
