('imitate', 'v. دورىماق، تەقلىد قىلماق، تەقلىد قىلىپ ياسىماق، تەقلىد. قىلىپ ئىشلىمەك.', 'I'),
('immediate', '① adj. دەرھال، شۇئان، تېز، كېچىكتۈرمەي، كېچىكمەي.② بىۋاسىتە، توغرىدىن-توغرا. ③ يېقىن، زىچ، ئەڭ يېقىن.', 'I'),
('immediately', '① adv. دەرھال، شۇئان، تېز، كېچىكتۈرمەي، كېچىكمەي. ② بىۋاسىتە، توغرىدىن-توغرا. ③ يېقىن، يېقىندىنلا.', 'I'),
