('immigrant', 'n. كۆچمەنلەر، كۆچۈپ كىرگەنلەر، چەت ئەلدىن كۆچۈپ كەلگەنلەر.', 'I'),
('immigrate', 'v. كۆچمەنلىك، كۆچۈپ كىرمەك (چەت ئەلدىن)، كۆچۈپ كەتمەك (چەت ئەلگە).', 'I'),
('immortal', 'adj. ئۆچمەس؛ ئۆلمەس.', 'I'),
('impair', '① v. ئاجىزلاشتۇرماق، زەئىپلەشتۈرمەك. ② زىيان يەتكۈزمەك، زىيان سالماق.', 'I'),
('impart', '① v. بەرمەك، بۆلۈپ بەرمەك. ② بىلدۈرمەك، ئۇقتۇرماق، مەلۇم قىلماق.', 'I'),
('impatient', 'adj. تاقەتسىز، سەۋر قىلالمايدىغان، ئالدىراڭغۇ.', 'I'),
('impel', 'v. ( impel  led؛  impel  led؛  impel  ling) ① ئالغا سىلجىتماق؛ تۈرتكە بولماق، ئىلگىرىلەتمەك. ② مەجبۇر قىلماق، زورلىماق.', 'I'),
('imperfect', 'adj. چالا، چولتا، مۇكەممەل بولمىغان.', 'I'),
('imperial', '① adj. ئىمپېرىيىنىڭ؛ جاھانگىر. ② پادىشاھلىق، خانلىق. ③ ھەيۋەتلىك، سەلتەنەتلىك.', 'I'),
('imperialism', 'n. ئىمپېرىئالىزم، جاھانگىرلىك.', 'I'),
