('impetus', '① ( impetus  es       )n. ھەرىكەتلەندۈرگۈچى كۈچ، قۇۋۋەت. ② رىغبەتلەندۈرۈش، ئىلگىرىلىتىش.', 'I'),
('implement 1', 'n.ئەسۋاب،جابدۇق، سايمان، قورال-سايمان.', 'I'),
('implement 2', 'v. ئەمەلگە ئاشۇرماق، ۋۇجۇدقا چىقارماق، ئەمەلىيلەشتۈرمەك: to  implement 2  policies سىياسەتنى ئەمەلىيلەشتۈرمەك.', 'I'),
('implore', 'v. ئۆتۈنۈپ سورىماق، يېلىنماق، يالۋۇرماق.', 'I'),
('imply', 'v. ئىشارەت قىلماق؛ دارىتمىلىماق، پۇرىتىپ قويماق.', 'I'),
('import 1', '① v. ئىمپورت قىلماق. ② دېرەك بەرمەك. ③ ئىزاھلىماق.', 'I'),
('import 2', '① n. ئىمپورت قىلىش. ② (كۆپلۈك ئىشلىتىلگەندە) ئىمپورت قىلىنغان مال. ③ مەنە؛ نىيەت. ④ مۇھىم، مۇھىملىق.', 'I'),
('importance', 'n. مۇھىم، مۇھىملىق، زۆرۈر، زۆرۈرلۈك.', 'I'),
