('impossible', 'adj. مۇمكىن بولمىغان، مۇمكىن بولمايدىغان، ھەقىقەتكە ئۇيغۇن كەلمەيدىغان، ئەقىلگە سىغمايدىغان.', 'I'),
('impress 1', '① v. باسماق، بېسىلماق. ② تەسىر قىلماق، تەسىرلەندۈرمەك. ③ تەسىرات قالدۇرماق.', 'I'),
