('improve', '① v. ياخشىلىماق، ئىسلاھ قىلماق، ئۆزگەرتىش كىرگۈزمەك، يېڭىلىماق، ئىلگىرى سۈرمەك. ② پايدىلانماق، ئىشلەتمەك.', 'I'),
('improvement', 'n. ياخشىلاش، ياخشىلىنىش، ئالغا بېسىش، ئىلگىرىلەش.', 'I'),
('impulse', '① n. تۈرتكە، تۈرتكە بولۇش، ئىلگىرى سۈرۈش، ئىلگىرى سۈرۈش كۈچى، قۇۋۋەت، ئىمپۇلس. ② ئۆزىنى تۇتالماسلىق.', 'I'),
('in', '① prep. (ئورۇننى كۆرسىتىپ، «دا، دە، تا، تە» دېگەندەك قوشۇمچىلار بىلەن ئىپادىلىنىپ، «...نىڭ ئىچىدە، ... نىڭ  in  تەۋەسىدە» ئىكەنلىكىنى بىلدۈرىدۇ):  in the room ئۆيدە  in China / جۇڭگودا. ② (ۋاقىتنى كۆرسىتىپ، «دا، دە، تا، تە» دېگەندەك قوشۇمچىلار بىلەن ئىپادىلىنىدۇ):  in the morning ئەتتىگەندە  in  the evening / كەچتە. ③ جەھەتتە. ④ (ھال ئەھۋال. ياكى ھالەتنى كۆرسىتىدۇ):  be  in  high spirits چەكسىز خۇشاللىققا چۆمگەن ھالدا. ⑤ ھەرىكەت ياكى سەۋەبنى كۆرسىتىدۇ) ... ئۈچۈن، ... سەۋەبىدىن: forget sth.  in  a hurry ئالدىراشلىق تۈپەيلىدىن ... نى ئۇنتۇپ قالماق. ⑥ (شەكىل، ئۇسۇل، چارە-تەدبىر قاتارلىقلارنى كۆرسىتىدۇ): sit  in  a circle. چۆرىدەپ ئولتۇرماق. ⑦ كىيمەك؛ تاقىماق  a student  in  spectacles كۆزەينەك تاقىغان (بىر) ئوقۇغۇچى ① adv. ... ئىچىدە؛ ئۆيدە: — No, he is out. — Is he in ئۇ ئۆيدىمۇ؟ — ياق، ئۇ سىرتقا چىقىپ كەتتى Come  in  please / كىرىڭ. ② يېتىپ بارماق، يېتىپ كەلمەك: The train is  in . پويىز بېكەتكە يېتىپ كەلدى.', 'I'),
('inasmuch', 'adv. چۈنكى، سەۋەبتىن، تۈپەيلىدىن، ... لىقتىن.', 'I'),
('incense', 'n. ئىسرىق، كۈجە؛ پاپىرۇس.', 'I'),
('inch', 'n. ديۇم (فوتنىڭ 12 دىن بىرى).', 'I'),
('incident', '① n.Ⅰ ۋەقە، ھادىسە. ② ئۆزگىرىش. ① adj.Ⅱ ئاسان تۇغۇلىدىغان، ساقلىنىش تەس، خالىي بولۇش قىيىن. ② ئەگىشىپ كېلىدىغان، قوشۇمچە.', 'I'),
('incidentally', '① adv. قوشۇمچە قىلىپ، قىستۇرۇپ، قوشۇپ. ② تۇيۇقسىز، تاسادىپىي.', 'I'),
('incline 1', 'v. قىڭغايماق، قىڭغايتماق، تۆۋەن قىلماق؛ تۆۋەنلىمەك، ئەگمەك، ئىگىلمەك. ② مايىل بولماق، مايىل قىلماق.', 'I'),
('incline 2', 'n. يانتۇلۇق، يانتۇ يۈز، يانتۇ تەكشىلىك.', 'I')
ON CONFLICT (english) DO NOTHING;

