('influence', '① n.Ⅰ تەسىر، تەسىرات، تەسىر كۈچ. ② ھاكىمىيەت، ھوقۇق، ھوقۇق ۋە كۈچ. ③ <ئېلېكتر> ئىندۇكسىيە. v.Ⅱ تەسىر قىلماق.', 'I'),
