('nauseate', '① كۆڭلىنى ئېلىشتۇرماق؛ قۇسقىسىنى كەلتۈرمەك. ② جاق تويدۇرغۇزماق، بىزار قىلغۇزماق ui.② قۇسماق؛ جاق تويماق، زېرىكمەك، نەپرەتلەنمەك (t)', 'N'),
('nauseating', '. كىشىنىڭ قۇسقىسىنى كەلتۈرىدىغان؛ كىشىنىڭ كۆڭلىنى ئېلىشتۇرىدىغان: nauseating food كىشىنىڭ قۇسقىسىنى كەلتۈرىدىغان يېمەكلىك؛ كىشىنىڭ كۆڭلىنى ئېلىشتۇرىدىغان يېمەكلىك  nauseating  gas قۇستۇرغۇچ خاراكتېرلىك گاز. ② كىشىنى زېرىكتۈرىدىغان.', 'N'),
('nauseous', '①. كىشىنى قۇستۇرىدىغان، كىشىنىڭ كۆڭلىنى ئېلىشتۇرىدىغان، ② كىشىنى زېرىكتۈرىدىغان، كىشىنى بىزار قىلىدىغان.', 'N'),
('naval', '① adj.دېڭىز ئارمىيىسىنىڭ. ② ھەربىي پاراخوتنىڭ. ③ ئۇرۇش كېمىسىنىڭ.', 'N'),
('nave 1', 'n. چاق، چىغرىق.', 'N'),
('nave 2', '① n. دەسلەپكى مەزگىلدىكى چېركاۋلارنىڭ مەركىزىي ئىبادەتخانىسى (ئورۇندۇق بار قىسىم). ② (تۆمۈر يول ۋوگزالى قاتارلىق قۇرۇلۇشلارنىڭ) ئوتتۇرىسىدىكى مەيدان، سەينا.', 'N'),
('navel', '①n. كىندىك. ② مەركەز.', 'N'),
('navigability', 'n. (دەريا، دېڭىز ياكى كېمە-قېيىق قاتارلىقلارنىڭ) سەپەرگە مۇۋاپىقلىقلىقى.', 'N'),
('navigate', '①ui. ئۈزمەك، يۈرمەك، سۇدا قاتنىماق؛ ھاۋادا قاتنىماق:  navigate  up a river يۇقىرى ئېقىمغا قاراپ ئۈزمەك. ② (كېمەر ياكى ئايروپىلان قاتارلىقلار)نى ھەيدىمەك. ①ut. يۈرمەك، ئۈزمەك، قاتنىماق cargo ships that can  navigate  inland waters ئىچكى قۇرۇقلۇق سۇ يولىدا قاتنىيالايدىغان يۈك پاراخوتلىرى. ② ھەيدىمەك، باشقۇرماق (كېمە، پاراخوت، ئايروپىلان قاتارلىقلارنى). ③ ئۆتكۈزمەك:  navigate  a bill uhrough Parliment تەكلىپ لايىھىسىنى پارلامېنتتىن ئۆتكۈزمەك.', 'N'),
('navigation', '①n. يۈرۈش، ئۇچۇش، ئۈزۈش؛ دېڭىز قاتنىشى؛ ھاۋا قاتنىشى: aerial  navigation  ھاۋا قاتنىشى inland  navigation  ئىچكى دەريا قاتنىشى.', 'N'),
('navigator', '①n. (كېمە، پاراخوت، ئايروپىلاننىڭ) شوپۇر، يول باشلىغۇچى. ② دېڭىزچى، سۇدا قاتنىغۇچى؛ بۇرۇنقى مەزگىللەردىكى دېڭىز تەۋەككۈلچىسى.', 'N'),
('navy', '① n. دېڭىز ئارمىيىسى. ② قاراكۆك.', 'N'),
('nay', '①d.Ⅰ ياق، ئەمەس. ② شۇنداق بولۇپلا قالماستىن، بەلكى؛ ھەتتا: I suspect,  nay , I am quite sure, that you are mistaken. مەن گۇمانلىنىمەن، ياق، مەن مۇقىملاشتۇرىمەنكى، سەن خاتا قىلدىڭ. It is peculiar,  nay , unique.   بۇ ئالھىدە بولۇپلا قالماستىن، بەلكى تەڭدىشى يوق (بىردىنبىر) ①n.Ⅱ ئىنكار قىلىش، يوققا چىقىرىش، تېنىۋېلىش، رەت قىلىش، ئىنكار قىلىنغان جاۋاب: will not take  nay  ماقۇل بولماسلىققا يول قويماسلىق. ② قارشى ئاۋاز؛ قارشى ئاۋاز بەرگەن كىشى: the nay say and  s قوللاش ۋە قارشى تۇرۇش ئاۋاز سانى. vote among the  nay  s  قارشى ئاۋاز بەرمەك.', 'N'),
('naysay', 'n. رەت قىلىش، ئىنكار قىلىش، تېنىۋېلىش. vt. (naysaid      )      Ⅱ رەت قىلماق، ئىنكار قىلماق، تېنىۋالماق.', 'N'),
('naze', 'n. دېڭىز تۇمشۇقى.', 'N'),
('ne’er', 'never.adv. (شېئىرلاردا)', 'N'),
('ne′er-do-well', ', ne’er-do-well n.Ⅰ يارىماس ئادەم، كارغا كەلمەيدىغان ئادەم. .Ⅱ يارىماس، كارغا كەلمەس، قىممىتى يوق، ئەرزىمەس.', 'N'),
('neap', 'n.Ⅰ كىچىك دولقۇن؛ ئەڭ تۆۋەن دولقۇن .Ⅱ كىچىك دولقۇنلۇق، ئەڭ تۆۋەن دولقۇنلۇق: (a)  neap  tide كىچىك دولقۇن vi.①.Ⅲ (دولقۇنلۇق سۇ كىچىك دولقۇنغا يۈزلەنمەك، كىچىك دولقۇننىڭ ئەڭ يۇقىرى نۇقتىسىغا يەتمەك. ut.② كىچىك', 'N'),
('near', '① adv.Ⅰ يېقىن، يېقىندا، يېقىن ئەتراپ، يېقىن ئەتراپتا: come  near  يېقىن كەلمەك National Day is drawing  near / دۆلەت بايرىمى يېقىنلىشىپ قالدى He lives  near  by. / ئۇ يېقىن ئەتراپتا تۇرىدۇ. prep.Ⅱ يېنىدا، ئەتراپىدا، يېقىن ئەتراپتا، ئۆپچۆرىسىدە:  near  the plant زاۋۇتنىڭ يېنىدا It was  near  six o’ clock. / سائەت ئالتىگە ئاز قالدى. ① adj.Ⅲ يېقىن، سەمىمىي:  a  near  friend   يېقىن دوست. ② يېقىن، يىراق ئەمەس: ◇ The post office is quite  near  پوچتىخانا مۇشۇ ئەتراپتا (پوچتىخانا يىراق ئەمەس) New Year’s Day is  near  . / يېڭى يىل بايرىمى يېقىنلاشتى. ③ سول، سول تەرەپتىكى: the  near  wheel of a car ماشىنىنىڭ سول چاقى. v.Ⅳ يېقىنلاشماق، يېقىن كەلمەك.', 'N'),
('nearly', '① adv. يېقىن، يېقىندا، يېقىندىن. ② تەخمىنەن. ③ دېگۈدەك.', 'N'),
('neat', '① adj. رەتلىك ۋە تازا، رەتلىك ۋە پاكىز. ②كۆركەم، گۈزەل، نەپىس، كېلىشكەن. ③ ئۇستىلىق، ئەپچىللىك، جايىدا. ④ ساپ، تۇتقا (قورالنىڭ).', 'N'),
('neb', '①n. (قۇش، تاشپاقىنىڭ) ئېغىزى؛ (ھايۋان) بۇرنى. ② (ئادەمنىڭ) ئېغىزى (ياكى بۇرنى). ③ ئۇچلۇق ئۇچ، ئۇچ (مەسىلەن، قەلەم ئۇچى).', 'N'),
('nebbish', 'n. قابىلىيەتسىز كىشى، كارغا كەلمەس ئادەم؛ كالۋا ئادەم.', 'N'),
