('necessary', '① adj.Ⅰ زۆرۈر، لازىم، لازىملىق. ② مۇقەررەر. n.Ⅱ لازىمەتلىكلەر.', 'N'),
('necessitate', 'v. زۆرۈرلەشمەك.', 'N'),
('necessitous', '①. نامرات، كەمبەغەل. ② جىددىي. ③ زۆرۈر؛ ساقلانغىلى بولمايدىغان.', 'N'),
('necessity', '① n. لازىم، كېرەك، زۆرۈر، ئېھتىياج. ② لازىمەتلىكلەر. ③ نامراتلىق، كەمبەللىك، غۇربەتچىلىك.', 'N'),
('neck', 'n.بويۇن.', 'N'),
('necklace', 'n. مارجان.', 'N'),
('necrolatry', 'n. ئۆلگۈچىگە بولغان چوقۇنۇش.', 'N'),
('necrology', '①n. ئۆلگۈچىلەر تىزىملىكى. ② ئۆلۈم خەۋىرى؛ مۇسىبەت خەۋىرى، مۇسىبەتلىك خەۋەر.', 'N'),
('necromancer', '①n. ئۆلگۈچى روھىغا دۇئا-تىلاۋەت قىلغۇچى. ② باخشى، داخان، پېرىخون.', 'N'),
('necromancy', 'n. داخانلىق، باخشىلىق، پېرىخونلۇق.', 'N'),
('need', '① n.Ⅰ لازىم، كېرەك، زۆرۈر، ئېھتىياج. ② لازىمەتلىكلەر. ③ نامراتلىق، كەمبەغەللىك، غۇربەتچىلىك. v.Ⅱ لازىم قىلماق، لازىم بولماق، كېرەك قىلماق، كېرەك بولماق، مۇھتاج بولماق. aux.v.Ⅲ لازىم، زۆرۈر، كېرەك Need he go?ئۇنىڭ بېرىشى زۆرۈرمۇ؟ — No, he needn’ t. ياق، (ئۇنىڭ بېرىشى) ھاجەتسىز. (بولۇشلۇق جاۋابى:Yes, he must. توغرا، ئۇنىڭ بېرىشى زۆرۈر.', 'N'),
('needful', 'adj. لازىم، لازىملىق، كېرەكلىك، ئېھتىياجلىق.', 'N'),
('needle', '① n. يىڭنە. ② يىڭنىسىمان نەرسىلەر.', 'N'),
('needless', 'adj. كېرەكسىز، ھاجەتسىز، ئېھتىياجسىز، لازىمى يوق.', 'N'),
('needments', 'n.(سەپەردە بىللە ئېلىپ ماڭىدىغان) لازىمەتلىك بۇيۇملار، سەپەرگە كېرەكلىك نەرسىلەر.', 'N'),
('needn’t', 'need not.', 'N'),
('needs', '］d. ھازىر پەقەر must بىلەن قوشۇپ ئىشلىتىلىدۇ       ［ چوقۇم؛ زۆرۈر، شەرت، كېرەك.', 'N'),
('needy', '. نامرات، كەمبەغەل، يوقسۇل: the poor and  needy  نامرات كىشىلەر.', 'N'),
('nefarious', '. (سۈيىقەست قاتارلىقلار) زەھەرخەندە، قەبىھ، قاباھەتلىك، ئىنتايىن بۇزۇق، ئىنتايىن ئەسكى.', 'N'),
('negate', '①ut. ئىنكار قىلماق، يوققا چىقارماق؛ تېنىۋالماق. ② ئەمەلدىن قالدۇرماق، بىكار قىلماق، ئىناۋەتسىز قىلماق.', 'N'),
('negation', 'n. ئىنكار قىلىش، يوققا چىقىرىش، تېنىۋېلىش؛ ئىنكار قىلىش خاراكتېرلىك سۆز (ياكى تەلىمات). ② ھېچنېمە، ھېچنەرسە، يوقلۇق، بولماسلىق، مەۋجۇت بولماسلىق.       ③ ھۆكۈمنىڭ ئىنكار قىلىنىشى.', 'N'),
('negative', '① adj.Ⅰ ئىنكار، بولۇشسىز. ② پاسسىپ، سەلبىي.  ③ <ماتېماتىكا> مىنۇس.   ④ <فىزىكا> مەنپىي. ① n.Ⅱ ئىنكار سۆز، بولۇشسىز سۆز.   ② <ماتېماتىكا> مىنۇس، مىنۇس سان، مەنپىي سان. ③ (فوتو سۈرەتلەرنىڭ) نېگاتپ. v.Ⅲ ئىنكار قىلماق، رەت قىلماق، تانماق، تېنىۋالماق.', 'N'),
('negativity', 'n. ئىنكارلىق، پاسسىپلىق.', 'N'),
('neglect 1', '① v.Ⅰ بىپەۋارلىق قىلماق، بىخەستەلىك قىلماق، ئېتىبارسىز قارىماق، سەل قارىماق. n.Ⅱ بىپەرۋالىق، بىخەستەلىك، ئېتىبارسىزلىق، سەل قاراش.', 'N'),
('neglecta 2', '①ut.Ⅰ سەل قارىماق، ئېتىبارسىز قارىماق:  neglecta 2  one’s meals and sleep ئۇيقۇ ۋە تاماقنىمۇ ئۇنتۇماق، ئۆزىنى ئۇنتۇغان ھالدا. ② بىپەرۋالىق قىلماق، بىخەستەلىك قىلماق؛ (مەلۇم ئىشنى) قىلىشتىن چۈشۈرۈپ قويماق:  neglecta 2  one’s duties مەسئۇلىيەتكە بىپەرۋالىق قىلماق. I  neglecta 2  ed to wind the clock سائەتنى بۇراشنى ئۇنتۇپ قاپتىمەن n.Ⅱ بىپەرۋالىق، بىخەستەلىك: He showed no  neglecta 2  of duty. ئۇ خىزمەت ئورنىغا بىخەستەلىك قىلغان ئەمەس. in a state of  neglecta 2    باشقۇرىدىغان كىشى يوق ھالەتتە تۇرماق. treat sb. with  neglecta 2    مەلۇم كىشىگە سوغۇق مۇئامىلىدە بولماق.', 'N'),
('neglectful', '. بىپەرۋالىق قىلىدىغان، بىخەستەلىك قىلىدىغان، ئېتىبارسىز قارايدىغان، دىققەت قىلمايدىغان be  neglectful  of one’s appearance:(of) ئۆزىنىڭ يۈرۈش-تۇرۇشىغا دىققەت قىلماسلىق.', 'N'),
('neglige', '①n.Ⅰ       ئاياللارنىڭ ئۇزۇن ئۇيقۇ كىيىمى. ② ئادەتتىكى كىيىم-كېچەك، رەتسىز كىيىم-كېچەك. .Ⅱ كىيىنىشى بىپەرۋا.', 'N'),
('negligence', '①n. بىپەرۋالىق، بىخەستەلىك، بىخۇدلۇق، بىپەرۋا قىلىق:  negligence  of dress كىيىم-كېچىكىگە دىققەت قىلمايدىغان.       ② سەۋەنلىك. ③ (ئەدەبىي ئەسەر قاتارلىقلار) ئۇسلۇبنىڭ جۇش ئۇرۇشى.', 'N'),
('negligent', '. بىپەرۋا، بىخەستە، بىخود: be  negligent  in one’s work خىزمەتتە بىپەرۋا. be  negligent  of one’s duties.   خىزمەت ئورنىدا بىخود.', 'N'),
('negligible', '. ئېتىبارسىز قالدۇرۇشقا بولىدىغان، تىلغا ئالغۇچىلىكى يوق، ھېچنەرسىگە ئەرزىمەيدىغان: a negligible quantityئېتىبارغا ئالماسلىققا بولىدىغان مىقدار(ياكى ئامىل)؛ ئەرزىمەس ئادەم.', 'N'),
('negotiation 1', '① n. سۆھبەت، كېڭەش، مەسلىھەت. ② ئۆتۈنۈش، ئۆتۈنۈپ بېرىش، ئايلىنىش.', 'N'),
('negotiation 2', 'n. سۆھبەت، كېڭەش، مەسلىھەت: enter into  negotiation 2  s (o. open  negotiation 2 s) with sb. مەلۇم كىشى بىلەن سۆھبەتنى باشلىماق. the resumption )suspension) of all-round  negotiation 2  s. تولۇق سۆھبەت ئەسلىگە كېلىش (توختاپ قېلىش). a point of (o. under)  negotiation 2    سۆھبەت ئېلىپ بېرىۋاتقان مەسىلە. be in  negotiation 2  with sb.over sth.   مەلۇم كىشى بىلەن مەلۇم ئىشنى كېڭەشمەك (مەسلىھەتلەشمەك).', 'N'),
('Negress', 'n. ئايال نېگىر.', 'N'),
('Negrillo', 'n. (ئافرىقىنىڭ ئوتتۇرا ۋە جەنۇبىي قىسمىغا ( تارقالغان) بويى پاكار نېگىرلار.', 'N'),
('Negro', '(Negroes) n. نېگىر.', 'N'),
('Negus', 'n. ئېفوفىيە پادىشاھىنىڭ ئاتىلىشى.', 'N'),
('neigh', 'n.Ⅰ (ئات) كىشنەش، كىشنەش ئاۋازى. v.Ⅱ (ئات) كىشنىمەك.', 'N'),
('neigh', 'vi.Ⅰ (ئات) كىشنىمەك؛ ئات كىشنىگەندەك ئاۋاز چىقارماق. n.Ⅱ ئاتنىڭ كىشنىگەن ئاۋازى.', 'N'),
('neighbo(u)r', '① n. قوشنا؛ قوشنا-قۇلۇم، يان، يېنى، يېقىن ئەتراپ.', 'N'),
