('neighbo(u)rly', '. قوشنىلاردەك، ئىناق قوشنىدارلىق بىلەن ئۆتىدىغان، دوستانە.', 'N'),
('neither', 'adj.＆prep. (ئىككىسىدىن) ھېچبىرى، (ئىككىسىدىن) ھېچقايسىسى: Neither answer is correct ئىككى جاۋابنىڭ ھېچقايسىسى توغرا ئەمەس. conj.Ⅱ (nor بىلەن قوشۇپ ئىشلىتىلىپ، ھېچنېمىدىن قورقماسلىق. ئۇمۇ-بۇمۇ بولماسلىققا ئوخشاش ئۇقۇملارنى بىلدۈرىدۇ): Fear  neither  hardship nor death. جاپادىنمۇ، ئۆلۈمدىنمۇ قورقماسلىق I am  neither  for nor against the conclusion./ بۇ خۇلاسىنى يا قوللىمايمەن يا قارشى تۇرمايمەن.', 'N'),
