('nerve', '① n. نېرۋا. ② غەيرەت، يۈرەك، ئىشەنچ.', 'N'),
('nerveless', '①. كۈچى يوق، ماغدۇرسىز؛ جانلىق ئەمەس، تېتىك ئەمەس. ② (ژانىر) چېچىلاڭغۇ. ③ چۈشكۈن، غەمكىن، ئېغىر بېسىق، جىم.       ④ قانات تومۇرى يوق        يوپۇرماق تومۇرى يوق.       ⑤ نېرۋىسىز، نېرۋىسى يوق.', 'N'),
('nervine', '①.Ⅰ نېرۋىنىڭ. ② نېرۋىنى تىنچلاندۇرىدىغان.       n.Ⅱ نېرۋىنى ساغلاملاشتۇرغۇچى دورا.', 'N'),
('nervous', '① adj. نېرۋا. ② نېرۋا سەزگۈرلۈكى ئېشىپ كەتكەن، نېرۋىسى جىددىيلەشكەن.', 'N'),
('nescience', '①n. نادانلىق، بىلىمسىزلىك، ساۋاتسىزلىق. ② agnosticism بىلەن ئوخشاش.', 'N'),
('nescient', '①.Ⅰ نادان، بىلىمسىز، ساۋاتسىز، بىلىمى يوق: be  nescient  of sth. مەلۇم ئىش توغرىسىدا ھېچنەرسىنى بىلمەسلىك. ②agnostic (). بىلەن ئوخشاش.', 'N'),
('ness', 'n. دېڭىز تۇمشۇقى؛ قۇرۇقلۇق تۇمشۇقى.', 'N'),
('nest 1', 'n.Ⅰ ئۇۋا، چاڭگا. v.Ⅱئۇۋا ياسىماق، ئۇۋىلىماق.', 'N'),
('nest 2', '①n.Ⅰ ئۇۋا، چاڭگا؛ كاتەك؛ ئۆڭكۈر، تۆشۈك. ② راھەتلىك جاي؛ تۇرالغۇ جاي، ئۆي؛ يوشۇرۇنۇش ئورنى: a machine-gun  nest 2', 'N'),
('nestle', '①vi. ئازادە ئورۇنلاشماق؛ بىخارامان ياتماق:  nestle  down in bed كارىۋاتتا ئارام ئالماق. ② يېپىشىپ تۇرماق:  nestle up to sb. مەلۇم كىشىنىڭ يېنىغا يېپىشىۋالماق. ③ يېرىم-يارتا كۆرۈنمەك: a village nestling in the valley. تاغ جىلغىلىرىدا يېزىلار يېرىم-يارتا كۆرۈنمەك. ①vt. ئورىماق، قۇچاقلىماق، يۆگىمەك؛ چىڭ چاپلاشتۇرماق: She  nestle d the child’s head close against her. ئۇ بالىسىنىڭ بېشىنى باغرىغا مەھكەم بېسىپ قۇچاقلىدى. ② ئازادە ئورۇنلاشماق، ئارامخۇدا جايلشماق:  nestle oneself in bed ئارامخۇدا كارىۋاتتا ياتماق.', 'N'),
('net', 'n.Ⅰ تور. v.Ⅱ ( net  ted؛  net ted؛  net ting) تور سالماق، تور سېلىپ تۇتماق.', 'N'),
('Netherlander', 'n. گوللاندىيىلىك.', 'N'),
('Netherlandish', '.Ⅰ گوللاندىيىنىڭ، گوللاندىيىلىكنىڭ گوللاندىيە تىلىنىڭ n.Ⅱ گوللاندىيە تىلى.', 'N'),
('nethermost', '. ئەڭ تۆۋەندىكى؛ ئەڭ تېگىدىكى.', 'N'),
('network', 'n. تور، سېتكا، تورسىمان نەرسە: a  network  of railways تۆمۈريول تورى.', 'N'),
('neutral', '① adj. بىتەرەپ، بىتەرەپ مەملىكەت. ② تۇراقسىز، تۇراقلاشمىغان.  ③ <خىمىيە> نېيترال.', 'N'),
('neutron', '〉 n. فىزىكا〈 نېيترون.', 'N'),
('never', 'adv. ئەسلا، ھېچقاچان، ھەرگىز: I have  never  been there. مەن ھېچقاچان ئۇ يەرگە بارغان ئەمەس.', 'N'),
('nevertheless', '① adv.Ⅰئاۋۋالقىدەك، يەنىلا، ھېلىمۇ، ھېلىھەم. ② بىراق، ئەمما، لېكىن. conj.Ⅱ بىراق، ئەمما، لېكىن.', 'N'),
('new', 'adj.Ⅰ يېڭى، يېڭى كۆرگەن. adv.Ⅱ (بىرىكمە سۆز قوشۇمچىسى بولۇپ كېلىدۇ) يېڭىدىن، ئەمدىلا:  new  -laid eggs ئەمدىلا تۇغۇلغان تۇخۇم.', 'N'),
('New Yorker', 'نيويورىك شەھىرى (ياكى شتاتى) كىشىسى.', 'N'),
('newborn', 'adj. يېڭى؛ يېڭى تۇغۇلغان. يېڭىدىن دۇنياغا كەلگەن.', 'N'),
('newcomer', 'n. يېڭى كەلگەن ئادەم، كۆچمەن.', 'N'),
('newish', '. بىرئاز يېڭى، خېلى يېڭى.', 'N'),
('newly', '① adv. يېقىندا، يېقىندىلا. ② يېڭىدىن، يېڭىۋاشتىن.', 'N'),
('news', 'n. (بىرلىك ئورنىدا ئىشلىتىلىدۇ) خەۋەر، يېڭىلىق، ئاخبارات: a piece of  news  بىر يېڭى خەۋەر.', 'N'),
('newsiness', '①n. كۆپ يېڭى خەۋەر. ② گەپدانلىق قىلىش، ۋالاقشىش، ۋاتىلداش.', 'N'),
('newspaper', 'n. گېزىت.', 'N')
ON CONFLICT (english) DO NOTHING;

INSERT INTO public.english_uyghur_dictionary (english, uyghur, letter_group) VALUES
('newsreel', 'n. ھۆججەتلىك فىلىم.', 'N'),
('newton', 'n. نيۇتون (كۈچىنىڭ بىرلىكى).', 'N'),
('Newtonian', '.Ⅰ (ئەنگلىيە فىزىكا ئالىمى) نيۇتون (Newton)نىڭ؛ نيۇتون تەلىماتىنىڭ؛ نيۇتون تەلىماتىغا ئېتىقات قىلىدىغان، n.Ⅱ نيۇتون تەلىماتىنىڭ ئېتىقادچىلىرى.', 'N'),
('next', 'n.Ⅰ كىلەركى، يېقىنقى، يەنە بىرى، تۆۋەندىكى، ئىككىنچى. ① adj.Ⅱ كېلەركى، يېقىنقى، تۆۋەندىكى، ئىككىنچى، كېلەر:  next  year كېلەر يىل. ② يان، قوشنا. ③ باشقا. adv.Ⅲ ئۇنىڭدىن قالسا، ئۇنىڭدىن باشقا.', 'N'),
('nib', 'n. قەلەم ئۇچى.', 'N'),
('nice', '① adj. ياخشى، ئوبدان، كۆڭۈللۈك. ② ئېھتىياتچان، سەزگۈر، ئىنچىكە.', 'N'),
('nicely', 'd.Ⅰ دەللا: fit  nicely  دەللا مۇۋاپىق كەلمەك. ② ئېغىر-بېسىقلىق بىلەن؛ ئېھتىياتچانلىق بىلەن. ③ كىشىنى رازى قىلارلىق ھالدا، كىشىنى خۇشال قىلارلىق ھالدا، ناھايىتى ياخشى ھالدا: The patient is doing  nicely . كېسەل كىشىنىڭ ئەھۋال تەرەققىياتى ناھايىتى ياخشى. .      Ⅱ sسالامەت، ساغلام.', 'N'),
('nicety', '①n. گۈزەللىك، نەپىسلىك؛ نەپىس نەرسە، گۈزەل نەرسە. ② توغرىلىق، ئېنىقلىق:  nicety of one’s powers of observation توغرا كۆزىتىش', 'N'),
('nickel', '〉 n. خىمىيە〈 نىكېل. ② (ئامېرىكىدا) بەش پۇڭلۇق نىكېل تەڭگە.', 'N'),
('nicker', '①vi.Ⅰ (ئات) كىشنىمەك. ② تېلىقىپ كۈلمەك. ①n.Ⅱ ئاتنىڭ كىشنىگەن ئاۋازى. ② تېلىقىپ كۈلۈش.', 'N'),
('nickle', 'n. (ئامېرىكا ۋە كانادانىڭ) بەش پۇڭلۇق نىكېل تەڭگە پۇل.', 'N'),
('nickname', '①n.Ⅰ لەقەم. ② ئەركە ئىسىم ①vt.Ⅱ ... گە لەقەم قويماق؛ لەقەم (ياكى ئەركىلەتمە ئىسىم) بىلەن ئاتىماق.', 'N'),
('nicotian', '.Ⅰ كۆك تاماكىنىڭ n.Ⅱ تاماكا چەككۈچى.', 'N'),
('nicotine', 'n. نىكوتىن، تاماكا ئىشقارى:  nicotine  stained fingers نىكوتىندىن ساغىرىپ كەتكەن قول.', 'N'),
('nicotinism', 'n. تاماكا ئىشقارى بىلەن زەھەرلىنىش، نىكوتىن بىلەن زەھەرلىنىش، تاماكا بىلەن زەھەرلىنىش.', 'N'),
('nictitate', 'vi. كۆزنى چىمچىقلاتماق، كىرپىك قاقماق: nictitating membrane.       كۆزنى يۇمۇپ-ئاچماق.', 'N'),
('nid-nod', '(nid-nodded; nid-nodding vi. (مۈگىدىگەندە) توختىماي بېشىنى سەل بەرمەك، توختىماي سالام قىلماق.', 'N'),
('niddle-noddle', '.Ⅰ (مۈگىدەش قاتارلىق چاغلاردا) ئۈزلۈكسىز بېشىنى سەل بېرىدىغان vt.＆vi.Ⅱ توختىمابېشىنى لىڭشىتماق.', 'N'),
('nidificate', ', nidify      vi. ئۇۋا ياسىماق، چاڭگا سالماق.', 'N'),
('nidus', '(      nidi      O. niduses)①n. ئۇۋا، چاڭگا؛ تۇخۇم باستۇرىدىغان جاي؛        بالىياتقۇ.       ② كېسەل ئوچىقى، كېسەل مەنبىئى. ③ باشلىنىش جايى، پەيدا بولۇش جايى.', 'N'),
('niece', 'n. قىز جىيەن، جىيەن قىزى.', 'N'),
('niff', 'n.Ⅰ      بەدبۇي پۇراق. vi.Ⅱ بەدبۇي پۇراق چىقماق.', 'N'),
('nifty', '①.Ⅰ چىرايلىق، ئۆز، ئېسىل. ② تەمى بار، پۇرىقى بار. ①      n.Ⅱ تەنە گەپ، كىنايە، قىزىقچىلىق قىلىپ ئېيتىلغان گەپ، مازاق گەپ. ② چىرايلىق قىزچاق.  ③ مودا چىرايلىق. نەرسە، مودا خىيال (ئوي).', 'N'),
('niggard', 'n.Ⅰ ئىچى تار ئادەم، پىخسىق ئادەم، بېخىل ئادەم. .Ⅱ ئىچى تار، كۆز كىچىك، پىخسىق، بېخىل.', 'N'),
('niggardly', '①.Ⅰ ئىچى تار، پىخسىق، بېخىل. ② ئىنتايىن ئاز مىقدارلىق: a  niggardly  sum بەك ئاز سان. d.Ⅱ بېخىللىق بىلەن، پىخسىقلىق بىلەن، ئاچكۆزلۈك بىلەن، پىششىقلىق بىلەن.', 'N'),
('niggle', '①vi. كىچىك ئىشلارغا ئەندىشە قىلماق (ياكى ۋاقىت سەرپ قىلماق)؛ تېتىقسىز ئىشلارنى قىلماق. ② چاتاق تاپماق، قۇسۇر چىقارماق. ③ قاسىماق، غاجىلىماق. vt.② پىخسىقلىق بىلەن... بەرمەك، ناھايىتى ئاز مىقداردا... بەرمەك.', 'N'),
('night', 'n. تۈن، كېچە، ئاخشام all  night  (long) ‖ كېچىچە، تۈن بويى at  night  / كېچىچە، كەچ، ئاخشام by  night  / كېچىدە، كەچتە، ئاخشىمى، in the  night  كېچە، تۈن Good  night  ! !/ ياخشى چۈش كۆرۈڭ!', 'N'),
