('nightfall', 'n. گۇگۇم، كەچقۇرۇن، قاش قارايغان چاغ.', 'N'),
('nightingale', 'n. بۇلبۇل.', 'N'),
('nightly', '①.Ⅰ كەچنىڭ، تۈننىڭ. ② ھەربىر كېچىنىڭ:Nightly visits are made by the house physicians. دوختۇرخانىدا تۇرىدىغان ۋراچ ھەر كۈنى كەچتە كېسەل ئۆيلىرىنى كۆزدىن كەچۈرىدۇ.       ③ كېچىنىڭ، كېچىگە ماس كېلىدىغان، كېچىگە مۇۋاپىق. d.Ⅱ كېچىدە، كېچىلىكى؛ ھەر كېچىسى.', 'N'),
('nights', 'd. ھەر كېچىسى؛ ھەرقانداق كېچىدە، ھەرقانداق كېچىلىكى: work hard  nights  s دائىم كېچىسى تىرىشىپ خىزمەت قىلماق.', 'N'),
