('nipple', '①n. ئەمچەك تۈگمىسى؛ رېزىنكە ئېمىزگە، ئېمىزگە قالپىقى. ② (تېرە، مېتال، ئەينەك يۈزى قاتارلىقلارنىڭ) ئەمچەكنىڭ تۈگمىسىمان تومپىيىپ چىقىشى.       ③ بۇرمىلىق ئۇلىغۇچ؛ ئوت پۈرگۈچ چىراق (پېندېڭ) پۈركۈگۈچ ئېغىزى: close  nipple  بۇرمىلىق ئۇلىغۇچ بىلەن ئۇلانغان تۇرۇبا       ④ (مىلتىق-زەمبىرەكنىڭ) ئوق چىقىش ئېغىزى.', 'N'),
('nippy', '①. كىشىگە سانجىلىدىغان؛ سوغۇق جاندىن ئۆتىدىغان. ② بۇرنىنى غىدىقلايدىغان؛ ئۆتكۈر        چەمبەس، چاققان، يېنىك: Look  nippy  دەرھال، چاپسان، چاققان.', 'N'),
('nisus', '］n.بىرلىك، كۆپلۈك ئوخشاش      ［ تىرىشىش، كۈرەش قىلىش، تالىشىش.', 'N'),
('nit 1', '①n. (پىت قاتارلىقلارنىڭ) تۇخۇم؛ لىچىنكا ② بىكار تەلەپ ئەبلەخ، ھارام تاماق.', 'N'),
('nit 2', 'd. ياق، ئەمەس.', 'N'),
('nitery', 'n. كەچلىك كلوب، كەچلىك ئۇيۇشما (nightclub بىلەن ئوخشاش).', 'N'),
('no', '① adj.Ⅰ يوق: He has  no  money ئۇنىڭ پۇلى يوق. ② (قىسقارتىلغان جۈملىلەردە رۇخسەت قىلىنماسلىق، يول قويماسلىق، قارشى تۇرۇش قاتارلىق ئۇقۇملارنى بىلدۈرىدۇ) No parking! ماشىنا (قويۇشقا) توختىتىشقا بولمايدۇ No compromise!/ مۇرەسسە قىلىشقا يول يوق.  adv.Ⅱ (بولۇشسىز جاۋابلارنىڭ ئالدىدا كېلىپ، ياق، بولمايدۇ، يوق دېگەنگە ئوخشاش ئۇقۇملار بىلەن ئىپادىلىنىدۇ): — Will you come? — No, I won’t. سىز كېلەمسىز؟ — ياق، كەلمەيمەن.', 'N'),
