('nobility', '① n. ئالىيجاناب، ئېسىل، يۈكسەك. ② ئاقسۆڭەك، ئاقسۆڭەكلەر (تەبىقىسى).', 'N'),
('noble', '① adj.Ⅰئالىيجاناب، ئېسىل: يۈكسەك.② ئاقسۆڭەك، ئاقسۆڭەكنىڭ. ③ ھەشەمەتلىك، سەلتەنەتلىك، ھەيۋەتلىك. n.Ⅱ ئاقسۆڭەك.', 'N'),
('nobody', 'pron. ھېچكىم، ھېچكىم يوق: ھېچكىم (... ئەمەس).', 'N'),
('nod', '① v. ( nod  ded؛  nod  ded؛  nod ding) بېشىنى لىڭشىتماق. ② مۈگىدىمەك. ③ لىڭشىماق، لىڭشىتماق، مىدىرلىماق، مىدىرلاتماق (گۈل-گىياھ قاتارلىقلار). n.Ⅱ بېشىنى لىڭشىتىش.', 'N'),
('nodal', '. بوغۇمنىڭ؛ تۈگۈننىڭ، دولقۇن رېتىمىنىڭ:  nodal circle دولقۇن چەمبىرى.', 'N'),
