('noddy', '①n. دۆت، دۆتلۈك، كالۋا، كالۋالىق. ② قارا بېلىقئالغۇچ.', 'N'),
('node', 'n. بوغۇم؛ تۈگۈن، مونەك؛ ئۆسمە. ② (ھېكايە، تىياتىر ۋەقەلىكى قاتارلىقلارنىڭ) ئەگرى-توقايلىق، تالاش-تارتىش. ③ مەركىزىي نۇقتا       ④ تۈگۈنچە:  node lymph لىمفا تۈگۈنى. ⑤        كېسىشىش نۇقتىسى.       ⑥ (دولقۇن) پەللىسى:  node  current. توك دولقۇن پەللىسى.       ⑦ تۈگۈن (نۇقتىسى)، كېرىش نۇقتىسى.       ⑧ بوغۇم، ئۈگە، پۇتاق (غولدىكى يوپۇرماق ئۆسىدىغان ئورۇن).', 'N'),
('nog 1', '①n.Ⅰ ياغاچ مىخ، ياغاچ پۇرۇپكا، ياغاچ كېسەك. ② يىلتىزلىق تۈپ؛ قالدۇق غول؛ دەرەخ كۆتىكى ③ ياغاچ قوغتا؛ قوغتا شەكىللىك تىرىگۈچ؛ تۈۋرۈك تەگلىك شىنىسى vt. (nogged; nogging)Ⅱ (ياغاچ تۈۋرۈك بىلەن) تىرىمەك؛ (ياغاچ مىخ بىلەن) مىخلىماق؛ ... نىڭ ياغاچ رامىغا كېسەكنى كېسىپ كىرگۈزمەك:  nog 1 partitions كېسەكنى پارچىلاپ يان تامنىڭ رامى ئىچىگە كىرگۈزمەك، كاۋاك چاممىسىنى قويماق.', 'N'),
('nog 2', 'n. (ئەنگلىيە) كۈچلۈك پىۋە؛ سۈت ۋە تۇخۇم ئارىلاشتۇرۇلغان ھاراق.', 'N'),
('noggin', '①n. كىچىك رۇمكا، كىچىك قەدەھ. ② ئاز مىقداردىكى ئىچىملىك ③ باش، كاللا.', 'N'),
('noise', 'n. قالايمىقان ئاۋاز، يېقىمسىز ئاۋاز، شاۋقۇن، سۈرەن، ۋاراڭ-چۇرۇڭ make a  noise  about sth. ‖ ۋارقىراشماق، ۋاراڭ-چۇرۇڭ قىلماق.', 'N'),
('noisy', 'adj. ۋاراڭ-چۇرۇڭ، قالايمىقان.', 'N'),
