('non-staple', '. مۇھىم ئەمەس:  non-staple  fool )O. foodstuffs. قوشۇمچە يېمەكلىكلەر).', 'N'),
('non-static', '①. تىنچ ئەمەس، تىنچسىز، غەيرىي ستاتىك.       ② ستاتىك زەرەتسىز، ستاتىك زەرەت توپلانمايدىغان       ③  سىمسىز رادىئو كاشىلىسى تۇغۇلمايدىغان.', 'N'),
('nonce', 'n.Ⅰ كۆز ئالدىدا، نۆۋەتتە (پەقەت تۆۋەندىكى قىسقا سۆزلەردىلا ئىشلىتىلىدۇ): for the  nonce . نۆۋەتتە، كۆز ئالدىمىزدا، ۋاقتىنچە، ھازىرچە. .Ⅱ بىر مەھەل يۈز بەرگەن (ياكى ئىشلەتكەن).', 'N'),
('nonchalance', 'n. كۆڭۈل بۆلمەسلىك، كارى بولماسلىق؛ سوغۇق مۇئامىلە قىلىش، سوغۇق مۇئامىلە، ھېچ ئىش بولماسلىق، ھاياجانلانماسلىق، تەسىرلەنمەسلىك: with  nonchalance  قىلچە تەسىر قىلماسلىق، پىسەنت قىلماسلىق، پەرۋايىم پەلەك دەپ يۈرمەك.', 'N'),
('nonchalant', 'كۆڭۈل بۆلمەيدىغان، كارى يوق، سوغۇق مۇئامىلە قىلىدىغان، ھېچ ئىش تەسىر قىلمايدىغان، ھاياجانلانمايدىغان.', 'N'),
('nonclaim', 'n. قانۇن بەلگىلىگەن ۋاقىت ئىچىدە تەلەپ ئوتتۇرىغا قويماسلىق.', 'N'),
('none', 'pron.Ⅰ بىرسىمۇ (يوق)، ھېچكىم، ھېچقايسى، ھېچنېمە: None have arrived yet. تېخى ھېچكىم كەلمىدى I need some paper badly but there is  none  at hand./ ماڭا قەغەز زۆرۈر لازىم بولۇپ قالدى لېكىن ئۆزۈمدە يوق None were left when I came./ مەن كەلگەندە ھېچكىم يوق ئىكەن.The price is  none  too high. adv.Ⅱ ھەرگىز، ھېچ، ھېچقانچە: بۇ باھا ھېچقانچە يۇقىرى ئەمەس.', 'N'),
('nonentanglement', 'n. كىرمەسلىك، ئارىلاشماسلىق؛ چېتىشماسلىق. a policy of  nonentanglement  سىياسەتكە ئارىلاشماسلىق.', 'N'),
('nonentity', '①n. مەۋجۇت ئەمەسلىك، مەۋجۇت بولماسلىق، مەۋجۇت ئەمەس (ياكى ساختا) نەرسە؛        مەۋجۇت ئەمەس ماھىيەت. ② كارغا كەلمەس ئادەم (ياكى نەرسە)، ئەھمىيەتسىز ئادەم (ياكى نەرسە)، كارى چاغلىق ئادەم (ياكى نەرسە): a political  nonentity  سىياسىي جەھەتتە ئەرزىمەس كىشى.', 'N'),
('nonessential', '.Ⅰ ماھىيەتسىز، ئەھمىيەتسىز، ئەرزىمەس، زۆرۈر ئەمەس. n.Ⅱ ئەھمىيەتسىز ئادەم (ياكى نەرسە). بولسىمۇ بولىدىغان بولمىسىمۇ بولىدىغان ئادەم (ياكى نەرسە).', 'N'),
('nonesuch', 'n. تەڭداشسىز ئادەم (ياكى نەرسە)، كۈشەندىسىز ئادەم (ياكى نەرسە).', 'N'),
('nonparty', 'adj.پارتىيىسىز؛ پارتىيە سىرتىدىكى، پارتىيە-گۇرۇھسىز.', 'N'),
('nonsectarian', '. گۇرۇھسىز، ھەرقانداق دىنى مەزھەپكە قارىمايدىغان.', 'N'),
('nonsense 1', 'n. قۇرۇق گەپ، بىكار گەپ، تۇترۇقسىز گەپ، يوقىلاڭ گەپ.', 'N'),
('nonsense 2', '①n.Ⅰ يالغان ئېيتىش، قۇرۇق گەپ؛ ئەسكىلىك (قىلىش)، بېشەملىك (قىلىش)، دۆتلۈك ھەرىكەت: talk  nonsense 2  ئاغزىغا كەلگەننى جۆيلىمەك. I want no more of your  nonsense 2 .   مەن سېنىڭ يەنە بېشەملىك قىلىشىڭغا (ياكى ئاغزىڭغا كەلگەننى جۆيلىشىڭگە) يول قويمايمەن. There is no  nonsense 2  about him.   ئۇ بېشەملىك قىلىشقا ھەرگىز يول قويمايدۇ (ئۇنىڭ ناھايىتى جىددىي ئىكەنلىكىنى بىلدۈرىدۇ). This is nothing short of a  nonsense 2 , a silly  nonsense 2 .   بۇلار پۈتۈنلەي ئاغزىغا كەلگەننى بىلجىرلىغانلىق، دۆتلەرچە بىلجىرلىغانلىق. ② قىممىتى يوق نەرسە، يارىماس نەرسە، كېرەكسىز زىننەت بۇيۇمى int.Ⅱ يالغان! يالغان ئېيتتىڭ! قۇرۇق گەپ!', 'N'),
('nonsensical', '. ئەھمىيەتسىز، ئەھمىيىتى يوق، مەنىسىز، مەنىسى يوق؛ دۆتلەرچە؛ بىمەنە، تېتىقسىز.', 'N'),
('nonsexual', '. جىنىس ئايرىمىسى يوق، جىنىسسىز. nonsignificant      . ئەرزىمەس، ئەھمىيەتسىز، كارى چاغلىق، تىلغا ئالغۇچىلىكى يوق.', 'N'),
('nonsmoker', 'n. تاماكا چەكمەيدىغان ئادەم.', 'N'),
('nonstop', '.Ⅰ توختىمايدىغان، ئۈزلۈكسىز؛ (پويىزدا، ئايروپىلان قاتارلىقلار) ئۇدۇل بارىدىغان، بىۋاسىتە بارىدىغان: a  nonstop  flight. بىۋاسىتە ئۇچماق. a  nonstop  per formance.   ئارىلىقتا ئارام ئالماي ئويۇن قويماق. d.Ⅱ توختىماي، توختىماستىن، ئۈزۈلدۈرمەي، بىۋاسىتە ھالدا.', 'N'),
('nonstriker', '①n. ئىش تاشلاشقا قاتناشمايدىغان ئادەم. ② (تاختا توپدا) قارشى تەرەپتىن كەلگەن توپنى تۇتالمىغان توپ ئۇرغۇچى.', 'N'),
