('noonday', 'n. چۈش: at  noonday . چۈشتە. summer  noonday  heat.   يازنىڭ چۈش ۋاقتىدىكى قاتتىق ئىسسىق.', 'N'),
('nooning', '①n. چۈش، دەل چۈش. ② چۈشلۈك تاماق. ③ چۈشلۈك ئارام.', 'N'),
('noose', '①n.Ⅰ سىرتماق؛ سالما. ② بويۇنتۇرۇق، ئاسارەت، چۈشەك. ③ توزاق، قاپقان، تور، قىلتاق، ئورا:put one’s head in the  noose . ئۆزى تورغا چۈشمەك، ئۆزى قىلتاققا ئىلىنماق ①vt.Ⅱ قىلتاق بىلەن تۇتماق؛ قىلتاققا چۈشۈرمەك. ② (ئارغامچىنى) سالغۇغا ئۆزگەرتمەك. ③ ... نى دارغا ئېسىپ ئۆلتۈرمەك.', 'N'),
('nor', 'conj. (دائىم neither ياكى not بىلەن بىرگە كېلىپ، ... مۇ ئەمەس، ... مۇ يوق دېگەنگە ئوخشاش بولۇشسىز ئۇقۇملار بىلەن ئىپادىلىنىدۇ): Our contry has neither external  nor  internal debts. مەملىكىتىمىزنىڭ دۆلەت ئىچى ۋە سىرتىدىمۇ، ھېچقانداق قەرزى يوق.', 'N'),
('normal', 'adj.Ⅰ نورمال، ئۆلچەملىك، مۇنتىزم: the  normal  temperature نورمال تېمپېراتۇرا ◇ a  normal  school/ سىفەن مەكتەپ. ① n.Ⅱ مۇنتىزم، نورمال ھالەت، تۇراقلىق ھالەت. 〉 ② ماتېماتىكا〈 نورمال.', 'N'),
('north', 'n.Ⅰ شىمال، شىمالىي رايون. adv.Ⅲ شىمالدا، adj.Ⅱ شىمالىي. شىمالغا، شىمال تەرەپتە. شىمال تەرەپكە.', 'N'),
('northeast', 'n.Ⅰ شەرقىي شىمال، شەرقىي شىمال رايون. adj.Ⅱ شەرقىي شىمال. adv.Ⅲ شەرقىي شىمالدا، شەرقىي شىمالغا.', 'N'),
('northern', 'adj. شىمالىي.', 'N'),
