('nose', '① n. بۇرۇن، تۇمشۇق، خارتۇم.follow one’s  nose  ‖ ئۇدۇل ماڭماق poke       one’s  nose  into sb, s business/ باشقىلارنىڭ ئىشىغا ئارىلاشماق، يوقىلاڭ ئىشلارغا ئارىلاشماق. ② پۇراپ سېزىش.', 'N'),
('nostril', 'n. بۇرۇن تۆشۈكى.', 'N'),
('nostrum', '①n. مەخپىي دورا، مەخپىي رېتسېپ؛ پاتېنت ھوقۇقى بار، دورا-دەرمەك. ② جاھانكەشتە تېۋىپ دورىسى.       ③ (ئىجتىمائىي ۋە سىياسىي ئىسلاھات تەرەپلەردىكى) ھەممىگە شىپالىق دورا.', 'N'),
('nosy', '①.Ⅰ چوڭ بۇرۇنلۇق.       ② باشقىلارنىڭ ئىشلىرىنى تىڭ-تىڭلاشقا ئامراق، مۇناسىۋەتسىز ئىشقا ئارىلىشىۋالىدىغان. ③ (ئېچىغان قۇرۇق ئوت-چۆپ قاتارلىقلار) سېسىق پۇراق تارقىتىدىغان؛ سېسىق پۇراققا سەزگۈر. ④ (چاي) پۇراقلىق، مەززىلىك. n.Ⅱ يوغان بۇرۇنلۇق ئادەم، بۇرنى چوڭ ئادەم.', 'N'),
('not', 'adv. (بولۇشسىزلىقنى بىلدۈرىدۇ): I do  not  know. مەن بىلمەيمەن He is  not  a teacher./ ئۇ ئوقۇتقۇچى ئەمەس  not  at all ‖ ھاجەتسىز، ئەرزىمەيدۇ.', 'N'),
('notability', '①n. مەشھۇر ئادەم، ئاتاقلىق ئادەم، داڭلىق كىشى، كاتتا كىشى، كاتتا ئەرباب، كاتتا زات. ② دىققەت قىلىشقا ئەرزىش(خاراكتېر ياكى ئەھۋالنى كۆرسىتىدۇ).', 'N'),
('notable', '① adj.Ⅰ دىققەت قىلىشقا ئەرزىيدىغان. ② كۆزگە كۆرۈنەرلىك، ئاتاقلىق، مەشھۇر. n.Ⅱ مەشھۇر ئادەم، داڭدار شەخس.', 'N'),
('notalgia', 'n. دۈمبە ئاغرىش.', 'N'),
