('notate', 'vt. ... نى بەلگە قىلىپ يازماق.', 'N'),
('notation', '①n. ئالامەت، بەلگە، شەرتلىك بەلگە، نامايەندە؛ ئىپادىلەش ئۇسۇلى، بەلگىلىك ئۇسۇل.       ② بەلگە سېلىش (يېزىش)، بەلگە ئىشلىتىش؛ خاتىرىلەش ئۇسۇلى: decimal  notation  ئونلۇق سىستېما بويىچە ھېسابلاش ئۇسۇلى.       ③ نوتا، نوتا يېزىش (خاتىرىلەش) ئۇسۇلى. ④ ئىزاھات، ئىزاھلاش.', 'N'),
('note', '① n.Ⅰ (دائىم كۆپلۈك ئىشلىتىلىدۇ) خاتىرە: the  note  s of a journey ساياھەت خاتىرىسى. ② (تاشقى ئىشلاردا) نوتا. ③ ئىككى ئىلىك خەت، باغاقچە. ④ ئىزاھات، ئىزاھ. ⑤ چەك؛ قەغەز پۇل. 〉⑥ مۇزىكا〈 نوتا بەلگىسى. ⑦ ئاھاڭ، تون. ⑧ (بېسىلغان، ياكى يېزىلغان) بەلگە. ⑨ نام، ئابرۇي. 01  دىققەت، دىققەت قىلىش. ① v.Ⅱ دىققەت قىلماق. ② خاتىرە يازماق، خاتىرىلىمەك make       a  note ‖ خاتىرە يازماق، خاتىرىلىمەك.', 'N'),
('notebook', 'n. خاتىرە دەپتەر.', 'N'),
('nothing', 'n. ھېچنېمە (يوق)، ھېچبىرى، ھېچقايسىسى (ئەمەس). 〉② ماتېماتىكا〈 نۆل. come to  nothing  ‖ مەغلۇپ بولماق have  nothing  to do with/ ... بىلەن مۇناسىۋىتى بولماسلىق.', 'N'),
('notice', '① n.Ⅰ ئېلان، ئومۇمىي ئۇقتۇرۇش، ئۇقتۇرۇش. ② دىققەت. ③ قىسقا باھا، باھا بېرىش، باھالاش. v.Ⅱ دىققەت قىلماق، دىققەت قىلىپ قارىماق، قارىماق، كۆرمەك.', 'N'),
