('obligation 2', 'n. ۋەزىپە، مەجبۇرىيەت، مەسئۇلىيەت، جاۋابكارلىق.', 'O'),
('obligation3', '① n. (ئەخلاق ۋە قانۇن جەھەتتىكى) مەجبۇرىيەت، بۇرۇچ، ۋەزىپە، مەسئۇلىيەت: perform the proletarian internationalist پرولېتارىيات ئىنتېرناتسىئونالىزملىق بۇرۇچنى ئادا قىلماق. the  obligation3  s of a citizen / گراژدانلارنىڭ مەجبۇرىيىتى a matter of  obligation3  / باش تارتىپ بولمايدىغان ئىش. ② توختام، كېلىشىم، ئاكسىيە. ③ ئىلتىپات، شەپقەت، ياخشىلىق؛ ھېسابنى بۇغماق. ③ ... گە ئىلتىپات قىلماق؛ ... نىڭ تەلىپىگە قوشۇلماق؛ قانائەتلەندۈرمەك: Will you  obligation3  me by closing the windows? ئىلتىپات قىلىپ، مېنىڭ ئۈچۈن دېرىزىنى ئېتىۋەتسىڭىز بولارمۇ؟ Can you  obligation3  me with one or two yuan? Sorry I can’t  obligation3  you. / سەن ماڭا بىر-ئىككى يۈەن پۇل قەرز بېرىپ تۇرالارسەنمۇ؟  ناھايتىى خىجىلمەن، سېنىڭ تەلىپىڭنى قانائەتلەندۈرەلمەيمەن. I’lease  obligation3  me with your presence./ چوقۇم قەدەم تەشرىپ قىلىشىڭىز ئۈمىد قىلىنىدۇ. ④ (مەجھۇل دەرىجىدە ئىشلىتىلىدۇ) تەشەككۈر ئېيتقۇزماق: We are much  obligation3  d to you for your help. ماڭا قىلغان ياردىمىڭگە ئىنتايىن تەشەككۈر ئېيتىمەن.        Much  obligation3  d! / رەھمەت!        ⑤ ... ئۈچۈن ئورۇنداپ بەرمەك: He  obligation3  d us with a song. ئۇ بىزگە بىر ناخشا ئېيتىپ بەردى. vi.② مەلۇم ئىشنى قىلغاندا، ياخشى كۆڭلىنى بىلدۈرمەك: Will you  obligation3  with a song? بىر ناخشا ئېيتىپ بەرسىڭىز بولارمۇ؟', 'O'),
('obligatory', '①adj. ئىختىيارى، خالىسانە، خالىس. ② مەجبۇرىي.', 'O'),
('oblige', '①v. مەجبۇرلىماق، زورلىماق، قىستىماق. ② ياخشىلىق قىلماق، رازى قىلماق، قانائەتلەندۈرمەك، ماقۇل كۆرمەك.', 'O'),
('obligee', 'n. ھوقۇقدار، تۆلىتىۋېلىش ھوقۇقىغا ئىگە كىشى، قەرز ئىگىسى. ( obliger گە قارمۇ قارشى) نەپ ئالغۇچى (obligor گە قارمۇقارشى)', 'O'),
('obliging', 'a. باشقىلارغا ياردەم بېرىشنى خۇشاللىق دەپ قارايدىغان، ئەدەبلىك؛ سەمىمىي: an  obliging  neighbour كىشىلەرگە ياردەم بېرىشنى خۇشاللىق دەپ بىلىدىغان قوشنا  be  obliging  to comrades / يولداشلارغا سەمىمىي بولماق        ② (ئەخلاق ياكى قانۇن جەھەتتە) چوقۇم ئورۇنداشقا تېگىشلىك، ئۆتەشكە تېگىشلىك، مەجبۇرىي خاراكتېرلىك.', 'O'),
('obligor', 'n. مەجبۇرىيەت ئۆتىگۈچى، قەرزدار.', 'O'),
('oblique', '① a.Ⅰ يانتۇلاشقان، قىيسايغان، قىيپاش، قىڭغىر:        an  oblique  compartment قىيپاش يەر شەكلى We set a course  oblique  to the other ships. / بىز باشقا بىر كېمە بىلەن قىيپاش چەتنىگەن سۇ يولىنى ئىشلەتتۇق.         oblique  leaf / قىڭغىر يوپۇرماق (ئىككى تەرىپى سىممېترىك بولمىغان)         oblique  muscles / ئەگرى مۇسكۇل.        ② تىك بۇلۇڭلۇق بولمىغان؛ تىك ئەمەس:  oblique  angle يانتۇ بۇلۇڭ  oblique  cone / قىڭغىر كونۇس. ③ ئەگرى-بۈگرى، تەكشىسىز، ئۇدۇل ئەمەس: make  oblique  accusations قىزىم ساڭا ئېيتاي، كېلىنىم سەن ئاڭلا. make  oblique  thrusts / دارىتمىلىماق، ئەگىتىپ ئېيتماق. ④ ئۆزىنى چەتكە ئالىدىغان، ئۆزىنى قاچۇرىدىغان؛ سەمىمىيەتسىز، ئوچۇق-يورۇق ئەمەس. ⑤ ۋاسىتىلىك:        the  oblique  case ۋاسىتىلىك كېلىش (باش كېلىشتىن باشقا كېلىشلەرنى كۆرسىتىدۇ)         oblique  oration .narration,speech) / ۋاسىتىلىك بايان an  oblique  reference to sth. / مەلۇم ئىشقا قارىتا ۋاسىتىلىك ⑥ (سۈرەت) ھاۋادىن قىيپاش تارتىلغان: an  oblique  aerial photograph قىيپاش ھاۋادىن تارتىلغان سۈرەت. ① vi.Ⅱ يانتۇ، قىيپاش، ئەگمە: The road  oblique  s from the river. بۇ يول دەريا بىلەن ئايرىلىپ كەتتى.  ② يانتۇ ئالغا ئىلگىرىلەش، ئەسلىدىكى يۆنىلىش بىلەن 54° بۇلۇڭ ياساپ ئالغا باسماق. ① n.m قىيپاش نەرسە.  ②  ئەگمەچ مۇسكۇل (بولۇپمۇ قورساق قىسىم مۇسكۇلىنى كۆرسىتىدۇ)  ③ قىيپاش ھاۋادىن تارتىلغان سۈرەت 54° ad.Ⅳ لۇق يەر:  To the right  oblique ,march! ئوڭغا 54° بۇلۇڭ ياساپ ئالغا!', 'O'),
('obliquity', '① n. يانتۇ، يانتۇلۇق دەرىجە، يانتۇ بۇلۇڭ.        ② يانتۇ كېسىشىش: the  obliquity  of the ecliptic قايچا بۇلۇڭ. ③ ئەگرى-بۈگرى؛ (گەپ-سۆز ياكى ھەرىكەت) ئېنىقسىز، ئىلمان؛ تۇتۇق گەپ. ④ ياۋاش ئەمەس؛ يامان، ئەسكى، توغرا ئەمەس.', 'O'),
('obliterate', '① vt. سۈركىمەك، سۈرتىۋەتمەك، ئېرىتىۋەتمەك؛ ... نىڭ دېغىنى چىقىرىۋەتمەك: obliterate one’s signature قويغان ئىمزانى ئۆچۈرۈۋەتمەك.② ئۇنتۇلدۇرماق، كۆمدۈرمەك:  obliterate  stb. from one’s memory مەلۇم ئىشنى ئۇنتۇلماق. ③ يوقاتماق، يوق قىلماق، ئېلىپ تاشلىماق.', 'O'),
('oblivion', '① n. ئۇنتۇش، ئۇنتۇلغان. ② ئۇنتۇلغان ھالەت (ياكى پاكىت):  be rescued from  oblivion  تەلىيىگە ئۇنتۇلۇشتىن ساقلىنىپ قالماق. ③ كۆمۈلۈش، يوقۇلۇش، ئېتىبارسىز قاراش. ④ ئومۇمىي كەچۈرۈم، كەچۈرۈم.', 'O'),
('oblivious', '① a. ئۇنتۇلغان، ئۇنتۇلغاقلىق: be  oblivious  of what has taken place يۈز بەرگەن ئىش ئۇنتۇلۇپ كەتتى. ② پەرۋاسىز، پىسەنتسىز: They are working hard  oblivious  of all fatigue ئۇلار چارچىغىنىغا پىسەنت قىلماي تىرىشىپ ئىشلەۋاتىدۇ be  oblivious  to all the risk / بارلىق خەتەرلىكلەرگە قارىماي.        ③ ئۇنتۇلدۇرۇلغان.', 'O'),
('oblong 1', 'n.Ⅰ تىك تۆت بۇلۇڭ. adj.Ⅱ تىك تۆت بۇلۇڭ، تىك تۆت بۇلۇڭلۇق.', 'O'),
('oblong 2', 'n.Ⅰ تىك تۆت بۇلۇڭ، ئېللىپىس a.Ⅱ تىك تۆت بۇلۇڭ شەكىللىك، ئېللىپىس شەكىللىك، سوزۇق.', 'O'),
('obloquy', '① n. تىللاش؛ كۈچلۈك ئەيىبلەش. ② (كىشىلەر تەرىپىدىن كۈچلۈك ئەيىبلىنىش تۈپەيلىدىن كېلىپ چىققان) يامان ئاتاق، يامان نام، ئۇيات، نومۇس، شەرمەندىلىك.', 'O'),
('obmutescence', 'n. ئۆلسىمۇ ئېڭرىماس.', 'O'),
('obnoxious', 'a. كىشىنى ئىنتايىن خۇشال قىلمايدىغان، كىشىنى زېرىكتۈرىدىغان: an  obnoxious  person كىشىنى بىزار قىلىدىغان ئادەم. ② ئوڭايلا... گە ئۇچرايدىغان:  obnoxious  to harm ئوڭايلا زىيانكەشلىككە ئۇچرايدىغان.        ③ مەسئۇلىيىتى بار. ④ ئەيىبلەشكە تېگىشلىك.', 'O'),
('Oboe', 'n.قوش تىللىق سۇناي، ئوبوۋ.', 'O'),
('obscene', '① a. چاكىنا، بۇزۇق. ② يىرگىنىچلىك، قەبىھ ئىپلاس؛ ئادەمنى يىرگەندۈرىدىغان.', 'O'),
('obscenity', '① n. چاكىنا، بۇزۇق. ② (دائىم كۆپلۈك ئىشلىتىلىدۇ) چاكىنا گەپ-سۆزلەر (ياكى ھەرىكەتلەر).', 'O'),
('obscurant', 'n.Ⅰ جاھالەتچى (مەرىپەتچىلىككە قارشى تۇرۇپ، ئىنسانلارنىڭ ئالغا ئىلگىرىلىشىنى توسىغۇچى كىشىنى كۆرسىتىدۇ) a.Ⅱ جاھالەتپەرەسلىك، نادانلاشتۇرىدىغان.', 'O'),
('obscure', 'adj.Ⅰ قاراڭغۇ، تۇتۇق، خىرە. ② ئۇقۇمسىز، چۈشىنىكسىز، مۈجمەل. ③ نامسىز، نامى چىقمىغان. ①v.Ⅱ قاراڭغۇلاشتۇرماق، مۈجمەللەشتۈرمەك. ② قاپلىماق. ③ قالايمىقانلاشتۇرماق.', 'O'),
('obscurity', 'n. قاراڭغۇ، غۇۋا؛ تۇتۇق. ② مۈجمەل، ئوچۇق ئەمەس، ئۇقۇمسىز، چۈشىنىش تەس:an article full of obscurities بىر پارچە چۈشىنىكسىز ماقالە. ③ كىشىنى جەلپ قىلماسلىق، چەت؛ يوشۇرۇن: retire into  obscurity  خىزمەتتىن چېكىنىپ تەركىدۇنيا بولماق. ④ نامسىز (ئادەم)؛ تۆۋەن (ئادەم)، پەس (ئادەم): sink into  obscurity  نامى ئۆچمەك.', 'O'),
('obsequial', 'a. دەپنە مۇراسىملىق، مۇسبەت قائىدىلىك.', 'O'),
('obsequies', '!n. دەپنە مۇراسىملىرى، مۇسبەت قائىدىلىرى.', 'O'),
('obsequious', '① a. خۇشامەتكارانە، تەخسىكەشچىلەرچە ② (to) ئىتائەتچان، ساداقەتلىك، ۋاپادار.', 'O'),
('observable', '① I a. رىئايە قىلىشقا بولىدىغان، رىئايە قىلىشقا تېگىشلىك. ② تەبرىكلەشكە بولىدىغان، تەبرىكلەشكە تېگىشلىك: an  observable  holiday تەبرىكلەشكە تېگىشلىك بايرام. ③ كۆرگىلى بولىدىغان، كۆزەتكىلى بولىدىغان؛ پەرق ئەتكىلى بولىدىغان: This is an  observable  phenomenon بۇ بىر كۆزەتكىلى بولىدىغان ھادىسە. ④ دىققەت قىلىشقا ئەرزىيدىغان، روشەن. ① n.Ⅱ (بىۋاسىتە ياكى ۋاسىتلىك سەزگىلى (ياكى كۆرگىلى) بولىدىغان شەيئى؛ ھادىسە.        ② دىققەت قىلىشقا ئەرزىيدىغان نەرسە.', 'O'),
('observance', '① n. رىئايە قىلىش، ئىجرا قىلىش (قانۇن، ئۆرپ-ئادەت، قائىدە قاتارلىقلارغا):the strict  observance  of the doctor’s direstions دوختۇرنىڭ تاپىلىغانلىرىغا قاتتىق رىئايە قىلماق. ② خاتىرىلەش، تەبرىكلەش (بايرام، تۇغۇلغان كۈن قاتارلىقلارنى). ③ ئادەت، رەسىم-ئادەت. ④ قائىدە-يۇسۇن، مۇراسىم: social  observance  s ئىجتىمائىي ئالاقە قائىدە-يوسۇنى religious  observance  s / دىنىي مۇراسىم. ⑤ دىققەت، كۆزىتىش. ⑥ دىنىي قائىدە؛        كاتولىك دىنىنىڭ دىنىي تاۋارلارنى تاشلىۋەتمەك (كاپىتالىستلارنىڭ سېتىش مىقدارىنى ئارتتۇرۇش ئۈچۈن، ئىشلىتىشكە چىدامسىز تاۋارلارنى قەستەن ئىشلەپچىقىرىپ، ئۇنى ناھايىتى تېز كاردىن چىقرىش ياكى ۋاقىتنى ئۆتكۈزۈش ھادىسىسىنى كۆرسىتىدۇ).', 'O'),
('observation', '①n. تەكشۈرۈش كۆزىتىش، كۆزىتىپ ئۆلچەش. ② (دائىم كۆپلۈك ئىشلىتىلىدۇ) تەكشۈرۈش خاتىرىسى، كۆزىتىش دولقۇنى. ③ پىكىر، باھالاش، باھا بېرىش.', 'O'),
('observatory', 'n. رەسەتخانا، ھاۋا رايى ئىستانسىسى.', 'O'),
('observe', '①v. تەكشۈرمەك، كۆزەتمەك، ئۆلچىمەك. ② رىئايە قىلماق، ئەمەل قىلماق. ③ تەبرىكلىمەك، مۇبارەكلىمەك. ④ باھالىماق، باھا بەرمەك. ⑤ سۆزلىمەك.', 'O'),
('observer', '①n. كۆزەتكۈچى. ② ئوبزورچى. ③ رىئايە قىلغۇچى، ئىتائەت قىلغۇچى.', 'O'),
('obsolescent', 'a. تەدرىجىي تاشلىۋېتىلگەن، تەدرىجىي ۋاقتى ئۆتىۋاتقان.', 'O'),
('obsolete', '① I a. ئاللا بۇرۇن تاشلىۋېتىلگەن، كېرەكسىز بولۇپ بولغان:an  obsolete  word بىكار قىلىنغان سۆز.② ۋاقتى ئۆتكەن، چىرىپ كەتكەن، كونا شەكىللىك:  obsolete  guns كونا شەكىللىك مىلتىق، زەمبىرەك.      ③(ئەزالىرى)روشەن ئەمەس؛ يېتىلمىگەن، تەرەققىي قىلمىغان. n.Ⅱ تاشلىۋېتىلگەن شەيئى.', 'O'),
('obstacle', 'n. توسالغۇ، توسقۇن: an  obstacle  to progress ئالغا ئىلگىرىلەشنىڭ توسالغۇسى throw  obstacle  s in sb.’s way / مەلۇم كىشىگە توسقۇنلۇق قىلماق There are  obstacle  s to overcome. / يېڭىش زۆرۈر بولغان توسالغۇ.', 'O'),
('obstinacy', 'n. تەرسا، كاج، جاھىل. ② قەيسەر؛ ئاسانلىقچە يېڭىلمەس. ③ (كېسەل، ئاغرىق قاتارلىقلار) داۋالاش تەس، قۇتقۇزۇش تەس، خالاس قىلىش تەس، تېزگىنلەش تەس.', 'O'),
('obstinate', '① a. تەرسالىق، كاجلىق، جاھىللىق، ئۆزگەرمەيدىغان: be  obstinate  in argument مۇنازىرە جەريانىدا ئۆز پىكىرىدە تەرسالىق بىلەن تۇرۇۋالماق. ② قەيسەرانە، ئاسان يېڭىلمەيدىغان:  obstinate  resistance قەيسەرانە تىز پۈكمەس قارشىلىق كۆرسەتمەك. ③ (كېسەل، ئاغرىق قاتارلىقلار) داۋالاش تەس بولغان، قۇتقۇزۇش تەس بولغان، تېزگىنلەش تەسكە چۈشىدىغان:  obstinate  fever ئۇزۇنغىچە يانمايدىغان ھارارەت.', 'O'),
('obstreperous', '① a. ۋاراڭ-چۇرۇڭلۇق، شاۋقۇن-سۈرەنلىك. ② جاھىللىق بىلەن قارشى تۇرىدىغان، پاتىپاراقچىلىق، پاراكەندىچىلىق، بەڭۋاشلىق، بوينى قاتتىقلىق.', 'O'),
('obstruct', '① vt. توسىماق، توسۇلۇپ قالماق، ئەتمەك، ئېتىلىپ قالماق:  obstruct  the tratlic قاتناشنى توسىۋالماق. ② توسىماق، توسىۋالماق، توختاتماق، چەكلىمەك، توسقۇنلۇق قىلماق:  obstruct  sb.in .from doing sth مەلۇم كىشىنىڭ مەلۇم ئىشىنى قىلىشىغا توسقۇنلۇق قىلماق No difficulty can ever  obstruct  the advance of the revolutionary people. / ھەرقانداق قىيىنچىلىقلارنىڭ ھەممىسى ئىنقىلابىي خەلقنىڭ ئالغا بېسىغىنى توسۇپ قالالمايدۇ. ③ توسماق (كۆرۈش سىزىقىنى)؛ توسۇۋالماق. ② توسالغۇ ئورۇنلاشتۇرماق (بولۇپمۇ كۈن تەرتىپ جەريانىدا).', 'O'),
('obtain', '①v. ئىگە بولماق، ئېرىشمەك، مۇيەسسەر بولماق، مۇۋەپپەق بولماق. ② ئېقىپ يۈرمەك، كەڭ تارقالماق (تۈزۈم، ئادەت قاتارلىقلار).', 'O'),
('obtrude', '① vt. سىقىپ چىقارماق، قىستاپ چىقارماق، بۆسۈپ چىقماق. ② تاڭماق، مەجبۇرىي يۈرگۈزمەك:  obtrude  one’s views upon others ئۆزىنىڭ كۆزقارشىنى كىشىلەرگە تاڭماق  obtrude  oneself upon (O. into) / تەرسالىق بىلەن قول تىقىپ ئارىلىشىۋالماق. vi.② كىشىگە تاڭماق؛ بۆسۈپ كىرمەك، پاراكەندە قىلماق:  obtrude  upon sb.’s privacy مەلۇم كىشىنىڭ تىنچلىقىغا پاراكەندىچىلىك سالماق.', 'O'),
('obtruncate', 'v. ... نىڭ باش (ياكى ئۈستى) قىسمىنى كېسىۋەتمەك.', 'O'),
('obtrusion', '① n. كۈچلۈك قىستاش؛ تېڭىش، كۈچلۈك تەلەپ قىلىش: the  obtrusion  of one’s opinions on others ئۆزىنىڭ پىكرىنى كىشىگە تاڭماق. ② بۆسۈپ كىرىش؛ قوپاللىق قىلىش.', 'O'),
('obtrusive', '① a. سوزۇلغان، گەۋدىلىك. ② كۆز-كۆز قىلىنغان، ماختانچىلىق. ③ كىشىنى مەجبۇرلايدىغان؛ بۆسۈپ كىرىدىغان؛ شاللاقلىق.', 'O'),
('obturate', 'vt. (ئېغىز، تۆشۈك قاتارلىقلارنى) ئەتمەك، ياپماق؛ ھىم ئەتمەك، چىڭ ئەتمەك.', 'O'),
('obtuse', '① a. گال، ئۆتمەس، ئىتتىك ئەمەس، ئۆتكۈر ئەمەس: an  obtuse  knife گال پىچاق.        ② ئۆتمەس (بۇلۇڭ):  obtuse  triangle ئۆتمەس بۇلۇڭلۇق ئۈچبۇلۇڭ. ③ (ھېسسىيات، سەزگۈ) گال، ئۆتكۈر ئەمەس؛ كالۋالىق. ④ (تەسىر، تەسىرات قاتارلىقلار) روشەن ئەمەس، (ئاغرىش) جىددىي ئەمەس: an  obtuse  pain بىلىنەر-بىلىنمەس ئاغرىماق. ⑤ (يوپۇرماق ئۇچى) دىقماق، تومپاق شەكىللىك؛ يۇمۇلاق.', 'O'),
('obverse', 'n.Ⅰ (قۇيما پۇل، مېدال قاتارلىقلارنىڭ) ئوڭ تەرىپى؛ (شەيئىلەر ئىككى تەرىپىنىڭ) روشەنرەك يۈزى. ② (شەيئىلەردە بولۇشقا تېگىشلىك) ئۆزئارا قارىمۇ قارشى تەرەپ.        ③ يەڭگۈشلىمە چۈشەندۈرۈش ئۇسۇلى (مەسىلەن، «يېڭىلمەس» دېگەن «ھەربىر جەڭدە چوقۇم يېڭىش»نىڭ يەڭگۈشلىمە چۈشەندۈرىلىشى) ① a.Ⅱ ئىجابىي، روشەن تەرەپلىك؛ قارىمۇ قارشى تەرەپلىك: We must see the reverse as well as the  obverse  side of things. بىز شەيئىلەرنىڭ ئىجابىي تەرىپىنىلا كۆرۈپ قالماستىن، سەلبىي تەرىپىنىمۇ كۆرۈشىمىز كېرەك. ② ئۈستى كەڭ ئاستى تار.        تەتۈر، تەتۈر قويۇلغان.', 'O'),
('obviate', '① vt. يەڭمەك، چەتكە قاقماق، يوقاتماق، تۈگەتمەك:  obviate  difliculties ھەرخىل قىيىنچىلىقلارنى يەڭمەك. ② ئالدىنى ئالماق، مۇداپىئەلەنمەك، ساقلانماق:  obviate  the possibility of a mistake ئىشتىن ئاۋۋال خاتالىشىشنىڭ مۇمكىنچىلىكىنى تۈگەتمەك. سۈمۈرۈپ قالدۇرۇۋالماق.  ④ (ھاۋا قاينىمى قاتارلىقلارنى) قامال قىلماق.  ① ② vi. (چىش) چىشلەشمەك  ② (ھاۋا قاينىمىنى) قامال قىلماق.', 'O'),
('obvious', 'adj. روشەن، ئېنىق، ئوچۇق.', 'O'),
('obviously', 'djv. → obvious', 'O'),
('occasion', '①n. پەيت، پۇرسەت، مەزگىل، ۋاقىت: on  occasion  دائىم، ھەر قاچان، زۆرۈر تېپىلغاندا on the  occasion  of/ ... چاغدا، ... ۋاقىتتا. ② سەۋەب. ③ زۆرۈرىيەت، ھاجەت.', 'O'),
('occasional', '①adj. تاسادىپىي، تۇيۇقسىز، ناۋادا. ② پات-پات، ئارىلاپ-ئارىلاپ.', 'O'),
('occasionally', 'dv.→occasional.', 'O'),
('occult', '① I n. يوشۇرۇنغان، يوشۇرۇن؛ كۆرۈنمەس، كۆرۈنمەيدىغان. ② مەخپىي، ئاشكارا ئەمەس. ③ سىرلىق، ھېكىمەتلىك، تەبىئەتتىن ھالقىغان، چۈشىنىش تەس: the  occult  ares (ئالتۇن تاۋلاش، پىلانتلارنى ئىگىلەش تېخنىكىسى قاتارلىقلارغا قوللىنىلىدىغان) مەخپىي تېخنىكا. ① Ⅱ vt.＆ vi.. مۆكۈندۈرمەك، مۆكتۈرمەك. ② ئوكالت يۇلتۇز.       ］       Ⅲn. ئومۇمىي ئاتىلىشى      ［ سىرلىق ئىش.', 'O'),
('occultation', '① n.يوشۇرۇنۇش، مۆكۈش، غايىب بولۇش، يوقۇلۇش.        ② غايىب يۇلتۇز.', 'O'),
('occultism', '① n. ئىلاھىيەتشۇناسلىق، ئىلاھىيەتشۇناسلىق نەزەرىيىسى سىرلىقلاشتۇرمىچىلىق. ② ئىلاھىيەتشۇناسلىق تەتقىقاتى ۋە ئەمەلىيىتى.', 'O'),
('occupancy', '① n. ئىگىلەش؛ ئىشغال قىلىش؛ ماكانلىشىش. ② ئىگىلەش (ياكى ماكانلىشىش، تۇرۇش) ۋاقتى: during the  occupancy  of a ost ۋەزىپە ئۆتەش ۋاقتىدا. ③ ئىگىلىۋېلىنغان قۇرۇلۇش؛ قۇرۇلۇشنىڭ ئىگىلىۋېلىنغان قىسمى.        ④ ئىگىلەش نىسبىتى.        ⑤ ئىگىلەش.', 'O'),
('occupant', '① n. ئىگىلىۋالغان كىشى، ئىگىلىۋالغۇچى؛ تۇرغۇچى، ئولتۇرغۇچى: the  occupant  of the seat بۇ ئورۇننى ئىگىلىگۈچى كىشى. ② ۋەزىپە ئۆتىگۈچى.', 'O'),
('occupation', '①n. ئىشغال قىلىش، بېسىۋېلىش، ئىگىلەش، ئىشغال قىلىش مەزگىلى. ② تۇرۇش، ئولتۇراقلىشىش، ماكانلىشىش. ③ كەسىپ.', 'O'),
('occupy', 'v. ئىگىلىمەك، ئىگىلىۋالماق، ئىشغال قىلماق، بېسىۋالماق.', 'O'),
('occur', 'v. ( occur red؛ red  occur ring) ① يۈز بەرمەك، تۇغۇلماق، پەيدا بولماق: What has  occur  red? نېمە ئىش تۇغۇلۇپتۇ؟ ② مەۋجۇت بولۇپ تۇرماق. ③ خىيالغا كەلمەك، ئېسىگە كەلمەك، يادىغا يەتمەك.', 'O'),
('occurrence', '①n. يۈز بېرىش، تۇغۇلۇش. ② ۋەقە؛ ھادىسە.', 'O'),
('ocean', '①n. ئوكيان، دېڭىز ئوكيان. ② (جانلىق تىلدا) نۇرغۇن، بىپايان.', 'O'),
('oceanarium', 'n. چوڭ تىپتىكى سۇ ئۈستى ھايۋانات ئۆسۈملۈك كۆرگەزمىخانىسى.', 'O'),
('Oceanian', 'I a. ئوكيانىيىلىك n.Ⅱ ئوكيانىيىلىك ئادەم، ئوكيانىيىلىك.', 'O'),
('oceanic', '① a. ئوكيانىلىق؛ دېڭىز-ئوكياندا ياشايدىغان؛ دېڭىز-ئوكياندا تۇغۇلغان. ② دېڭىز-ئوكياندەك، كەڭرى، چېكى يوق.       ③ ئوكيانىيەنىڭ.', 'O'),
('oceanographer', 'n. ئوكيانىشۇناس.', 'O'),
('Oct.', 'October.', 'O'),
('October', 'n. ئۆكتەبىر.', 'O'),
('odd', '①adj. <ماتېماتىكا> تاق سان، تاق سانلىق. ② تاق. ③ پارچە، پارچە-پۇرات، ئۇششاق-چۈششەك.  ۋاقىتلىق، تۇراقسىز. ⑤ ئاجايىپ، غەيرىي، غەلىتە.', 'O'),
('oddish', 'a. غەلىتىرەك، ئاجايىپراق، ھەيران قالغۇدەك.', 'O'),
('oddity', '① n. غەلىتە، ئاجايىپ-غارايىپ. ② غەلىتە ئادەم، غەلىتە ئىش (نەرسە)؛ غەلىتە خۇمار.', 'O'),
('odo(u)r', '①n. ھىد، بۇي، پۇراق. ② شۆھرەت، ئابرۇي، داڭق، ئاتاق-ئابرۇي.', 'O'),
('of', '①prep(تەۋەلىك، ياكى قاراشلىق مۇناسىۋىتىنى بىلدۈرىدۇ)… - نىڭ، … دىكى: The works of Lu Hsun. لۇشۈن(نىڭ)ئەسەرلىرى the capital  of  China/ جۇڭگونىڭ پايتەختى an appraisal   of  the present situation/ ھازىرقى ۋەزىيەت توغرىسىدىكى مۆلچەر.②(پەرقلەندۈرۈش، مىقدار قاتارلىقلارنى بىلدۈرىدۇ): the majority  of  the masses كۆپچىلىك ئامما، كۆپ ساندىكى ئامما two tons  of  coal / ئىككى توننا كۆمۈر.③(ماتېرىيالنى كۆرسىتىدۇ) ... دىن ياسالغان: made  of  wood ياغاچتىن ياسالغان.④(مەلۇم بىر خىل خۇسۇسىيەت، مەزمۇن، ھالەت قاتارلىقلارنى كۆرسىتىدۇ): a man  of  talent تالانتلىق ئادەم a cup  of  tea/ بىر پىيالە چاي. ⑤ (مەنبەنى كۆرسىتىدۇ):students  of  working classئىشچى ئائىلىسىدىن كېلىپ چىققان ئوقۇغۇچىلار.⑥(سەۋەبنى بىلدۈرىدۇ): die  of  inllness كېسەل سەۋەبى بىلەن ئۆلمەك. ⑦ ھەققىدە، توغرىسىدا، ئائىت: speak  of  sth. بىرەر نەرسە ياكى ئىش ھەققىدە گەپ قىلماق.', 'O'),
('ofay', 'n. ئاق تەنلىك.', 'O'),
('off', '①dv.Ⅰ (مەلۇم سەۋەب ياكى ئارىلىقنى كۆرسىتىدۇ): along way  off  يىراقتا The town is five miles  off / ئۇ شەھەر بەش مىل يىراقلىقتا. ② (مەلۇم نۇقتىدىن يىراقلىشىش ياكى چەتنەشنى كۆرسىتىدۇ): walk off  كەتمەك. ③ (ئۈزۈلۈپ قېلىش، توختاپ قېلىش، ئايرىلىش، سېلىۋېتىش قاتارلىقلارنى كۆرسىتىدۇ): take  off  one’s coat پەلتونى سېلىۋەتمەك. ④ ئاياغلىشىشنى كۆرسىتىدۇ): finish  off  تۈگەتمەك، ئاياغلاشتۇرماق. prep.Ⅱ (مەلۇم نۇقتىدىن يىراقلىشىش ياكى چەتنەشنى كۆرسىتىدۇ)  off  the track رېلىستىن چىقىپ كەتمەك. ① يىراق: the  off  side ئاۋۇ تەرەپ. ② بىكار، ئىشلىمىگەن.دەم ئېلىش كۈنى.', 'O'),
('offence', '① n. چىشىغا تېگىش؛ ئاچچىقىنى كەلتۈرۈش: No  offence  ! سېنىڭ كۆڭلۈڭگە تەگمىدى (ياكى ئەيىبكە بۇيرىماڭ!) give (O.cause)  offence  to sb. / مەلۇم كىشىنىڭ چىشىغا تەگمەك. take  offence  atsth. / مەلۇم ئىش سەۋەبىدىن ئاچچىقلانماق. ② قانۇنغا خىلاپ (ھەرىكەت)؛ جىنايەت؛ خاتالىق: commit an  offence  against a rule قائىدىگە خىلاپلىق قىلماق a military  offence  / ھەربىي قانۇنغا خىلاپ ھەرىكەت. ③ زېرىكەرلىك نەرسە، بىزار بولۇشنى كەلتۈرۈپ چىقىرىدىغان شەيئى: an  offence  to the ear قۇلاقنى يارىدىغان ئاۋاز.  ④ جىنايەت مەنبى؛ توسالغۇ، پۇتلىكاشاڭ. ⑤ ھۇجۇم، زەربە: weapons of  offence  ھۇجۇم قىلىش خاراكتېرلىك قورال. ⑥ ھۇجۇم قىلغان تەرەپ.', 'O'),
('offend', '①v. خىلاپلىق قىلماق، خاتالىق ئۆتكۈزمەك. ② چىشىغا تەگمەك، ئاچچىقىنى كەلتۈرمەك، تېرىكتۈرمەك.', 'O'),
('offender', 'n. چىشقا تەككۈچى، ئاچچىقىنى كەلتۈرگۈچى، چېقىلغۇچى، جىنايەتچى، گۇناھكار: a first (an old)  offender  تۇنجى (تۈزەلمەس) جىنايەتچى.', 'O'),
('offense', 'offence.', 'O'),
('offensive', '①adj.Ⅰ چىشىغا تېگىدىغان، زېرىكتۈرىدىغان، جانغا تېگىدىغان، بىزار قىلىدىغان. ② ھۇجۇم خاراكتېرلىك، زەربە خاراكتېرلىك. n.Ⅱ ھۇجۇم.', 'O'),
('offer', '①v.Ⅰ ئوتتۇرىغا قويماق. ② تەمىنلىمەك، يەتكۈزۈپ بەرمەك، قامدىماق. ③ (باھا) چىقارماق:  offer  a price باھا چىقارماق. ④ تەقدىم قىلماق، بېغىشلىماق، تۆھپە قىلماق. ⑤ سىنىماق، سىناپ كۆرمەك. ⑥ ئۇرۇنماق. ⑦ (پۇرسەت) بولماق، تۇغۇلماق  as accasion  offer  s ‖ پۇرسەت بولسىلا. ①n.Ⅱ تەكلىپ، تەشەببۇس. ② ئوتتۇرىغا قويۇلغان نەرسىلەر.', 'O'),
('office', '①n. ئىشخانا. ② ئىدارە، ئورۇن، خىزمەت ئورنى، باشقارما. ③ (ئەنگلىيىدە) ھۆكۈمەت ئورگىنى، بيۇرو. ④ ھۆكۈمەت خىزمىتى. ⑤ بۇرۇچ، ۋەزىپە، مەجبۇرىيەت. ⑥ (كۆپلۈك ئىشلىتىلىدۇ) ياردەم، ئاتىدارچىلىق.', 'O'),
('officer', '①n. ئوفىتسېر، ھەربىي باشلىق. ② ئەمەلدار، مەنسەپدار.', 'O'),
('official', '①adj.Ⅰ ۋەزىپىدىكى، خىزمەتتىكى. ② رەسمىي. n.Ⅱ ھۆكۈمەت خىزمەتچىسى، ئەمەلدار، مەنسەپدار.', 'O'),
('official ese', 'n. (ھۆكۈمەت سورۇنلىرىدا ئالاھىدە بولىدىغان) خەت-ئالاقە تۈرى.', 'O'),
('officialism', '① n. ئۆلۈك ئورگان ئىستىلى، ئىبوكراتلىق ئىستىل، ئالاقەبازلىق.  ］②ئومۇمىي ئاتىلىشى      ［ ئەمەلدار؛ ھۆكۈمەت سورۇنى.', 'O'),
('officialize', '① vt. رەسمىيلىككە ئايلاندۇرماق؛ رەسمىيەتتىن ئۆتكۈزمەك. ② ھۆكۈمەت تەرەپنىڭ كونترول قىلىشىدا بولماق.', 'O'),
