('old', '①adj.Ⅰ قېرى، ياشانغان. Ⅱ (قانچە ياشقا كىرگەنلىكنى كۆرسىتىدۇ) ... ياش: How  old  are you? قانچە ياشقا كىردىڭىز؟ ③ كونا، قەدىمكى، قەدىمىي. ④ چېنىققان، ئىش كۆرگەن، تەجرىبىلىك. n.Ⅱ قەدىمكى زامان، ئۆتمۈش.', 'O'),
