('omit', 'v. ( omit ted؛  omit ted؛  omit ting) ① قىسقارتماق، ئېلىپ تاشلىماق، چۈشۈپ قالماق، چۈشۈرۈپ قويماق. ② ئۇنتۇماق، ئېسىدىن چىقىرىپ قويماق، بىپەرۋالىق قىلماق.', 'O'),
('omnicompetent', 'a. تولۇق ھوقۇقلۇق.', 'O'),
('omnidirectional', 'a. تولۇق يۆنىلىشلىك.', 'O'),
('omnifarious', 'a. ھەرخىل ھەرياڭزا، خىلمۇخىل.', 'O'),
('omnificent', 'a. چەكسىز ئىجادىي كۈچكە ئىگە.', 'O'),
('omniparity', 'n. ھەممە باراۋەر بولۇش.', 'O'),
('omniphibious', 'a. ھەرقانداق شارائىت ئاستىدا قونالايدىغان.', 'O'),
('omnipotence', '① n. تولۇق قابىلىيەت، چەكسىز ھوقۇق، چەكسىز كۈچ-قۇدرەت. ② تەڭرى.', 'O'),
('omnipotent', 'a.Ⅰ تولۇق قابىلىيەتلىك، تولۇق ئىقتىدارلىق، چەكسىز ھوقۇقى بار، چەكسىز يۇقىرى ئىناۋىتى بار. n.Ⅱ ھەممىگە قادىر.', 'O'),
('on', '①prep.Ⅰ (ئورۇننى كۆرسىتىدۇ) ... نىڭ ئۈستىدە:  a map  on  the wall  تامدىكى خەرىتە. ② (بىرەر نەرسىنىڭ مەلۇم بىر نۇقتا ئەتراپىدا، يېنىدا، چۆرىسىدە ياكى بويىدا ئىكەنلىكىنى كۆرسىتىدۇ):  a city  on  the river دەريا بويىدىكى شەھەر. ③ (يۆنىلىش ياكى نىشاننى كۆرسىتىدۇ): make an attack  on  the enemy دۈشمەنگە ھۇجۇم قىلماق. ④ (ۋاقىتنى كۆرسىتىپ، ئورۇن كېلىش قوشۇمچىلىرى، ... دا، دە، تا، تە قاتارلىقلار بىلەن ئىپادىلىنىدۇ):  on Monday دۈشەنبىدە  on  the 5th of December/ 5-دېكابىردا. ⑤ (... گە ئائىت، توغرىسىدا، تەئەللۇق؛ ... گە چېتىشماق، ... گە تاقالماق دېگەنگە ئوخشاش ئۇقۇملارنى بىلدۈرىدۇ): a book  on  grammar گرامماتىكا كىتابى. ⑥ (ئاساسلىنىش، ئاساس، بويىچە، شەرت قاتارلىقلارنى بىلدۈرىدۇ) ... غا، ... گە ئاساسەن، ... نى ئاساس قىلىپ، ... لىقتىن: rely  on  the masses ئاممىغا تايانماق act  on  principle/ پرىنسىپ بويىچە، پرىنسىپقا ئاساسلىنىپ. ⑦ (مەلۇم بىر خىل ھالەتنى ياكى بىرەر ئىش ھەرىكەتنىڭ ئۆزگىرىۋاتقانلىقىنى بىلدۈرىدۇ):  on  fire ئوت تۇتىشىۋاتقان، ئوت كۆيۈۋاتقان  on  sale/ سېتىلىۋاتقان workers  on  strike/ ئىش تاشلاۋاتقان ئىشچىلار. ①DV.Ⅱ (كىيمەك، تاقىماق، ئاچماق، چاپلىماق قاتارلىق ئۇقۇملارنى بىلدۈرىدۇ): have      one’s coat  on  پەلتونى كىيمەك the bottle has a lable  on / ئۈستىگە ماركا چاپلانغان بوتۇلكا turn  on  the radio/ رادىئونى ئاچماق. ② (ئىش ھەرىكەتنىڭ ئىلگىرىلەش ياكى داۋاملىشىشىنى كۆرسىتىدۇ): further  on  يەنىمۇ ئىلگىرىلىمەك later  on / كېيىنكى چاغلاردا، كېيىنكى كۈنلەرگە كەلگەندە Go  on / (گەپ-سۆز، ئىش ھەرىكەت قاتارلىقلارنى) داۋاملاشتۇرۇڭ! Don’t stop, read  on / توختاپ قالماڭ، ئوقۇۋېرىڭ. ③ (سۇ، گاز، توك ئېقىمى قاتارلىقلارنىڭ ھەرىكەتلىنىۋاتقانلىقىنى بىلدۈرىدۇ): Is the radio off or  on ? رادىئو ئوچۇقمۇ ئۆچۈرۈكلۈكمۇ؟  ④ (ئىش-ھەرىكەتنىڭ بولۇۋاتقانلىقىنى كۆرسىتىدۇ): The battle is  on  ئۇرۇش داۋاملىشىۋاتىدۇ.', 'O'),
('once', '①dv.Ⅰ بىر قېتىم، بىر نۆۋەت، بىر مەرتەم:  once  a year  يىلدا بىر قېتىم. ② (بىرەر ئىش ھەرىكەتنىڭ بولۇپ ئۆتكەنلىكىنى بىلدۈرىدۇ) بۇرۇن: He  once  lived in Urumqi ئۇ بۇرۇن ئۈرۈمچىدە تۇرغان  once again‖؛  once more يەنە بىر قېتىم  once upon a time/ بۇرۇن، قەدىمكى زاماندا. ①conj.Ⅱ بىر كۈنى، كۈنلەرنىڭ بىرىدە، مەلۇم بىر كۈنى: when he  once  underestand بىر كۈنى ئۇ چۈشەنگەندە. ② مۇبادا؛ ھامان.', 'O'),
('one', 'num.Ⅰ بىر، بىر دانە، بىر تال ①adj.Ⅱ (سېلىشتۇرۇشقا ئىشلىتىلىدۇ) بىر تەرەپتىن، بىر باشتىن، from  one  side to the other بىر بېشىدىن يەنە بىر بېشىغىچە. ② (مەلۇم) بىر:  one morning (مەلۇم) بىر كۈنى ئەتىگەن. ③ ئوخشاش. ①pron.Ⅲ (تۇراقسىز ئالماش بولۇپ كېلىدۇ) بىر كىشى، ھەرقانداق ئادەم. ② (سۆزلەرنىڭ تەكرارلىنىشىدىن ساقلىنىش ئۈچۈن ۋە ھالەت ئورنىدا ئىشلىتىلىدۇ: His life was  one  of struggle ئۇنىڭ ھاياتى كۈرەشچان ھايات.', 'O'),
('onion', 'n. پىياز، باش پىياز.', 'O'),
('only', '①adj.Ⅰ بىردىنبىر، ئۆز ئالدىغا، يالغۇز، مۇستەقىل. ② ئەڭ ياخشى، ئەڭ مۇۋاپىق، ماس كېلىدىغان. dv.Ⅱ پەقەت، يالغۇز، ... لا ... not  only  ... but       ... بولۇپلا قالماي بەلكى... conj.Ⅲ لېكىن، ئەمما، بىراق.', 'O'),
('onset', '①n. ھۇجۇم، قاتتىق باشلىنىش. ② قوزغىلىش (كېسەل).', 'O'),
('onward', 'adj. ئىلگىرىلەۋاتقان، ئالغا باسقان.', 'O'),
('opaque', '①adj. تۇتۇق، نۇر ئۆتمەيدىغان. ② قاشاڭ.', 'O'),
('open', '①adj.Ⅰ ئوچۇق. ② كەڭ، ئازادە، بىپايان. ③ ئۈستى ئوچۇق، يوپۇق، يوپۇقسىز (ماشىنا). ④ ئاق كۆڭۈل، ئوچۇق-يورۇق. ⑤ ھەل بولمىغان، بىر تەرەپ قىلىنمىغان. ⑥ ئاشكارا. ⑦ ئىختىيارىي. n.Ⅱ دالا، سەھرا، تالا. v.Ⅲ ئاچماق، ئېچىلماق. ② باشلىماق، باشلانماق. ③ يايماق، يېيىلماق، يېيىلىپ ياتماق  open  out ‖ ئاچماق، يايماق، يېيىلىپ ياتماق، يېيىلماق ① open up/ ئاچماق. ② باشلىماق. ③ پاش بولماق، پاش قىلماق.', 'O'),
('opening', '①n.Ⅰ ئېچىش، ئېچىلىش. ② باشلىنىش، باشلاش. ③ تۆشۈك، ئېغىز، يول. ④ ئورۇن، بوش قويۇلغان ئورۇن، پۇرسەت. adj.Ⅱ ئېچىش، باشلىنىش، باشلاش.', 'O'),
('openly', 'dv. ئاق كۆڭۈل، ئوچۇق-يورۇق؛ سەمىمىي.', 'O'),
('opera', 'n. ئوپېرا.', 'O'),
('operate', 'v. ئايلانماق، ئايلاندۇرماق، ماڭماق، ماڭدۇرماق. ② ئىشلىمەك، رولىنى جارى قىلماق، نەتىجە بەرمەك، نەتىجە چىقماق. ③ ئوپېراتسىيە قىلماق.', 'O'),
('operation', '①n. ئايلىنىش، ھەرىكەتلىنىش.② مەشغۇلات.③ ئەمەلگە ئاشۇرۇش.④ رول، تەسىر.⑤ خىزمەت، كەسىپ، ئىش.⑥ (ھەربىي) مانېۋىر.⑦ <ماتېماتىكا> ئەمەل، ھېساب.', 'O'),
('operator', '①n. ئىشچى، خىزمەتچى. ② ئوپراتور (تېلېفون ئۇلاپ بەرگۈچى). ③ ئوپېراتسىيە قىلغۇچى.', 'O'),
('opinion', '①n. پىكىر، كۆزقاراش، تەشەببۇس. ② ھۆكۈم، باھا.', 'O'),
('opium', 'n. ئەپيۈن.', 'O'),
('opponent', 'n. قارشى تەرەپ، رەقىب.', 'O'),
('opportunism', 'n. پۇرسەتپەرەسلىك، ئوپپورتۇنىزم.', 'O'),
('opportunist', 'n.adj. پۇرسەتپەرەسلىك، ئوپپورتۇنىست.', 'O'),
('opportunity', 'n. پۇرسەت، پەيت.', 'O'),
('oppose', '①v. قارىمۇ قارشى قويماق، قارشى ئورۇنغا قويماق. ② قارشى تۇرماق، قارشى چىقماق، قارشىلىق كۆرسەتمەك.', 'O'),
('opposite', '①adj.Ⅰ نىسبىي، قارىمۇ قارشى. ② ئەكسىچە، تەتۈرىچە. n.Ⅱ قارىمۇ قارشى، قارىمۇ قارشىلىق.', 'O'),
('opposition', 'n. قارشى، قارىمۇ قارشى، قارشىلىق.', 'O'),
('oppress', '① vt. زۇلۇم سالماق، ئەزمەك، باسماق، بۇغماق، باستۇرماق: We firmly support the just struggle of the  oppress  ed people and nations of the world. بىز پۈتۈن دۇنيادىكى ئېزىلگۈچى خەلق ۋە ئېزىلگۈچى مىللەتلەرنىڭ ھەققانىي كۈرىشىنى قەتئىي قوللايمىز. ② بوغماق، چەكلىمەك؛ ئېغىرلىق ھېس قىلدۇرماق؛ زېرىكتۈرمەك، بىئارام قىلماق، تىت-تىت قىلماق: feel  oppress  ed with the heat ئىسسىپ چىدىيالماي كەتمەك.', 'O'),
('oppression', '① n. ئېزىش، زۇلۇم سېلىش، بوغۇش، بېسىش. ② باسقۇچى نەرسە. ③ دىمىق، تىنجىق، بۇرۇقتۇرۇم، پەرىشانلىق.', 'O'),
('oppressive', 'a. ئېزىدىغان، باسىدىغان، چەكلەيدىغان، خارلايدىغان. ② ئېغىر، زېرىكەرلىك، ئىچىنى پۇشۇرىدىغان، چىداش تەس بولغان  oppressive  heat تىنجىق ئىسسىق.', 'O'),
('oppressor', 'n. ئەزگۈچى.', 'O'),
('opprobrious', 'a. ھاقارەتلەيدىغان، ھاقارەتلىك، ئەدەپسىز:  opprobrious  language ئادەم', 'O'),
('optative', 'a.Ⅰ ئىنتىزارلىق، ئىنتىزار بولغان.① n.Ⅱ ئىنتىزارلىق ئىنتوناتسىيە (بولۇپمۇ سانسكرىت، گرېك تىللىرىنىڭ) ② ئىنتىزارلىق ئىنتوناتسىيىسىنى ئىپادىلەيدىغان پېئىل (ياكى پېئىل شەكلى).', 'O'),
('optic', 'a. كۆزنىڭ؛ كۆرۈش كۈچىنىڭ؛ كۆرۈش سېزىمىنىڭ: an  optic  angle كۆرۈش بۇلىڭى  optic  nerves كۆرۈش نېرۋىسى. ② ئوپتىكىلىق، ئوپتىكىنىڭ  ① n.Ⅱ كۆز. ② ئەينەك پلاستىنكا (ئوپتىكا سايمانلىرىدىكى لىنزا ئەينەك، پرىزما ئەينەك قاتارلىقلارنى كۆرسىتىدۇ).', 'O'),
('optical', 'a. كۆزنىڭ، كۆرۈش كۈچىنىڭ، كۆرۈش سېزىمىنىڭ. ② ئوپتىكىلىق، ئوپتىكىنىڭ:  an  optical  gas maskئوپتىكىلىق زەھەردىن قوغدىنىش نىقابى  optical  instruments / ئوپتىكا ئەسۋابلىرى (سايمانلىرى) an  optical  pyrometer / ئوپتىكىلىق تېرمومېتىر an  optical  spectrum / سپېكتر. ③ كۆرۈش كۈچىگە ياردەم بېرىدىغان، كۆرۈش كۈچىگە ياردىمى بار.', 'O'),
('optician', '① n. كۆزەينەك سودىگىرى، ئوپتىكا سايمانلىرى سودىگىرى. ② كۆزەينەك (ياكى ئوپتىكا سايمانلىرى) ياسىغۇچى.', 'O'),
('opticist', 'n. ئوپتىكا مۇتەخەسسىسى، ئوپتىكىست.', 'O'),
('optics', '］ n. بىرلىك ياكى كۆپلۈك سۈپىتىدە      ［ ئوپتىكا.', 'O'),
('optimal', 'a. ئەڭ مۇۋاپىق، ئەڭ كۆڭۈلدىكىدەك، كىشىنى ئەڭ قانائەتلەندۈرىدىغان (رازى قىلىدىغان).', 'O'),
('optimism', 'n. ئۈمىدۋارلىق، ئوپتىمىزم: revolutionary  optimism  ئىنقىلابىي ئۈمىدۋارلىق', 'O'),
('optimistic (al)', 'a. ئۈمىدۋار، ئوپتىمىستىك، ئوپتىمىزملىق.', 'O'),
('optimize', 'vi.① ئۈمىدۋارلىقنى بىلدۈرمەك (ئىپادىلىمەك):  optimize  about the future كەلگۈسىگە نىسبەتەن ئۈمىدۋارلىقىنى بىلدۈرمەك. vt.② دەپتىرى (Order Paper بولۇپمۇ كېلىدۇ).        ③ بۇيرۇق دەپتىرى.', 'O'),
('or', '①conj. (تاللاشنى كۆرسىتىدۇ) ياكى: tomorrow  or on Sunday ئەتە ياكى يەكشەنبە كۈنى. ② (دائىم else بىلەن قوشۇپ ئىشلىتىلىدۇ) ئۇنداق بولمىسا، ئۇنداق قىلمىغاندا: Hurry up,  or  (else) you’ll be late. چاققان بول، بولمىسا كېچىكىپ قالىسەن.', 'O'),
('oral', '①adj. ئېغىزچە، ئاغزاكى. ② ئېغىز، ئېغىز قىسىملىرىدىكى.', 'O'),
('orange', '①n.Ⅰ جۈزە، ماندارىن. ② قىزغۇچ سېرىق. adj.Ⅱ قىزغۇچ سېرىق.', 'O'),
('orb', 'n. شار، ئاسمان جىسىملىرى.', 'O'),
('orbit', 'n.Ⅰ <ئاسترونومىيە> ئوربىتا. v.Ⅱ ئوربىتانى بويلاپ ئۇچماق.', 'O'),
('orchard', 'n. مېۋىلىك باغ.', 'O'),
('orchestra', '①n. ئوركېستىر. ② (تىياتىرخانىلاردا) سازەندىلەر ئورنى.', 'O'),
('ordain', '①v. يېزىلماق، پۈتۈلمەك، بەلگىلىمەك. ② (دىن) پوپ تەيىنلىمەك.', 'O'),
('order', '①n.Ⅰ تەرتىپ. ② رەتلىك. ③ دائىملىق ھالەت (خىزمەتنىڭ). ③ ئامانلىق. ④ يىغىن تەرتىپى. ⑤ بۇيرۇق. ⑥ زاكاز قىلىش، بۇيرۇتۇش. ⑦ خۇيلانغان پۇل ھۆججىتى. ⑧ مۇددىئا، نىشان: in  order  to (that) ... مەقسىتىدە، ئۈچۈن. ①v.Ⅱ بۇيرۇماق، پەرمان بەرمەك. ② زاكاز قىلماق، بۇيرۇتماق.', 'O'),
('orderliness', '① n.پاكىز بولۇش؛ رەتلىك بولۇش. ② تەرتىپلىك بولۇش، ئىنتىزامغا رىئايە قىلىش.', 'O'),
('orderly', '① a.Ⅰ پاكىز، رەتلىك، قائىدىلىك: an  orderly  desk رەتلىك، پاكىز يېزىق جوزىسى The room is in  orderly  condition. / ئۆي ئىچى رەتلىك پاكىز بولماق        an  orderly  bin / (يول بويىدىكى) كېرەكسىز نەرسىلەر ساندۇقى.  an  orderly  person / قائىدىلىك ئادەم. ② تەرتىپلىك، ئىنتىزامچان: intense but  orderly  work جىددىي ئەمما تەرتىپلىك خىزمەت قىلماق an  orderly  crowd / ئىنتىزامچان ئادەم توپى.         ③ بۇيرۇقنىڭ يەتكۈزۈلۈش (ياكى ئىجرا قىلىنىش) توغرىسىدىكى: an  orderly  book بۇيرۇق دەپتىرى an  orderly  man / بۇيرۇق يەتكۈزگۈچى ئەسكەر an  orderly  officer / نۆۋەتچى ئوفىتسېر an  orderly  room / (ھەربىي گازارما ئىچىدىكى) كۇتۇپخانا        ① n.Ⅱ بۇيرۇق يەتكۈزگۈچى ئەسكەر، خىزمەتكار، خەۋەرچى. ② كۈتكۈچى، قارىغۇچى، خەۋەر ئالغۇچى (ھەربىي دوختۇرخانىلاردىكى)؛ خىزمەتچى ئىشچى، چاكار: a meaical  orderly  تازىلىق خادىمى، تازىلىق ئىشچىسى. ① ad.Ⅲ تەرتىپلىك ھالدا. ② تەرتىپ-ئىنتىزام بىلەن، مۇۋاپىق ھالدا. ③ قائىدىلىك بىلەن، قائىدىلىك ھالدا.', 'O'),
('ordinal', '① a.Ⅰ ئارقا-ئارقىدىن، ئارقىمۇ ئارقا، تەرتىپلىك:  ordinal  num bers دەرىجە سان (مەسىلەن: first, second, twentieth قاتارلىقلار). ② «تۈركۈم»نىڭ ① n.Ⅱ دەرىجە سان.              ② رەسىم-قائىدەنامە؛ مۇقەددەس ۋەزىپە تاپشۇرۇپ بېرىش مۇراسىمنامىسى؛ تولۇقلاش، ئېلىپ تاشلاش نىزامنامىسى.', 'O'),
('ordinance', '① n. پەرمان، ئەمىر-پەرمان؛ نىزام؛ قائىدە: a government  ordinance  ھۆكۈمەت پەرمانى. ② مۇراسىم، رەسىم-يوسۇن (بولۇپمۇ پەيغەمبەر تامىقى كۆزدە تۇتىلىدۇ). ③ ئەنئەنىۋى ئۆرپ-ئادەت، ئەنئەنىۋى قائىدە-يوسۇن. ④ (ئىلاھ ياكى تەقدىر) پۈتكەن ئىش.', 'O'),
