('organization', '①n. تەشكىللەش، تەشكىللىنىش، تۈزۈش، تۈزۈلۈش، ئۇيۇشتۇرۇش. ② تەشكىلات، ئورگان، كوللېكتىپ.', 'O'),
('organize, organise', 'v. تەشكىللىمەك، ئۇيۇشتۇرماق، قۇرماق، تۈزىمەك.', 'O'),
