('orgulous', 'a. تەكەببۇر، تەكەببۇرلۇق قىلىدىغان؛ مەغرۇر، مەغرۇرلۇق قىلىدىغان، ئۆزىنى چوڭ تۇتىدىغان.', 'O'),
('orient', 'n. (شېئىر سۆزى) شەرق.', 'O'),
('orientation', 'n. يۆنىلىش، تەرەپ، نىشان.', 'O'),
('origin', '①n. مەنبە، كېلىش مەنبەسى. ② كېلىپ چىقىش، باشلىنىش. ③ قانداشلىق.', 'O'),
('original', '①adj.Ⅰ ئەسلى، ئاۋۋالقى، دەسلەپكى، تۇنجى، قەدىمكى، ئىپتىدائىي. ② ئۆزىگە خاس. ③ يېڭى، يېڭىچە. ①dv.Ⅱ يېڭىچە، ئۆزىگە خاس. ② دەسلەپتە. n.Ⅲ دەسلەپكى ماددا.', 'O'),
('originality', '① n.ئىجادىي كۈچى، ئۆزگىچە خاسلىق، ئىجادىي قاراش؛', 'O'),
('originate', '①v. كېلىپ چىقماق، پەيدا بولماق، باشلانماق، تۇغۇلماق. ② ئىجاد قىلماق، قۇرماق، تەسىس قىلماق، ئاچماق.', 'O'),
('ornament', '①n.Ⅰ پەرداز، زىننەت، زىننەت بۇيۇملىرى، زىبۇ-زىننەت. ② شەرەپ؛ شان-شەرەپ كەلتۈرگۈچى. v.Ⅱ زىننەتلىمەك، بېزىمەك، ياسىماق، پەردازلىماق.', 'O'),
('ornamentation', '① n. زىننەتلەش، بېزەش، ياساش،تۈزەشتۈرۈش. ② زىننەتلەش بۇيۇملىرى، بېزەك. ③ زىننەتلەش ھۈنەر-سەنئىتى.', 'O'),
('ornate', '① a. ھەشەمەتلىك بېزەلگەن؛ زىيادە بېزەلگەن. ② (ژانىر) ھەشەمەتلىك، پۇزۇر؛ ھالى چوڭ، ھال تارتىدىغان.', 'O'),
('ornery', '① a. مىجەزى ئەسكى، ئۇرۇشقاق، جوداكەش. ② پەسكەش، رەزىل.', 'O'),
('orphan', 'n. يېتىم، يېتىم بالا.', 'O'),
('orphanage', '① n.يېتىملىك سالاھىيەت، يېتىم ھالەت. ② دارىلئېتام. ］ ③ ئومۇمىي ئاتىلىشى      ［ يېتىم، يېتىم بالا.', 'O'),
('orphanize', 'vt. يېتىم قىلماق، يېتىم قىلدۇرماق.', 'O'),
('osteitis', 'n. سۆڭەك ياللۇغى.', 'O'),
('ostensible', '① a. ئاشكارىلاشقا بولىدىغان، ئوچۇق، روشەن، شۈبھىسىز: have different  ostensible  properties ئېنىق ئوخشىمايدىغان ئالاھىدلىككە ئىگە. ② سىرتقى، يۈزەكى، يالغاندىن: one’s  ostensible  motive (purpose) يۈزەكى مۇددىئا، غەرەز، نىيەت (مەقسەت).', 'O'),
('ostensive', '① a. ئېنىق (ياكى بىۋاسىتە) ئىپادىلەنگەن. ② سىرتقى، يۈزەكى، يالغاندىن. ③ بىۋاسىتە ئىسپاتلانغان.', 'O'),
('ostentation', 'n. مۇبالىغە قىلىپ كۆرسىتىش، كۆپتۈرۈش، كۆرەڭلەش، كۆز-كۆزقىلىش؛ بۇزۇپ-چېچىش، شۆھرەتپەرەسلىك: detest  ostentation  in any form ھەرقانداق ساختىپەزلىكلەرگە نەپرەتلەنمەك (ئۆچەكىمەك) be free from individual heroism and  ostentation  شەخسىي قەھرىمانلىق ۋە شۆھرەتپەرەسلىك يوق بولماق.', 'O'),
('ostentatious', 'a. مۇبالىغە قىلغان، كۆپتۈرۈلگەن، كۆز-كۆز قىلىنغان، ساختىلىققىلىنغان، كۆز-كۆز قىلىنغان.', 'O'),
('otalgia', 'n. قۇلاق ئاغرىش.', 'O'),
('other', 'adj.pron. باشقا، يەنە، بۇندىن باشقا each  other ‖ every  other / بىرنى قويۇپ، ئارىلاپ no  other  than / باشقىسى ئەمەس، دەل (شۇ) one after the  other / ئارقا-ئارقىدىن، بىرىنىڭ كەينىدىن بىرى.', 'O'),
('otherness', '① n. باشقا بىر، باشقا، ئوخشاش ئەمەس.② باشقابىر نەرسە، ئوخشاش ئەمەس نەرسە. ad. باشقا ئورۇندا، باشقا ئورۇنغا.', 'O'),
('otherwhile(a)', '①  ad. باشقا بىر ۋاقىتتا. ② بەزىدە.', 'O'),
('otherwise', '① ad.Ⅰ باشقا، باشقىچە، بۆلەك، بۆلەكچە: He thinks  otherwise  ئۇ ئۇنداق دەپ تونىمايدۇ. He is  otherwise  engaged. / ئۇنىڭدا باشقا بىر ئىش بار. Liupan Mountain,  otherwise  called Lung Shan / ليوپەنشەن تېغىنىڭ يەنە بىر ئىسمى — لوڭ شەن I could do no  otherwise  than laugh. / كۈلمەسلىكىمگە بولماي قالدى؛ كۈلمەسلىكىمگە نېمە ئامال. ② باشقا تەرەپلەردە (جەھەتلەردە): The article is long, but not  otherwise  blameworty. بۇ ماقالە ئۇزۇن، باشقا تەرەپلەردە ياخشى ئەمەس دېگۈچىلىك يېرى يوق. an  otherwise  perfect picture. / ئەگەر مەلۇم بىر كەمچىلىكى تۈزۈتىلسىلا مۇكەممەل نۇقسانسىز بىر پارچە رەسىم بولىدۇ. ③ بولمىسا، يا بولمىسا؛ ئۇنداق بولمىسا، ئۇنداق بولمىغاندا: He reminded me of what I shoud  otherwise  have forgotten. ئۇ مېنىڭ يادىمغا كەلتۈرۈپ قويدى. بولمىسا، بۇ ئىشنى ئۇنتۇلۇپ كەتكەن بولاتتىم. We must conscientiously study Marxism. Leninism adn Chairman Mao’s works, (or) otherwise we’ll lose our bearings. بىز ماركسىزم-لېنىنىزم، ماۋجۇشى ئەسەرلىرىنى ئەستايىدىل ئۆگىنىشىمىز كېرەك، ئۇنداق بولمىسا، نىشاندىن ئادىشىپ قالىمىز. ① a.Ⅱ باشقىچە، بۆلەكچە، ئۇنىڭغا ئوخشىمايدىغان: if conditions were  otherwise مۇبادا ئەھۋال ئۇنداق بولمايدىغان بولسا. Our struggle cannot be  otherwise  than wictorious. / بىزنىڭ كۈرىشىمىز چوقۇم غەلبە قىلىدۇ. ② باشقا تەرەپلەردە، باشقا تەرەپلەردىكى: sb.’s  otherwise  equals باشقا تەرەپلەردە مەلۇم كىشى بىلەن ئۆزئارا يۇقىرى-تۆۋەنلىكى يوق كىشى. His students in Chinese literature are also his  otherwise  teachers. / بۇ كىشىلەر جۇڭگو ئەدەبىياتى تەرەپلەردە ئۇنىڭ ئوقۇغۇچىسى، ئەمما باشقا تەرەپلەردە بولسا، ئۇنىڭ ئوقۇتقۇچىسى.', 'O'),
('otherword', 'n. ئاخىرەت، ئۇ دۇنيا.', 'O'),
('otherworldly', '① a. ئاخىرەتنىڭ، ئۇ دۇنيانىڭ. ② ئاخىرەتكە تەييارلىق قىلىشتىكى.', 'O'),
('ought', '］ aux.a.Ⅰ ھالەت ۋە شەخس ئۆزگىرىشى يوق، پېئىل تۇراقسىز شەكلى كەينىگە ئۇلىنىدۇ       ① مەسئۇلىيەت، جاۋابكارلىق، ئۇيغۇنلۇق، ماسلىق، مۇناسىپلىق، بابلىق، مۇمكىنچىلىق قاتارلىقلارنى بىلدۈرىدۇ.       ② پېئىل تۇراقسىز شەكلىنىڭ تاماملىنىش شەكلى ئاخىرىغا ئۇلىنىدۇ      ［ بۇرۇنلا شۇنداق بولىشى كېرەك ئىدى. ئەسلى شۇنداق بولۇشى لازىم (تېگىشلىك) ئىدى. ئەسلىدە زۆرۈر ئىدى. You  ought  to have done the work yesterday. سەن بۇ خىزمەتنى تۆنۈگۈن ئىشلەپ تۈگىتىشىڭ لازىم ئىدى. The child  ought  not to have been allowed to go alone. / ئەسلىدە بۇ بالىنى بارغۇزماسلىق كېرەك ئىدى. n.Ⅱ ئادا قىلىشقا تېگىشلىك بۇرچ، مەسئۇلىيەت.', 'O'),
('oughtn’t', 'ought not.', 'O'),
('ounce', 'n. ئۇنسىيە (4.28 گرامغا توغرا كېلىدىغان ئېغىرلىق ئۆلچەم بىرلىكى).', 'O'),
('our', 'we］ pron. نىڭ ئىگىلىك كېلىشى ①       Our Saviour ./ ئىيسائەلەيكسالام.', 'O'),
('ours', 'pron. (we نىڭ ئىسىم خاراكتېرلىك ئىگىلىك ئالماش شەكلى) بىزنىڭ، ئۆزىمىزنىڭ.', 'O'),
('ourself', '］pron. ئۆزلۈك ئالماش ①      ［ (گېزىت-ژۇرنال مۇھەررىرلىرى قاتارلىقلار قوللىنىدىغان سۆز) بىز ئۆزىمىز (ourselves بىلەن ئوخشاش). ② (خان-پادىشاھلار رەسمىي سورۇنلاردا myself نىڭ ئورنىغا ئىشلىتىلىدۇ) پېقىر ئۆزى.', 'O'),
('ourselves', '］① pron. ئۆزلۈك ئالماش      ② سۆز ئورامىنى كۈچەيتىدۇ      ④ be, become, come to قاتارلىقلارنىڭ كەينىدە ئىشلىتىلىدۇ      ［ بىزنىڭ نورمال ئەھۋالىمىز (سالامەتلىك، كەيپىيات قاتارلىقلارنى كۆرسىتىدۇ): Wound healed, we are quite  ourselves  again. جاراھەت ساقايغاندىن كېيىن بىز ھەممىمىز يەنە بۇرۇنقىدەك ساغلام بولۇپ كەتتۇق.', 'O'),
('ourselves', 'pron. ئۆزىمىز: we do everything  ourselves . بىز ھەممە ئىشنى ئۆزىمىز قىلىمىز.', 'O'),
('oust', '① vt. قوغلاپ چىقارماق، ھەيدەپ چىقارماق، سۈرۈپ چىقارماق. قوغلىماق، ھەيدىمەك، سۈرمەك:  oust  sb.from office مەلۇم كىشىنى خىزمەتتىن ھەيدەپ چىقارماق (بوشاتماق). ② تارتىۋالماق، مەھرۇم قىلماق (of) ③ ئورنىنى باسماق، ئورنىنى ئىگىلىمەك: Take care that quantity does ont  oust  quality سان قوغلاشماستىن سۈپەتكە دىققەت قىلىش كېرەك.', 'O'),
('ouster', '① n. قوغلاپ چىقىرىش، ھەيدەپ چىقىرىش، قوغلاش، ھەيدەش.', 'O'),
('out', '①adj.Ⅰ (سىرتقا چىققانلىقنى، سىرتتا ئىكەنلىكنى، ۋەزىپىسىدە ئەمەسلىكنى ياكى نورمال بولمىغان ھالەتتە ئىكەنلىكنى بىلدۈرىدۇ): go  out  سىرتقا چىقماق The book is  out / بۇ كىتاب ئارىيەت بېرىلگەن The dockers are  out ./ ماتروسلار ئىش تاشلىدى. ② (پەيدا بولۇش، ئېچىلىش قاتارلىقلارنى كۆرسىتىدۇ): The flowers are  out . گۈللەر ئېچىلدى. ③ (مەلۇم بىر خىل ئىش ھەرىكەتنىڭ ئاياغلاشقانلىقىنى ياكى ئاخىرغىچە ئېلىپ بېرىلغانلىقىنى كۆرسىتىدۇ): The fire has burnt  out . ئوت ئۆچۈرۈلدى fight it  out  / ئاخىرغىچە كۈرەش قىلماق. ④ (ئېنىقلىق ياكى ياڭراقلىقنى كۆرسىتىدۇ): call  out  ۋارقىرىماق  out and  out ‖ باشتىن ئاخىرغىچە، ئۇجۇر-بۇجۇرىغىچە ① out  of/ ... نىڭ سىرتىدا:  out of door  ئۆينىڭ سىرتىدا. ② ... لىقى ئۈچۈن، ... لىقى تۈپەيلىدىن. ③ ... نىڭ ئارىسىدىن. ④ ... نى ماتېرىيال قىلىپ. ⑤ كەم، يېتەرسىز.', 'O'),
('outcome', 'n. ئاقىۋەت، نەتىجە.', 'O'),
('outdoor', '① a. ئائىلە سىرتىدىكى، ئۆي سىرتىدىكى، ئوچۇقچىلىقتىكى، دالادىكى:  outdoor  labour ئۆي سىرتىدىكى ئەمگەك  outdoor  sports./ دالا سپورتى an  outdoor  theatre ئۈستى ئوچۇق تىياتىرخانا، يازلىق تىياتىرخانا an  outdoor  life./ دالا تۇرمۇشى. ② كەمبەغەللەر قورۇسىدا ئولتۇرمايدىغان نامراتلارغا سەدىقە قىلىش ئېلىپ بارىدىغان:  outdoor  relief كەمبەغەللەر قورۇسىدا ئولتۇرمايدىغان نامراتلارغا سەدىقە قىلماق.', 'O'),
('outdoors', 'ad.Ⅰ ئۆي سىرتىدا، دالادا: go  outdoors  for military training دالاغا بېرىپ ھەربىي مەشىق ئېلىپ بارماق. outdoor a.Ⅱ بىلەن ئوخشاش. ］ n.Ⅲ  بىرلىك سۈپىتىدە①      ［ ئوچۇقچىلىق. ② دالا.', 'O'),
('outer', 'adj. سىرتقى، سىرتىدىكى، تاشقىرى، تاشقىرىقى.', 'O'),
('outfight', '(outfought       vt. غەلىبە قىلماق، مەغلۇپ قىلماق.', 'O'),
('outfighting', 'n. يىراق ئارىلىقلىق جەڭ (ئۇرۇش) قىلىش.', 'O'),
('outfit 1', 'n. يۈرۈشلەشكەن ئۈسكۈنە.', 'O'),
('outfit 2', '① n.Ⅰ قوراللىنىش (ھەرىكەتنى كۆرسىتىدۇ):The  outfit 2  of the exploring party took only half a mounth. ئېكىسپدىتچىلار ئەترىتى تولۇق قوراللىنىشقا پەقەت يېرىم ئاي ۋاقىت سەرپ قىلدى. ②تولۇق بىر يۈرۈش سايمان، ھەممە بۇيۇملار، ھەممە لازىمەتلىكلەر، تولۇق بىر يۈرۈش قورال-جابدۇق: a dentist’s  outfit 2  چىش دوختۇرلىقىغا ئىشلىتىدىغان تولۇق بىر يۈرۈش ئۈسكۈنە.        ③ روھىي جەھەتتىكى سۈپەت. ④ (بەلگىلىك سورۇنلاردا كىيىدىغان) بىر يۈرۈش كىيىم-كېچەك. an  outfit 2  for camp ئوچۇقچىلىقتا تۈنەش كىيىمى. ⑤ (سىنىپ، گۇرۇپپا، ئەترەت قاتارلىقلارنى كۆرسىتىدۇ) تەشكىلى بار كوللېكتىپ، ئىدارە، ئورۇن (كۆپىنچە قىسىملارنى كۆرسىتىدۇ)؛ (مەلۇم كىشىنىڭ قول ئاستىدىكى) تولۇق قوشۇن. ⑥ ئوتلاق، يايلاق، چارۋىچىلىق مەيدان، جۇاڭيۇەن. vt.① (outfitted; outfitting) Ⅱ. قوراللانماق، تەقسىم قىلماق، سەپلىمەك vi.② قورال-ياراغقا ئېرىشمەك.', 'O'),
('outflow  n.', 'Ⅰ ئېقىپ چىقىش، سىرتقا ئېقىش، ئېقىپ چىققان نەرسە، ئېقىپ چىقىش مىقدارى: the  outflow  n.  of blood قان چىقىش مىقدارى an  outflow  n.  of language. / تۈگۈمەيدىغان گەپ، بېسىلمايدىغان گەپ. vi.       Ⅱ ئېقىپ چىقماق.', 'O'),
('outfly', '(outflew      , outflown      ) vt. ئۇچۇش تېزلىكى جەھەتتە ئېشىپ چۈشمەك: Today man can  outfly  the cound of his own voice. بۈگۈنكى كۈندە ئىنسانلار ئاۋازدىنمۇ يۇقىرى سۈرئەتتە ئۇچالايدىغان بولدى.', 'O'),
('outfoot', 'vt. (چېپىش، يۈگۈرەش، ئۇچۇش، ئۈزۈش قاتارلىقلاردىكى تېزلىك تەرەپتە ئېشىپ چۈشۈش:  outfoot  the other yachts. سۈرئەت باشقا ساياھەت كېمىسىدىن', 'O'),
('outguard', 'n. قاراۋۇلخانا.', 'O'),
('outguess', 'vt. سېزىۋالماق، تېپىۋالماق، بىلىۋالماق (قارشى تەرەپنىڭ غەرىزىنى) پەم بىلەن غەلىبە قىلماق:  outguess  the enemy دۈشمەننىڭ ھىيلە-مىكىرىنى سېزىۋالماق.', 'O'),
('outhouse', '① n. تاشقىرقى ئۆي، قوشۇمچە كىچىك ئۆي. ② ئۆي (سىرتىدىكى) ھاجەتخانا.', 'O'),
('outing', '① n.Ⅰ ساياھەتكە چىقىش، ئۆي سىرتىدىكى ھەرىكەت (كۆپىنچە يىراققا بېرىپ دالا تامىقى يېيىشنى كۆرسىتىدۇ): an  outing  at the beach دېڭىز ساھىلىدا كىچىك سەيلە قىلماق go for an  outing  / سىرتقا چىقىپ سەيلە-تاماشا قىلماق. ② تەنتەربىيە مۇسابىقىسى، كېمە ھەيدەش مەشىقى؛ ئات چاپتۇرۇش مەشىقى: score a victory in the second  outing  ئىككىنچى قېتىملىق مۇسابىقىدە غەلىبە قىلماق. a.Ⅱ ئۆي سىرتىدىكى ھەرىكەتلەرگە بېرىلىدىغان.', 'O'),
('outjockey', 'vt. پاراسەت بىلەن يەڭمەك، ئالداپ (كىشىنى) دامىغا چۈشۈرمەك، ئالدام خالتىغا چۈشەرمەك.', 'O'),
('outlander', 'n. چەت ئەللىك، باشقا يەرلىك كىشى. سىرتتىن كەلگۈچى، ناتونوش ئادەم. يات ئادەم.', 'O'),
('outlandish', '① a. چەت ئەل سالاپىتىلىك. ② ئاجايىپ-غارايىپ، قوپال-كېلەڭسىز.', 'O'),
('outlet', '①n. سۇ چىقىرىۋېتىش ئېغىزى، چىقىش ئېغىزى. ② ھېسسىياتىنى بېسىش ئۇسۇلى، ئاچچىقىنى چىقىرىش ۋاسىتىسى.', 'O'),
('outline', '①n.Ⅰ تاشقى شەكىل، سىرتقى شەكىل، ئىزنا، ئومۇمىي كۆرۈنۈش. ② مۇھىم نۇقتا، قىسقىچە مەزمۇن، تىزىس. v.Ⅱ قىسقارتىپ سۆزلىمەك، ئىزناسىنى سىزماق.', 'O'),
('outlook', '①n. مەنزىرە، كۆرۈنۈش. ② ئىستىقبال، كېلەچەك، كەلگۈسى. ③ كۆزقاراش، قاراش، نۇقتىئىنەزەر.', 'O'),
('output', '①n. مەھسۇلات، مىقدار. ② چىقىرىش، چىقىرىش قۇۋۋىتى.', 'O'),
('outrush', 'n.Ⅰ بۆسۈپ چىقىش، ئېتىلىپ چىقىش؛ ئېقىپ چىقىش. vt.Ⅱ (مۇسابىقىدا) (قارشى تەرەپكە) نىسبەتەن تېخىمۇ ئالغا بۆسۈپ كەتمەك.', 'O'),
('outsail', 'vt. يول بېسىشى...... دىنمۇ تېز بولماق.', 'O'),
('outsat', 'outsit نىڭ ئۆتكەن زامان شەكلى ۋە ئۆتكەن زامان سۈپەتدىشى', 'O'),
('outscriber', 'n. چىقارغۇچى خاتىرىلەش ماشىنىسى (خاتىرىلىگۈچ).', 'O'),
('outside', '①n.Ⅰ تاشقى قىسمى، تېشى، سىرتى، تاشقى كۆرۈنۈشى، كۆرۈنۈش. ② سىرت، تالا. ①adj.Ⅱ سىرتقى، تاشقى، تاشقىرىقى:  outside  work سىرتتىكى ئىشلار، سىرتقا چىقىپ قىلىدىغان ئىشلار. ② ئېھتىمالغا يېقىن، ئېھتىمالى زور بولغان. dv.Ⅲسىرتىدا، تالادا، دالدىدا: Is there anybody  outside ? سىرتىدا بىر كىم بارمۇ؟ prep.Ⅳ ... نىڭ سىرتىدا، ... نىڭ تاشقىرىسىدا، سىرتىغا:  go  outside the house تالاغا چىقماق That is  outside  myplan./ مېنىڭ پىلانىمدىكى ئىش ئەمەس.', 'O'),
('outsole', 'n. ئاياغ كىيىمىنىڭ پاشنىسى، پاشنا.', 'O'),
('outspread', 'I(outspread)v.＆ vt. سوزماق (سوزدۇرماق)، كەرمەك، كەردۈرمەك؛ يايماق (يايدۇرماق) a.Ⅱ سوزۇلغان، سۇنۇلغان، كېرىلگەن، يېيىلغان: welcomethe visiting comrades with  outspread  arms زىيارەتكە كەلگەن يولداشلارنى قۇچاق ئېچىپ قارشى ئالماق. n.Ⅲ سوزۇش، سۇنۇش، كېرىش، يېيىش، قانات يايدۇرۇش.', 'O'),
('outstanding', '①adj. كۆزگە كۆرۈنەرلىك، مەشھۇر، كۆزگە كۆرۈنگەن. ② ھەل بولمىغان، بىر تەرەپ قىلىنمىغان.', 'O'),
('outstation', 'n.يىراق چەت رايونلارغا تەسىر قىلغان تارماق پونكىت.', 'O'),
('outstay', '① vt. ... گە قارىغاندا ئۇزۇن تۇرماق؛ تۇرىشى (چەكتىن) ئېشىپ كەتمەك: He  outstay  ed the other visitors. ئۇ باشقا مېھمانلارغا قارىغاندا تېخىمۇ ئۇزۇن تۇردى.  outstay  one outstay ’s welcome/ بەك ئۇزۇن كېچىكتۈرگەنلىك تۈپەيلىدىن قارشى ئېلىنماسلىق. ② ئۇزۇنغا بەرداشلىق بېرىش كۈچى جەھەتتە ئۆتۈپ كەتمەك (بېسىپ چۈشمەك).', 'O'),
('outstep', '(outstepped; outstepping) vt. ھالقىپ ئۆتمەك، ئاتلاپ ئۆتمەك، ئېشىپ چىقماق، ئۆتۈپ كەتمەك:  outstep  the truth. ئەمەلىيەت دائىرىسىدىن ھالقىپ كەتمەك، پاكىتنى چوڭايتىۋەتمەك.', 'O'),
('outstretch', '① vt. سوزماق، سوزۇلماق، كېرىلمەك lie  outstretch  ed on the grass ئوت-چۆپ ئۈستىدە تۈپ-تۈپ سوزۇلۇپ ياتماق. ② سوزۇلىشى (كېرىلىشى، يېيىلىشى) ... نىڭ دائىرىسىدىن ئۆتۈپ كەتمەك: This explanation  outstretch  es common sense. بۇ چۈشەندۈرۈشكە كىشى ئىشىنىش تەس، بۇ چۈشەندۈرۈشكە ئىشەنگىلى بولمايدۇ.', 'O'),
('outstrip', '(outstripped; outstripping) ① vt. ئاتلاپ ئۆتمەك، ھالقىماق. ② بېسىپ چۈشمەك، غالىب كەلمەك، ئۆتۈپ كەتمەك، ئېشىپ كەتمەك:  outstrip  a country in ...... تەرەپتە مەلۇم بىر دۆلەتتىن ئۆتۈپ كەتمەك.', 'O'),
('outtalk', 'vt.... دىنمۇ ياڭراق سۆزلىمەك، ... گە قارىغاندا سۆزلىشى ياڭراق (ياكى كۈچلۈك) بولماق؛ سۆز قابىلىيىتى جەھەتتە بېسىپ چۈشمەك.', 'O'),
('outthrow', '(outthrew      ,outthrown      )vt. تاشلىماق، ئاتماق ② ... گە قارىغاندا، تاشلىشى تېخىمۇ يىراق، تېخىمۇ دەل بولماق. ① n.       Ⅱ تاشلاش، ئۇرغۇپ چىقىش، ئېتىلىپ چىقىش. ② يەر ئاغدۇرۇش؛ يەر ئاغدۇرۇش مىقدارى. ③ ئۇۋاق ماتېرىيال، كېرەكسىز ماتېرىيال.', 'O'),
('outtravel', '(outtravel(l)ed outtravel (l)ing) ① vt. (مەلۇم رايون، مەلۇم دائىرە قاتارلىقلاردىن) ساياھەت قىلىش ھالقىپ كەتمەك. ② سۈرئەتتە ئۆتۈپ كەتمەك: He outtravel(l)ed the news of his coming. ئۇ كەلمەكچى بولغان خەۋەر يېتىپ كەلمەي تۇرۇپ، ئۇ كەلدى.', 'O'),
('outtrump', 'vt. مۇسابىقىدا ئۇتۇپ چىقماق (ياكى مەغلۇپ قىلماق)، (قارشى تەرەپنى) يەڭمەك.', 'O'),
('outturn', 'n. مەھسۇلات مىقدارى، مەھسۇلات.', 'O'),
('outward', '①adj. تاشقى، سىرتقى. ② سىرتقا چىققان، سىرتقا تارالغان.', 'O'),
('outwards', 'dv. سىرتىدا، سىرتىغا، تالادا، تالاغا.', 'O'),
('oven', '①n. ئوچاق. ② مەش. ③ دوخوپكا.', 'O'),
('over', '①prep.Ⅰ ئۈستىدە، يۇقىرىدا: a bridge  over  the river. دەريا (ئۈستى)، دىكى كۆۋرۈك. ② (ھوقۇق، دەرىجە قاتارلىقلارنىڭ ... دىن يۇقىرى، ... نى بېسىپ چۈشىدىغان، ... دىن ئالىي ئىكەنلىكىنى كۆرسىتىدۇ): The East Wind prevails  over  the West Wind. شەرق شامىلى غەرب شامىلىنى بېسىپ چۈشىدۇ. ② ھەممە يەردە بار، ھەممە يەرگە يېيىلغان: We have friends all  over the world. دوستلىرىمىز دۇنيانىڭ ھەممە يېرىگە تارالغان؛ دۇنيانىڭ ھەمممىلا يېرىدە دوستلىرىمىز بار. ③ (ئۆتۈپ كېتىش، ... دىن، ... ئارقىلىق، دېگەنگە ئوخشاش ئۇقۇملارنى بىلدۈرىدۇ): jump  over  ئاتلاپ ئۆتمەك hear it  over  the radio/ رادىئو ئارقىلىق ئاڭلىماق. ④ توغرىسىدا، ئائىت، ... لىقتىن، ... لىكتىن: talk  over  the matter بۇ ئىش توغرىسىدا تەپسىلىي سۆزلىشەيلى. ①dv.Ⅱ يىقىلىپ؛ ۋاراقلاپ: fall  over  يىقىلىپ چۈشمەك turn  over  the page/ ۋاراقلىماق، ۋاراقلاپ ئاچماق. ② (ھالقىش ياكى تېشىپ كېتىشنى كۆرسىتىدۇ): The milk boiled  over . سۈت قايناپ تاشتى. ③ باشقا جايدا، ئاۋۇ تەرەپتە: The post office is  over  there. پوچتىخانا ئاۋۇ تەرەپتە. ④ ھەممە، پۈتۈنلەي، باشتىن ئاياغ: 〉〈all the world over  پۈتۈن دۇنياغا تارالماق. paint a door  over / ئىشىكنى پۈتۈنلەي سىرلىماق The wound healed  over / يارا پۈتۈنلەي ساقايماق. ⑤ (تەكرارلىنىشنى كۆرسىتىدۇ) يەنە، قايتا، قايتىلاپ.  over  again. قايتا، يەنە بىر قېتىم  over  and  over / قايتا-قايتا. ⑥ (مەلۇم بىر ئىش ھەرىكەتنىڭ ئاياغلىشىش ياكى ئۆتۈپ كېتىشىنى كۆرسىتىدۇ): The storm will soon be  over . بوران چاپقۇن توختاي دەپ قالدى. ⑥ (ئارتىپ كېتىش، ئېشىپ قېلىش قاتارلىقلارنى كۆرسىتىدۇ): How much is left  over ? قانچىلىك ئېشىپ قالدى؟', 'O'),
('overabundance', 'n. ئېشىپ قېلىش، ئارتىپ كېتىش.', 'O'),
('overact', 'vt.① (مەلۇم رولنى) چەكتىن ئاشۇرۇپ ئورۇندىماق (ئالماق). (مەلۇم ئىشنى) چەكتىن ئاشۇرۇپ قىلماق. vi.② ئورۇنلىشى چەكتىن ئېشىپ كەتمەك، قىلغىنى چەكتىن ئېشىپ كەتمەك.', 'O'),
('overage 1', '① a. بەك كونا، بەك كونىراپ كەتكەن، بەك كونا بەلكى كارغا كەلمەيدىغان: an  overage 1  warship كونا كارغا كەلمەيدىغان ھەربىي پاراخوت. ② يېشى ئارتىپ كەتكەن.', 'O'),
('overage 2', 'n. ھەددىدىن ئارتۇق، زىيادە، ئوشۇق.', 'O'),
('overaize ① a.', 'Ⅰ بەك چوڭ. ② ئادەتتىكى ئۆلچەمدىن چوڭ. ① n. پەۋقۇلئاددە چوڭ تىپ. ② پەۋقۇلئاددە چوڭ نومۇرلۇق نەرسە.', 'O'),
('overall', '①n.Ⅰ (ئۆي ئاياللىرى ياكى بالىلار كىيىدىغان) خالات. ② (كۆپلۈك ئىشلىتىلىدۇ) ئاسما شىم (سىم يول ئىشچىلىرىنىڭ). adj.Ⅱ ئەتراپلىق، تولۇق، پۈتۈن، پۈتۈنلەي.', 'O'),
('overburden', 'vt. زىيادە كۆپ باستۇرماق، زىيادە كۆپ قاچىلاتماق؛ يۈكنى بەك ئېغىرلاتماق، بەك ھاردۇرىۋەتمەك، بەك ھالسىرىتىۋەتمەك؛ ئەگمەك: The trees are  overburden  ed with fruit. دەرەخ مېۋىسى بەك تولۇق بولۇپ، شاخلىرى كۆتۈرەلمەي ئېگىلىپ كېتىپتۇ ① n. زىيادە ئېغىر يۈك؛ ئېغىرلىقى ئاشۇرۇپ بېسىلغان نەرسە.  ② يېپىنچا قاتلام. سىرتقى قاتلام توپىسى.', 'O'),
('overbusy', '① a. بەك ئالدىرايدىغان. ② بىھۇدە ئىشلارغا كۆپ ئارىلىشىدىغان.', 'O'),
('overbuy', '(overbought      ) vt.① (ئېھتىياجدىن ياكى سېتىۋېلىش ئىقتىدارىدىن ئارتىپ كەتكەنلىكىنى كۆرسىتىدۇ) زىيادە سېتىۋالماق. vi.② سېتىۋېلىشى زىيادە بولماق (ئارتۇقچە بولماق).', 'O'),
('overcall  vt.①', 'Ⅰ (قارت تاشلاش)، ... دىن ئارتىپ كەتمەك. vi.② (شېرىكى قارت تاشلىمىغان ئەھۋال ئاستىدا) رەقىبىگە قارىغاندا تېخىمۇ كۆپ قارت تاشلىماق.', 'O'),
('overcame', 'v. →overcome.', 'O'),
('overcapitalize', '① vt. ... گە مەبلەغنى بەك كۆپ سېلىۋەتمەك. ② (مەلۇم كارخانىنىڭ) كاپىتالى (سەرمايە)نى يۇقىرى مۆلچەرلىمەك.', 'O'),
('overcareful', 'a. ئارتۇقچە ئېھتىيات قىلىدىغان؛ بەكمۇ ئېھتىياتچان.', 'O'),
('overclothes', 'n. تاشقىكىيىم-كېچەك، نىقاب كىيىملىرى.', 'O'),
('overcoat', 'n. پەلتو، ئۇزۇن چاپان.', 'O'),
('overcome', '→ (overcame)      ① vt. غەلىبە قىلماقل يەڭمەك: overcome  difficulties قىيىنچىلىقلارنى يەڭمەك  overcome  the enemy / دۈشمەننى تىز پۈكتۈرمەك.  overcome  bureau cracy ./ بيۇكراتلىقنى يەڭمەك.  overcome  one’s shortcomings / كەمچىلىكلەرنى يەڭمەك. ］② كۆپىنچە مەجھۇل دەرىجىدە ئىشلىتىلىدۇ      ［ بېسىپ چۈشمەك، ئۈستۈن چىقماق: Overcome by fear, the enemy soldiers took to their heels. دۈشمەن ئارمىيىسى قورققىنىدىن بېشىنى ساڭگىلىتىپ تىكىۋەتتى. We were  overcome  with joy. / بىزنىڭ گۈلقەقەلىرىمىز ئېچىلىپ كەتتى. بىز كۈتۈلمىگەن خۇشاللىققا ئېرىشتۇق؛ بىز ئىچ-ئىچىمىزدىن سۆيۈنۈپ كەتتۇق. vi.② غەلىبىگە ئېرىشمەك.', 'O'),
('overcompensation', 'n. ھەددىدىن زىيادە تولدۇرۇش (ئۆزىنى كەمسىتىش قاتارلىق پسىخولوگىيىنى يېڭىش ئۈچۈن يۈز بەرگەن زىيادە ئىنكاس؛ ئەكس تەسىر).', 'O'),
('overcunning', 'a.＆ n. بەكمۇ ھىيلىگەرلىك قىلىش (بەكمۇ ھىيلىگەرلىك قىلىدىغان).', 'O'),
('overcurious', 'a. زىيادە ھەيرانلىق بىلەن كۆپ سورايدىغان.', 'O'),
('overdelicate', '① a. زىيادە ئىنچىكە، زىيادە نازۇك. ② زىيادە سىرلىق، زىيادە مۇرەككەپ.', 'O'),
('overdevelop', '① vt. زىيادە تەرەققىي قىلماق، بەك تەرەققىي قىلىپ كەتمەك.        ② بەك كۆلەڭگۈ چۈشۈرىۋەتمەك.', 'O'),
('overflow', '①v. تاشماق، تېشىپ كەتمەك، ئۇرغۇماق، يامرىماق، يېيىلماق. ② تولماق، لىق تولماق، قاپلىماق، قاپلانماق.', 'O')
ON CONFLICT (english) DO NOTHING;

INSERT INTO public.english_uyghur_dictionary (english, uyghur, letter_group) VALUES
('overhead', 'dv. بېشىدا، يۇقىرىدا، ئۈستىدە، ئاسماندا.       adj.Ⅱ ئېگىز، يۇقىرى، يەردىن ئايرىلىپ تۇرىدىغان.', 'O'),
('overhear', '(overheard       ① vt. مەيلى يوق (ئاڭسىز) ھالدا ئاڭلىماق؛ تۇيۇقسىز ئاڭلىماق. ② ئوغرىلىقچە ئاڭلىماق.', 'O'),
('overheat', '① vt. زىيادە قىزدۇرماق. ② زىيادە ھاياجانلاندۇرماق.', 'O'),
('overhung', 'overhang نىڭ ئۆتكەن زامان شەكلى ۋە ئۆتكەن زامان سۈپەتدىشى.', 'O'),
('overindulgence', 'n. زىيادە زوق-شوخ؛ زىيادە مەيلىگە قويۇش.', 'O'),
('overissue', 'n.Ⅰ (قەغەز پۇل، زايۇم قاتارلىقلارنى) زىيادە تارقىتىش، ئارتۇقچە تارقىتىش. vt.Ⅱ (قەغەز پۇل، زايۇم قاتارلىقلارنى) قالايمىقان تارقاتماق، كەلسە-كەلمەس تارقاتماق.', 'O'),
('overjoy', 'v. خۇشال قىلماق، خۇشاللاندۇرماق: With (ياكى) be  overjoy  ed at خۇشاللىققا چۆممەك. vt. چەكسىز خۇشاللاندۇرماق، ئىنتايىن خۇشاللاندۇرماق. a. بەك خۇشال: be  overjoy ed oa (O.with) the good news خۇش خەۋەرنى △  overjoy  ed ئاڭلاپ ئىنتايىن خۇشال بولماق.', 'O'),
('overkill', '① vt.ھەددىدىن زىيادە كۆپ يادرو كۈچى بىلەن (نىشاننى) ۋەيران قىلىپ تاشلىماق. ② تەكرار تەككۈزمەك. ③ قىرىپ تۈگەتمەك؛ قىرىپ قۇرىتىۋەتمەك ① n. زىيادە كۆپ يادرو قوراللىرى ۋەيران قىلىش كۈچى. ② زىيادە كۆپ زىيانكەشلىك قىلىش. ③ ھەددىدىن زىيادە كۆپ بولۇش؛ زۆرۈر بولمىغان ئارتۇقچە ھەرىكەت.', 'O'),
('overknee', 'a. تىزدىن ئاشقان.', 'O'),
('overlabo (u)r', '① vt. بەك بېرىلىپ ئىشلەتتۈرمەك. ② ... گە قارىتا زىيادە بېرىلىپ سۈرەتلىمەك.', 'O'),
('overlie', '(overlay      , overlain      ;  ① vt.... نىڭ ئۈستىدە ياتماق، نىڭ ئۈستىگە باسماق. ② چۈمكەپ دەم ئالالمايدىغان قىلىۋەتمەك؛ ..... بېسىپ دىمىقتۇرىۋەتمەك.', 'O'),
('overload', '① vt. يۈكىنى ئاشۇرىۋەتمەك، يۈكىنى زىيادە ئېغىرلاشتۇرماق: an  overload  ed vessel يۈكى ئېشىپ كەتكەن كېمە an  overload  ed sytle / كۆپتۈرۈپ چاكىنىلاشتۇرۇلغان ژانىر be  overload  ed with duties / خىزمەت يۈكى زىيادە ئېغىر بولماق. ② (مىلتىق، زەمبىرەكلەرگە) زىيادە كۆپ ئوق-دورىلارن−ى قاچىلىماق (سالماق). ① n.       Ⅱزىيادە ئېغىر يۈك.        ② ئارتۇق يۈك:  overload  relay ئارتۇق يۈكلۈك رېلى.', 'O'),
('overlong', 'ad.＆a. بەك ئۇزۇن.', 'O'),
('overlook', '① vt.Ⅰ نەزەر تاشلىماق، يۇقىرىدىن تۆۋەنگە قارىماق:  overlook  a valley from a hill تاغ ئۈستىدىن جىلغىغا نەزەر تاشلىماق (قارىماق). a tower  overlook  ing the city / پۈتۈن شەھەرنىڭ مۇنار-بىنالىرىغا نەزەر تاشلىماق. ② چوقچۇيۇپ چىقماق. ③ تەكشۈرمەك؛ نازارەت قىلماق: carefully  overlook  the accounts ھېساب تۈرلىرىنى ئىنچىكىلىق بىلەن تەكشۈرمەك. ④ كۆرۈشتىن قالدۇرۇپ قويماق (چۈشۈرۈپ قويماق)؛ سەل قارىماق:  overlook  a printer’s error بىر ئورۇندا بېسىشتا خاتالىققا يول قويماق. ⑤ ئۆز مەيلىگە قويىۋەتمەك، كېچىرىم قىلماق، ئەپۇ قىلماق:  overlook  a fault خاتالىقىنى ئەپۇ قىلماق. ⑥ ... نى كۆرۈپ ھودۇقماق (تەمتىرىمەك)؛ كۆز نۇرى بىلەن جەلپ قىلماق ① n. تۆت ئەتراپقا نەزەر تاشلايدىغان ئېگىز جاي. ② نەزەر تاشلىنىۋاتقان مەنزىرە. ③ قاراش، نەزەر تاشلاش، كۆزىتىش.', 'O'),
('overlord', '① n. فېئودال پادىشاھ (خان)، فېئودال ئاقسۆڭەك.②ئەڭ ئالىي ھۆكۈمران؛زالىم، زومىگەر؛ شاھىنشاھ، خاقان.', 'O'),
('overly', 'ad. ھەددىدىن ئارتۇق، ھەددىدىن زىيادە.', 'O'),
('overlying', 'overy نىڭ ھازىرقى زامان سۈپەتدىشى.', 'O'),
('overman', 'overmen      ) ① n. نازارەتچى؛ ئىش بېشى، باشلىق. ② كېسىمچى؛ زېغىر، سوتچى        ③ دەرىجىدىن تاشقىرى ئادەم (superman بىلەن ئوخشاش) vt.       (overmanned; overmanning) Ⅱ خادىملارنى زىيادە كۆپ سەپلەتتۈرمەك (تەقسىم قىلدۇرماق):  overman  a ship پاراخوتتىكى خادىملارنى ھەددىدىن زىيادە كۆپ تەقسىم قىلدۇرماق.', 'O'),
('overmany', 'a. ئارتۇقچە، زىيادە.', 'O'),
('overmaster', 'vt. بويسۇندرۇماق، باش ئەگەدۈرمەك؛ بېسىپ چۈشمەك: A strong emotion  overmaster  ed him completely. بىرخىل كۈچلۈك ھېسسىيات ئۇنى پۈتۈنلەي كونترول قىلىۋالدى.', 'O'),
('overmatch I', '① vt. غالىب كەلمەك، يەڭمەك، ئۇتۇپ چىماق، مەغلۇپ قىلماق. ② كۆپ كۈچلۈك رەقىب بىلەن مۇسابىقىلاشتۇرماق ① n.       Ⅱ بىرقەدەر كۈچلۈك رەقىب؛ كۈچلۈك دۈشمەن. ② ئارتۇقچىلىق ۋە ئاجىزلىق پەرقى چوڭ مۇسابىقە.', 'O'),
('overmeasure', 'n. نورمىدىن ئېشىپ كېتىش؛ ئېشىپ قېلىش.', 'O'),
('overmodest', 'a. زىيادە كەمتەر؛ زىيادە ئۇياتچان.', 'O'),
('overnice', '① a.زىيادە كۆڭۈل بۆلىدىغان، زىيادە رىئايە قىلىدىغان. ② زىيادە پۇتاق چىقىرىدىغان، ئارتۇقچە قۇسۇر ئىزدەيدىغان. ③ بەكمۇ ئىنچىكىلىك قىلىدىغان، بەكمۇ ئېغىر-بېسىق.', 'O'),
('overnight', '①dv.Ⅰ دەسلەپكى كۈنى كەچتە. ② كېچىچە، بىر كېچە، تاڭ ئاتقۇچە. adj.Ⅱ كەچ، كېچىلىك.', 'O'),
('overslaugh', '① vt.Ⅰ سەل قارىماق، چالا قويماق، چۈشۈرۈپ قويماق. ② (مەلۇم كىشىنىڭ) ۋەزىپىسىدىن ئېلىپ تاشلاپ (باشقىغا قويماق).        ③ (مەلۇم كىشىگە) سەل قاراپ ۋەزىپە بەرمەي (باشقىلارنى ئىشلەتمەك).        ④ توسىماق، توسقۇنلۇق قىلماق:  overslaugh  a legisla tive bill تەكلىپنىڭ ئىلگىرىلىشىگە توسالغۇلۇق قىلماق              n.Ⅱ (باشقا بىر تېخىمۇ مۇھىم ۋەزىپە تۈپەيلىدىن) ھازىرقى ۋەزىپىسىنى ئۆتەشتىن توختىتىش.', 'O'),
('oversleep', '(overslept      )       vt.① قانغۇدەك ئۇخلاتقۇزماق. vi.② قانغۇدەك ئۇخلىماق، بەك ئۇخلىماق.', 'O'),
('oversleeve', 'n. يەڭ قاپچۇقى.', 'O'),
('overtake', 'v. (overtook      ؛ overtaken      ) ① يېتىشمەك، يېتىشىۋالماق. ② تۇيۇقسىز يېتىپ كەلمەك، تۇيۇقسىز چۈشمەك (بوران-چاپقۇن، پېشكەللىك قاتارلىقلار).', 'O'),
('overthrow', 'v.Ⅰ (overthrew      ؛ overthrown      ) ئاغدۇرماق، ئاغدۇرۇپ تاشلىماق، غۇلاتماق، يىقىتماق.       n.Ⅱ ئاغدۇرۇش، ئاغدۇرمىچىلىق، گۇمران بولۇش، گۇمران قىلىش.', 'O'),
('overtook', 'v.→overtake.', 'O'),
('overturn', 'v. ئاغدۇرماق، ئاغدۇرۇلماق، يىقىلماق، يىقىتماق، غۇلىماق، غۇلاتماق.', 'O'),
('overwhelm', '①v. بېسىپ چۈشمەك. ② يوقالماق، غەرق بولماق، چۆكۈپ كەتمەك.', 'O'),
('owal', 'n.Ⅰ ئېللىپىس، ئېللىپىس شەكىل، تۇخۇم شەكىل. adj.Ⅱ ئېللىپىس، تۇخۇم شەكىللىك.', 'O'),
('owe', '①v. قەرزدار بولماق. ② مەنسۇپ بولماق.', 'O'),
('owing', '① a. قەرز بولغان، تۆلىمىگەن: There are still ten dollars  owing  يەنە 10 كوي قەرز بولماق (قالماق). ② بېرىشكە تېگىشلىك بولغان: sleep  owing  to sb. because of the long vigil مەلۇم كىشى تاڭ ئاتقۇچە كېچىلىك پوستتا تۇرغاندىن كېيىن، ئېلىشقا تېگىشلىك ئۇيقۇ.', 'O'),
('owing', 'adj. تۆلەنمىگەن، بېرىلمىگەن  owing to‖ سەۋەبتىن، تۈپەيلىدىن.', 'O'),
('owl', 'n. قارىغۇ ياپىلاق، ھوقۇق.', 'O'),
('own', 'adj.Ⅰ ئۆزىنىڭ، ئۆزىگە خاس. ①v.Ⅱ ئىگە بولماق. ② ئېتىراپ قىلماق، ئىقرار قىلماق، قوشۇلماق، ماقۇل بولماق.', 'O'),
('owner', 'n. ئىگە، ئىگىدارلىق قىلغۇچى، مۈلۈكدار، مال ئىگىسى.', 'O'),
('ox', 'n. (كۆپلۈكى  ox en      ) كالا، بۇقا.', 'O'),
('oxen', 'n.→ox.', 'O'),
('oxer', 'n. كالا قوتىنى، كالا ئېغىلى.', 'O'),
('oxherd', 'n. كالا باققۇچى، پادىچى.', 'O'),
('oxhide', 'n. كالا تېرىسى، كالا خۇرۇمى.', 'O'),
('oxidize', '①v. ئوكسىدلاشتۇرماق، ئوكسىدلاشماق. ② داتلاشماق، داتلاشتۇرماق.', 'O'),
('oxygen', 'n. <خىمىيە> ئوكسىگېن.', 'O'),
('oyster', 'n. مۇلى قۇلۇلىسى.', 'O'),
('oz.', 'ounce.', 'O'),
('P,p', 'ئىنگلىز تىلى ئېلىپبەسىنىڭ ئون ئالتىنچى ھەرپى', 'P'),
('p.', '①page.② participle. ③ past. ④ penny.', 'P'),
('P.M,p.m.', 'post meridien 〉لاتىن تىلى〈 چۈشتىن كېيىن،چۈشتىن كېيىنكى.', 'P'),
('P.O.', 'post office پوچتىخانا', 'P'),
('pace', 'n. قەدەم.', 'P'),
('pacific', '① adj. تىنچ، تىنچلىق. ② تىنچلىقپەرۋەر، تىنچلىق سۆيەر the pacific (Ocean) ‖ تىنچ ئوكيان.', 'P'),
('pack', 'n.Ⅰ بوپا، باغلام، توپ، بولاق، تېڭىق، ئورام. ① v.Ⅱ قاچىلىماق، ئورىماق، تاڭماق، قاچىلانماق، ئورالماق. ② قىستىماق، قىستالماق، قىستىلىپ كىرمەك، لىق توشماق.', 'P'),
('package', 'n.تېڭىق، بولاق، خالتا، پوسۇلكا.', 'P'),
('pad', '① n.Ⅰ سېلىنچا، چۈشەك. ② پات دەپتەر (يىرتىۋېتىلىشقا ئاسان بولسۇن ئۈچۈن، بىر چېتىگە يىلىم يېپىشتۇرۇپ تۈپلەنگەن دەپتەر). ③ (ھايۋاناتلارنىڭ) پۇت، تاپان. v.Ⅱ تولدۇرماق، نىقتىماق، توشقۇزماق.', 'P'),
('paddle 1', 'v. سۇ كەچمەك، سۇدا ئوينىماق.', 'P'),
