('page', 'n. بەت.', 'P'),
('paid', 'v. → pay.', 'P'),
('pail', 'n. چېلەك، تۇڭ.', 'P'),
('pain', 'n.Ⅰ ئاغرىق، ئازاب، جاپا، جاپالىق، مۇشەققەت،  مۇشەققەتلىك. v.Ⅱئاغرىماق، ئاغرىتماق، قىينىماق، جاپاغا سالماق، ئازابلىماق.', 'P'),
('painful', '① adj. ئاغرىق، ئازاب. ② جاپالىق، مۇشەققەتلىك.', 'P'),
('paint', 'n.Ⅰ سىر، بوياق، رەڭ. ① v.Ⅱ سىرلىماق. ② (بوياق بىلەن) سىزماق. ③ تەسۋىرلىمەك، سۈرەتلىمەك.', 'P'),
('painter', '① n. رەسسام. ② سىرچى.', 'P'),
('painting', 'n. رەسىم (سىزىلغان)؛ رەسساملىق.', 'P'),
('pair', 'n.Ⅰ (بىر) جۈپ. v.Ⅱ جۈپلەشمەك، جۈپلەشتۈرمەك a  pair  of ‖ بىر جۈپ a  pair  of glasses / بىر كۆزەينەك.', 'P'),
('palace', '① n. خان سارىيى، ئوردا. ② ساراي.', 'P'),
('pale', '① adj.Ⅰ تاتىرىپ كەتكەن؛ زەئىپ، ئاجىز. ② سۇس، ئاچ. v.Ⅱ تاتارماق، ئۆڭمەك.', 'P'),
('palm 1', 'n.Ⅰ ئالقان. v.Ⅱ كۆز بويىماق، ئالدىماق.', 'P'),
('palm 2', 'n. پالما، پالما دەرىخى.', 'P'),
('pan', '① n. تاۋا، تېگى تۈز قازان. ② لېگەن، تەخسە، پەتنۇس.', 'P'),
('pancake', 'n. تاۋا كاكچىسى.', 'P'),
('panda', 'n. مۈشۈكئېيىق.', 'P'),
('pane', 'n. پەنجىرە ئەينىكى.', 'P'),
('pang', '① n. قاتتىق ئاغرىق، قاتتىق ئاغرىش، سانجىلىپ ئاغرىش. ② ئازاب-ئوقۇبەت.', 'P'),
('panic', 'n.Ⅰ تەمتىرەش، دۇدۇقلاش، ئالاقزادىلىك. adj.Ⅱ سەۋەبسىز، ئارتۇقچە.', 'P'),
('pant', '① v.Ⅰ ھاسىراپ سۆزلىمەك، نەپىسى سىقىلىپ سۆزلىمەك. ① تەشنا بولماق، ئىنتىزار بولماق، ئارزۇ قىلماق. n.Ⅱ نەپەسلىنىش.', 'P'),
('pantry', '① n. تاماق ئېتىش سايمانلىرى ئۆيى.② يېمەكلىك ساقلاش ئۆيى.', 'P'),
