('prevail', '① v. ئۈستۈن كەلمەك، ئېشىپ چۈشمەك، بېسىپ چۈشمەك. ② كەڭ تارقالماق، ئەۋج ئالماق  prevail  up       ‖ قايىل بولماق.', 'P'),
