('proceeding', '① n. ئېلىپ بېرىش، يۈرگۈزۈش، ھەرىكەتلىنىش، ھەرىكەت. ② (كۆپلۈك ئىشلىتىلگەندە) ئەرز، دەۋا؛ خاتىرە، خاتىرە يېزىش.', 'P'),
