('profess', '① v. ئوچۇق ئىزھار قىلماق، ئوچۇق بىلدۈرمەك، ئىقرار قىلماق. ② ... قىلىپ جان باقماق، ... گە تايىنىپ تىرىكچىلىك قىلماق. ③ جاكارلىماق، ئۆزىنى ... دەپ تونۇشتۇرماق، ئۆزىنى ... دەپ ئاتىۋالماق.', 'P'),
