('prospect 1', '① n. مەنزىرە، ئەھۋال. ② ئۈمىد، ئارزۇ، ئىستەك، ئىستىقبال، كېلەچەك: The  prospect 1  s are bright ئىستىقبالى پارلاق.', 'P'),
