('provide', '① v. تەمىنلىمەك، بەرمەك. ② ساقلانماق، ئېھتىيات قىلماق، ھازىرلىق كۆرمەك، تەييارلىق قىلماق. ③ بەلگىلىمەك، بەلگىلەنمەك.', 'P'),
