('round', '①adj.Ⅰ يۇمىلاق، دۈگىلەك، شارسىمان. ② بىر ئايلانغان: a  round trip ئايلىنىپ چىقىش. ③ تولۇق، پۈتۈن. ④ سىلىق، لولىلىق، قۇۋلۇق، تىل ياغلىمىلىق. ①n.Ⅱ شارسىمان نەرسە. ② ئايلانما يول. ①dv.Ⅲ ئايلىنىپ، ئەگىپ: A wheel goes  round  چاق ئايلىنىپ ماڭىدۇ. ② ئەتراپتا، ئەتراپقا. ③ تەرەپ-تەرەپتىن، تەرەپ-تەرەپكە، تۇشمۇ تۇشتىن، بىر-بىرلەپ: 〉〈Hand these papers  round . بۇ ھۆججەتلەرنى كۆپچىلىككە تارقىتىپ بېرىڭ. prep.Ⅳ ئايلىنىپ، بويلاپ، ئەتراپىدا: The earth moves  round  the sun. يەر شارى قۇياش ئەتراپىدا ئايلىنىدۇ. ② ئەگىپ: walk  round  a corner دوقمۇشتىن ئەگىپ ئۆتمەك. ③ تەرەپ-تەرەپتىن، تەرەپ-تەرەپكە، تەرەپ-تەرەپتە.', 'R'),
('rouse', 'v. ئويغانماق، ئويغاتماق، قوزغىماق، قوزغالماق، ئىلھاملانماق، ئىلھاملاندۇرماق، ئىلھام بەرمەك.', 'R'),
('route', '①n. يول، مۇساپە. ② (ھەربىي ئاتالغۇ، دائىم        ئوقۇلىدۇ) يۈرۈش بۇيرۇقى.', 'R'),
('routine', 'n.Ⅰ كۈندىلىك خىزمەت، دائىمىي تەرتىپ. adj.Ⅱ كۈندىلىك، بەلگىلىك، دائىملىق.', 'R'),
('rove', 'v. سەيلە قىلماق، سەرگەردان بولۇپ يۈرمەك.', 'R'),
('rover', 'n. سەرگەردان.', 'R'),
('row 1', 'n. قاتار، رەت، تىزىق، سەپ.', 'R'),
('row 2', 'v.Ⅰ ھەيدىمەك (پالاق بىلەن كېمە ھەيدىمەك). n.Ⅱ (پالاق بىلەن) كېمە ھەيدەش.', 'R'),
('row3', '①n. غەلۋە، جېدەل، جېدەللىشىش، ماجىرا، ماجىرا تۇغدۇرۇش. ② ئەيىبلەش. ③ زاكونلىشىش.', 'R'),
('royal', '①adj. پادىشاھ، خان، پادىشاھنىڭ، خان ئائىلىسىنىڭ.  ② تەنتەنىلىك، كاتتا.', 'R'),
('rub', 'v.Ⅰ ( rub bed؛  rub bed؛  rub bing) ① سۈركىمەك، سۈركەلمەك، سۈركىلىپ كەتمەك، داسلىنىپ كەتمەك (ئەت)  rub down‖ سۈرتمەك، سۈرتۈپ تازىلىماق  rub in/ تەكرارلىماق  rub off      / سۈرتمەك، تازىلىماق ① rub up/ سۈرتۈپ تازىلىماق، سۈرتۈپ پارقىراتماق. ② ئويغاتماق، ئېسىگە سالماق. ①n.Ⅱ سۈركەش، سۈركىلىش. ③ توسالغۇ، كاشىلا، پۇتلىكاشاڭ.', 'R'),
('rubber', '①n. رېزىنكە. ② ئۆچۈرگۈچ.', 'R'),
('rubbish', '①n. ئەخلەت، تاشلاندۇق، كېرەكسىز نەرسىلەر. ② قۇرۇق گەپ، بىكار گەپ، خام خىيال، بولمىغۇر ئوي.', 'R'),
('ruby', '①n. قىزىل ياقۇت. ② قىپقىزىل رەڭ.', 'R'),
('rudder', 'n. رول (كېمە ياكى ئايروپىلاننىڭ).', 'R'),
('rude', '①adj. قوپال، ئەدەبسىز، پالاكەت، تەربىيىلەنمىگەن. ② قاتتىق، شىددەتلىك. ③ ئېچىلمىغان؛ ئىپتىدائىي. ④ يىرىك، ئاددىي.', 'R'),
('ruffle', '①v.Ⅰ داۋالغۇماق، تۈرمەك، تۈرۈلمەك، پۈرلەشمەك، پۈرلەشتۈرمەك، قاتلاشماق، قاتلاشتۇرماق. ③ ئاچچىقلانماق، ئاچچىقىنى كەلتۈرمەك، تېرىكمەك، تېرىكتۈرمەك؛ ۋارقىراپ جارقىرىماق. ④ قالايمىقانلاشماق، قالايمىقانلاشتۇرماق. ①n.Ⅱ پۈرمە، پۈرۈم. ② قورۇق.', 'R'),
('rug', 'n. (كىچىك) گىلەم.', 'R'),
('rugged', '①adj. ئېگىز-پەس. ② قورۇق، قورۇق باسقان، پۈرۈلگەن، پۈرلەشكەن، تۈرۈلگەن. ③ قوپال، قاتتىق، كەسكىن. ④ قىيىن، تەس، مۇشەققەتلىك. ④ (ئامېرىكا تىلىدا) ساغلام، قاۋۇل، كۈچلۈك.', 'R'),
('ruin', '①n.Ⅰ يوقىلىش، گۇمران بولۇش، ھالاكەت. ② بالايىئاپەت يىلتىزى. ③ خارابە، خارابىلىك. v.Ⅱ يوقاتماق، گۇمران قىلماق، ھالاك قىلماق، بىتچىت قىلماق.', 'R'),
('rule', '①n.Ⅰ قائىدە، تەرتىپ، نىزام. ② قانۇن، دائىمىي تەرتىپ، قائىدە-يوسۇن، ئادەت. ③ ھۆكۈمرانلىق قىلىش. ④ سىزغۇچ.  ①v.Ⅱ باشقۇرماق، ھۆكۈمرانلىق قىلماق. ② ھۆكۈم قىلماق. ③ سىزىق سىزماق (سىزغۇچ قويۇپ).', 'R'),
('ruler', '①n. ھۆكۈمرانلىق قىلغۇچى، باشقۇرغۇچى. ③ سىزغۇچ.', 'R'),
('ruling', 'adj.Ⅰ ھۆكۈمران، ھۆكۈمرانلىق قىلىۋاتقان. n.Ⅱ كېسىم، ھۆكۈم (قىلىش).', 'R'),
('rumo(u)r', 'n.Ⅰ سۆز-چۆچەك، مىش-مىش گەپ، ئىغۋا، پىتنە-پاسات. v.Ⅱ ئىغۋا تارقاتماق، پىتنە-پاسات تارقاتماق.', 'R'),
('run', 'v.Ⅰ (ran      ؛  run ؛  run ning) ① يۈگۈرمەك، چاپماق، چاپتۇرماق. ② ماڭماق، يۈرمەك (ماشىنا، پويىز، كېمە ۋە باشقىلار). ③ ئايلانماق، ئايلاندۇرماق. ④ سوزماق، سوزۇلماق، داۋاملاشتۇرماق. ⑦ (سۇ) ئاقماق. ⑧ ... بولۇپ قالماق (كالىدىن سۈت چىقمايدىغان، قۇدۇققا سۇ يىغىلمايدىغان بولۇپ قالماق). ⑨ يۈگۈرتمەك (كۆزىنى). 01 يېزىلماق. 11 قاچماق، قاچۇرماق. 21 ئۆتمەك، ئۆتكۈزمەك. 31 سانجىماق، سانجىلماق. 41 ئۇرۇلماق. 51 باشقۇرماق، ئىدارە قىلماق؛ ھەيدىمەك، ئىشلەتمەك. 61 سايلام رىقابىتىگە قاتناشماق، مۇسابىقىلاشماق، تاسادىپىي ئۇچرىماق  run after/ ئىزدىمەك، ئىنتىلمەك ① run down توختاپ قالماق. ② ئاجىزلاشماق  run low      / كەملىك قىلماق؛ خورىماق، سەرپ بولماق ① run out/ تۈگىمەك، تۈگەتمەك، ئاخىرلاشماق، ئاخىرلاشتۇرماق. ② تومپىيىپ چىقىپ تۇرماق. ③ سوزماق، سوزۇلماق، كېڭەيمەك، كېڭەيتمەك ① run over/ تاشماق، تېشىپ كەتمەك؛ ئاشماق، ئېشىپ چۈشمەك. ② كۆزدىن كەچۈرمەك، تەكرارلىماق. ③ (ماشىنا) سوقۇۋەتمەك، بېسىۋالماق ① run through/ (پۇل) تۈگىمەك، تۈگەتمەك، ئىسراپچىلىق قىلماق. ② كۆزدىن كەچۈرمەك ①  run up/ ئۆرلىمەك، ئۆرلەتمەك، كۆتۈرمەك، كۆتۈرۈلمەك. ② ئالدىراپ-تېنەپ ياسىماق، ئوپۇل-توپۇل تىكلەپ قويماق. ①n.Ⅱ يۈگۈرۈش، چېپىش، قېچىش. ② داۋاملىشىش، داۋاملاشتۇرۇش. ③ ئايلىنىش، ئايلاندۇرۇش.', 'R'),
('rung', 'v. ← ring.', 'R'),
('runner', '①n. يۈگۈرگۈچى، يۈگۈرۈش سپورتچىسى. ② خەۋەرچى.', 'R'),
('running', '①adj.Ⅰ ئارقا-ئارقىدىن، ئۈزلۈكسىز، كەينى-كەينىدىن. ② يۈگۈرۈش؛ ئاقىدىغان: 〈 running water〉 ۋودوپروۋود سۈيى. ①n.Ⅱ يۈگۈرۈش، يۈگۈرۈش مۇسابىقىسى. ② ئايلىنىش، ئايلاندۇرۇش، ئىشلەش، ئىشلىتىش.', 'R'),
('rural', 'n. يېزا، سەھرا، يېزا ئىگىلىك.', 'R'),
('rush', '①v.Ⅰ ئېتىلماق، بۆسۈپ ئۆتمەك، بۇزۇپ ئۆتمەك، شىددەتلىك زەربە بەرمەك. ② سۈيلىمەك، ھەيدەكچىلىك قىلماق، ئالدىرىماق، ئالدىراتماق. ①n.Ⅱ ئېتىلىش، ئېتىلىپ كىرىش، بۇزۇپ ئۆتۈش، شىددەتلىك زەربە بېرىش. ② زۆرۈر لازىم بولۇش، جىددىي مۇھتاج بولۇش. ③ تالىشىپ سېتىۋېلىش. adj.Ⅲ جىددىي، ئالدىراش؛ جىددىي ئورۇنلىنىش، تەلەپ قىلىنىدىغان (بۇيرۇق).', 'R'),
('Russian', '①adj.Ⅰ رۇس، رۇسنىڭ. ② رۇسچە، رۇس تىلىنىڭ. ①n.Ⅱ رۇس. ② تۇس تىلى.', 'R'),
('rust', '①n.Ⅰ دات. ② <ئۆسۈملۈك> ھال كېسىلى. v.Ⅱ داتلاشماق، دات باسماق، داتلاشتۇرماق.', 'R'),
('rustic', '①adj.Ⅰ يېزا، يېزىنىڭ، يېزىچە، سەھرا، سەھرانىڭ، سەھراچە، سەھرايى. ② ساددا، سەمىمىي، ئاق كۆڭۈل. n.Ⅱ سەھرالىق، دېھقان تېرىقچى.', 'R'),
('rustle', 'n. شىلدىر-شىلدىر، شىر-شىر (شامالنىڭ دەل-دەرەخ، ئوت-چۆپ قاتارلىقلارغا ئۇرۇلۇشىدىن پەيدا بولغان ئاۋاز).', 'R'),
('rusty', 'adj. داتلاشقان.', 'R'),
('Ry.', 'Rail way.', 'R'),
('rye', 'n. قارا بۇغداي؛ يالىڭاچ ئارپا.', 'R'),
('S,s', 'ئىنگلىز تىلى ئېلىپبەسىنىڭ ئون توققۇزىنچى ھەرپى', 'S'),
('sack 1', '① n.Ⅰ تاغار، خالتا، قاپ.        ②(جانلىق تىلدا) ئىشتىن بوشىتىش، خىزمەتتىن ئېلىپ تاشلاش. ① v.Ⅱ خالتىغا قاچىلىماق، قاپقا سالماق. ② (جانلىق تىلدا) ئىشتىن بوشاتماق، خىزمەتتىن ئېلىپ تاشلىماق.', 'S'),
('sack 2', 'n.Ⅰ بۇلاش، تالان-تاراج قىلىش. v.Ⅱ بۇلىماق، بۇلاپ-تالىماق، تالان-تاراج قىلماق.', 'S'),
('sacred', 'adj. مۇقەددەس.', 'S'),
('sacrifice', '① n.Ⅰ قۇربانلىق. ② نەزىر بۇيۇملىرى. ③ زىيانغا ئۇچراش. ① v.Ⅱ قۇربان بولماق، بېغىشلىماق، ئۆزىنى ئاتىماق. ② نەزىر بەرمەك. ③ باھاسىنى چۈشۈرۈپ ساتماق.', 'S'),
('sad', 'adj. قايغۇلۇق، ھەسرەتلىك، قايغۇرىدىغان، ھەسرەتلىنىدىغان. ② غۇۋا، خىرە، تۇتۇق؛ دىمىق (ھاۋا). ③ غەمكىن.', 'S'),
('saddle', '① n.Ⅰ ئېگەر، ئېگەر شەكىللىك نەرسىلەر. ② ۋېلىسىپىت ئېگىرى. ① v.Ⅱ ئېگەرلىمەك، ئېگەر توقۇماق. ② ئۈستىگە ئارتىلماق، زىممىسىگە يۈكلەنمەك (مەسئۇلىيەت).', 'S'),
('sadly', 'adv. قايغۇدا، قايغۇرۇپ، ئېچىنىپ، غەمكىن، پەرىشان ھالدا.', 'S'),
('sadness', '① n. قايغۇ-ھەسرەت، غەم-غۇسسە، غەم-ئەندىشە. ② چىرايى تۇتۇلۇپ قېلىش، كۆڭلى بۇزۇلۇش.', 'S'),
('safe', '① adj. بىخەتەر، بىخەتەرلىك، تىنچ-ئامان، ساق-سالامەت. ② ئېھتىياتچان. ③ پۇختا، ئىشەنچىلىك. ④ ساغلام.', 'S'),
('safely', '① adv. بىخەتەر، بىخەتەر ھالەتتە، تىنچ-ئامان. ② ئېھتىياتچانلىق بىلەن، پەخەس بولۇپ.', 'S'),
('safety', 'n.Ⅰ بىخەتەر. adj.Ⅱ بىخەتەرلىك، ئىشەنچلىك in (with)  safety  تىنچ-ئامان، ساق-سالامەت.', 'S'),
('sage', 'n.Ⅰ ئاقىل، دانىشمەن، دانا ئادەم، ئەۋلىيا. adj.Ⅱ دانىشمەن، چېۋەر، ئاقىل، ئاقىلانە.', 'S'),
('said', 'v.→ say.', 'S'),
('sail', 'n.Ⅰ يەلكەن، يەلكەنلىك كېمە. v.Ⅱ يولغا چىقماق، ھەيدىمەك (كېمە).', 'S'),
('sailor', 'n. دېڭىزچى، كېمىچى، ماتروس.', 'S'),
('saint', '① n. پەيغەمبەر. ② دانىشمەن. ③ مۇقەددەس ئادەم.', 'S')
ON CONFLICT (english) DO NOTHING;

INSERT INTO public.english_uyghur_dictionary (english, uyghur, letter_group) VALUES
('sake', 'n. سەۋەب، ۋەج، مەقسەت.', 'S'),
