('salary', 'n. مائاش، ئايلىق؛ يىللىق مائاش.', 'S'),
('sale', '① n.Ⅰ سېتىش، سېتىۋېلىش. ② باھاسىنى چۈشۈرۈپ سېتىش. ③ بازىرى، سېتىلىش يولى، سېتىلىشى on (for)  sale ‖ ساتىدىغان، سېتىلىدىغان.', 'S'),
('salesman', '(salesmen      ) n. (ئەر) پرىكازچىك، دۇكانچى.', 'S'),
