('salient', 'adj. كۆزگە كۆرۈنەرلىك، گەۋدىلىك.', 'S'),
('sally', '① n. مۇھاسىرىنى بۇزۇپ چىقماق، ھۇجۇمغا ئاتلىنىش. ② تەنە گەپ، كىنايە، شاڭخو. v.Ⅱ مۇھاسىرىنى بۇزۇپ چىقماق، ھۇجۇمغا ئاتلانماق.', 'S'),
('salt', 'n.Ⅰتۇز: common  salt  ئاش تۇزى. adj.Ⅱ تۇزلۇق. v.Ⅲ تۇزلىماق، تۇز سەپمەك، تۇز سالماق.', 'S'),
('salute', '① n.Ⅰ سالام، سالام بېرىش، تەزىم قىلىش. ② ئېھتىرام، ئېھتىرام بىلدۈرۈش. ① v.Ⅱ سالام بەرمەك، تەزىم قىلماق. ② ئېھتىرام بىلدۈرمەك.', 'S'),
('salvation', 'n. ياردەم، قۇتقۇزۇش، ئىجتىمائىي ياردەم.', 'S'),
('same', 'adj.Ⅰ ئوخشاش، بىردەك، پەرقسىز ① at the  same  time‖ بىرلا ۋاقىتتا. ② يەنە، ھەم the  same  as / ... بىلەن ئوخشاش، بىردەك.        pron.Ⅱ شۇنداقلا، ئوخشاشلا، بىردەك. adv.Ⅲ ئوخشاش، بىردەك.', 'S'),
('sample', 'n.Ⅰ ئۈلگە، نۇسخا، نەمۇنە، ئۆرنەك. ① v.Ⅱ ئۈلگە قىلماق، نۇسخا ئالماق. ② سىناپ كۆرمەك.', 'S'),
('sanatorium', '(       sanatoria) n. ساناتورىيە.', 'S'),
('sanctuary', '① n. ئىبادەتخانا، بۇتخانا. ② (قەدىمكى) پاناھ جاي. ③ ھايۋاناتلارنى مۇھاپىزەت قىلىش رايونى، ئوۋ قىلىش چەكلەنگەن رايون.', 'S'),
('sand', 'n. قۇم، قۇملۇق.', 'S'),
('sandal', '① n. ساپما كەش. ② ساندال.', 'S'),
('sandwich', 'n.Ⅰ گۆشنان. v.Ⅱ ئارىسىغا قىستۇرماق، سانجىماق، كىرگۈزمەك.', 'S'),
('sandy', '① adj. قۇم، قۇمدەك، قۇمساڭ. ② سۇس چايرەڭ. ③ تۇراقسىز.', 'S'),
('sang', 'v.→ sing.', 'S'),
('sanitarium', 'n. sanatorium.', 'S'),
('sank', 'v.→ sink.', 'S'),
('santa Claus', 'n.قار بوۋاي (غەرب ئەللىرىدە روژدىستۋو بايرىمىدا بوۋايچە ياسىنىپ بالىلارغا سوۋغا تەقسىم قىلىدىغان ئادەم).', 'S'),
('sap', '① n.سۇيۇقلۇق؛ دەرەخ سۇيۇقلۇقى. ② دەرمان، قۇۋۋەت، ماغدۇر.', 'S'),
('sash', '① n. بەلباغ، باغ. ② رام، كېشەك.', 'S'),
