('shall', '(should      ) ① auv.v. (بىرىنچى شەخس ئىگە بولۇپ كەلگەن جۈملىلەردە ئاساسىي پېئىل بىلەن بىرگە كېلىپ، كېلىدىغان زاماننى بىلدۈرىدۇ): I  shall  go. مەن بارىمەن. ② (ئىككىنچى ۋە ئۈچىنچى شەخس ئىگە بولۇپ كەلگەن جۈملىلەردە ئاساسىي پېئىل بىلەن بىرگە كېلىپ، سۆزلىگۈچىنىڭ ئىرادە، مەقسەت، غەرەز، بۇيرۇق ياكى تەھدىت قىلغانلىقىنى بىلدۈرىدۇ): You  shall  not leave at post. سەن ئىش ئورنۇڭدىن ئايرىلما afternoon. You  shall  get the answer right this / بۈگۈن چۈشتىن كېيىن جاۋابقا ئېرىشىسىز. ③ (سوراق جۈملىلەردە قارشى تەرەپنىڭ پىكىرىنى ئېلىش ياكى تەكلىپ بېرىش مەنىسىنى بىلدۈرىدۇ): Shall I fetch the hammar? بولكىنى ئېلىپ كېلەيمۇ؟ ④ (ئۆتكەن زامان شەكلى shoud ئاساسىي پېئىل بىلەن بىرگە كېلىپ، ئىمكانىيەتنى ياكى قىياس قىلىشنى بىلدۈرىدۇ): They should have arrived in Peking by this time. ئۇلار ھازىر بېيجىڭگە يېتىپ بارغان بولۇشى مۇمكىن.', 'S'),
