('sound 1', 'n.Ⅰ ئاۋاز، ئاھاڭ، تاۋۇش. ① v.Ⅱ تاۋۇش چىقارماق؛ (مەلۇم نەرسىنىڭ) ئاۋازىنى چىقارماق. ② ئۇقتۇرماق (سىگنال بىلەن). ③ جاراڭلىماق، ياڭرىماق. ① adj.Ⅲ ساغلام، ساق، بېجىرىم. ② توغرا. ③ ئۈزۈل-كېسىل، تامامەن.', 'S'),
('sound 2', '① adj. ساغلام، ساق بېجىرىم. ② توغرا. ③ ئۈزۈل-كېسىل، تولۇق، تامامەن. ④ قانغۇدەك.', 'S'),
