('spank', 'v.Ⅰ ... نىڭ ساغرىسىغا ئۇرماق، شاپىلاقلىماق. n.Ⅱ ساغرىسىغا ئۇرۇش، شاپىلاقلاش.', 'S'),
('spare', '① v.Ⅰ رەھىم قىلماق، كەچۈرمەك. ② ئىقتىساد قىلماق، تېجىمەك، ئايىماق. ① adj.Ⅱ بوش، بىكار:  spare  time بوش ۋاقىت a  spare  time school / ئىشتىن سىرتقى مەكتەپ. ② زاپاس. ③ ئورۇق، ئاۋاق (ئادەم).', 'S'),
