('speak', 'v. spoke      ؛ spoken      ) سۆزلىمەك، گەپ قىلماق ①  speak  for ‖ ۋاكالىتەن سۆزلىمەك. ② ئىسپاتلىماق، بىلدۈرمەك ①  speak  out       / ئۈنلۈك سۆزلىمەك. ② ئىككىلەنمەك  speak  to / ئىسپاتلىماق. ② ئەيىبلىمەك. ③ ماۋزۇدىن يىراقلاشماسلىق generally  speak  ing / ئادەتتىكىچە قىلىپ ئېيتقاندا، مۇنداقچە ئېيتقاندا.', 'S'),
