('spice', '① n.Ⅰ خۇش پۇراق ماتېرىياللىرى. ② دورا-دەرمەك. ③ قىزىقىش، ھەۋەس، لەززەت. v.Ⅱ دورا-دەرمەك سالماق.', 'S'),
