('spinning', '① n.Ⅰ توقۇش. ② ئېگىرىش. ③ ئايلىنىش، ئۆز ئوقى ئەتراپىدا ئايلىنىش. ① adj.Ⅱ توقۇمىچىلىق، توقۇمىچىلىققا ئىشلىتىلىدىغان.', 'S'),
