('spite', '① n.Ⅰ يامان نىيەت، يامانلىق. ② نەپرەتلىنىش، يامان كۆرۈش. ③ ئۆچمەنلىك. ① v.Ⅱ زىيان يەتكۈزمەك. ② قىيىنچىلىق تۇغدۇرماق in  spite  of ‖ مەيلى ... بولمىسۇن، ... بىلەنمۇ.', 'S'),
('splash', 'v.Ⅰ چاچرىماق، چاچراتماق. n.Ⅱ چاچراش ئاۋازى (سۇيۇقلۇققا بىرەر نەرسىنىڭ چۈشۈشىدىن ھاسىل بولغان ئاۋاز).', 'S'),
('splendid', 'adj. پارلاق، شانلىق، ھەشىمەتلىك، ئۇلۇغۋار.', 'S'),
('splendo (u)r', 'n. كۆركەم، ھەشەمەتلىك، پارلاق، سەلتەنەتلىك.', 'S'),
('split', 'v.Ⅰ ( split ؛  split ؛  split ting) يارماق، يېرىلماق، ئاجراتماق، ئاجرالماق بۆلمەك، بۆلۈنمەك. adj.Ⅱ بۆلۈنگەن، ئايرىلغان. ئاجرىتىلغان، چاك كەتكەن. ① n.Ⅲ دەز، چاك. ② ئىختىلاپ، كېلىشمەسلىك.', 'S'),
('spoil', 'v.Ⅰ ( spoil  ed        spoil t      ؛  spoil ،  spoil ed) ① بۇزماق، بۇزغۇنچىلىق قىلماق، ۋەيران قىلماق، زىيان يەتكۈزمەك. ② (بالىلارنى) ئەركىلىتىپ كاردىن چىقارماق. ③ بۇزۇلماق، چىرىمەك؛ پۇراپ قالماق. n.Ⅱ زاڭ مال، غەنىيمەت، ئولجا.', 'S'),
('spoke', 'v.→ speak.', 'S'),
