('sponge', 'n.Ⅰبۇلۇت. v.Ⅱ بۇلۇت بىلەن تازىلىماق.', 'S'),
('sponsor', 'n.Ⅰ تەشەببۇسچى، ياردەمچى، مەسئۇل. ① v.Ⅱ تەشەببۇس قىلماق. ② باشلاپ بەرمەك، باشچىلىقىدا ئېلىپ بارماق، ئۇيۇشتۇرماق.', 'S'),
('spontaneous', 'adj. تەبىئىي ئۆزلۈكىدىن پەيدا بولغان.', 'S'),
