('spore', '〉n.بىئولوگىيە〈 سپورا.', 'S'),
('sport', '① n.Ⅰ ئويۇن، تاماشا. ② تەنھەرىكەت، ئىسپورت. v.Ⅱ ئويۇن-تاماشا قىلماق. adj.Ⅲ تەنھەرىكەت، تەنھەرىكەتكە ئىشلىتىلىدىغان:  sport  (s) equipments تەنھەرىكەت ئۈچۈن ئىشلىتىلىدىغان ئۈسكۈنىلەر.', 'S')
