INSERT INTO public.english_uyghur_dictionary (english, uyghur, letter_group) VALUES
('spot', '① n.Ⅰ نۇقتا، چېكىت. ② داغ. ③ جاي، ئورۇن. ① v.Ⅱ داغ چۈشمەك، داغ چۈشۈرمەك؛ پاسكىنا قىلماق، مەينەت بولماق. ③ تونۇماق، پەرق ئەتمەك.', 'S'),
('sprang', 'v.→ spring.', 'S'),
('spray', '① n.Ⅰ (ئېتىلىپ چىققان) ھور؛ تۇمان. ② پۈركۈگۈچ. ② v.Ⅱ چاچراپ چىقماق، ئېتىلىپ چىقماق، پۈركۈمەك. ② دورا پۈركۈمەك.', 'S'),
('spread', 'n.Ⅰ ( spread ؛  spread ) ① يايماق، يېيىلماق، سوزماق، سوزۇلماق، كېڭەيمەك، كېڭەيتمەك. ② تارقىماق، تارقاتماق. ③ سۈركىمەك. n.Ⅱ (دائىم كۆپلۈك ئىشلىتىلىدۇ) تارقىتىش. ① تارقىلىش، يېيىش، يېيىلىش. ② داستىخان؛ كىرلىك. ③ زىياپەت، ئولتۇرۇش.', 'S'),
('spring', 'v.Ⅰ (sprang      ؛ sprung      ) ① ئاتلىماق، سەكرىمەك، سەكرەتمەك. ② پارتلىماق. ① n.Ⅱ باھار، ئەتىياز، ئەتىياز پەسلى. ② بۇلاق. ③ سەكرەش، ئاتلاش. ④ پۇرژىنا. ⑤ ئېلاستىكىلىق، ئېلاستىك كۈچ. ⑥ (دائىم كۆپلۈك ئىشلىتىلىدۇ) مەنبە، مەقسەت.', 'S'),
('sprinkle', '① v.Ⅰ چاچماق، چېچىلماق، سەپمەك، سېپىلمەك. ② سىم-سىم يامغۇر ياغماق. n.Ⅱسىم-سىم يامغۇر، ئۇششاق يامغۇر.', 'S'),
('sprung', 'v.→ spring.', 'S'),
('spun', 'v.→ spin.', 'S'),
('spur', '① n.Ⅰ غىدىقلىغۇچى ماددا. ② تاغ تۇمشۇقى، يار. v.Ⅱ ( spur  red      ؛  spur  red؛         spur ring) ① ھەيدىمەك، قوغلىماق. ② غىدىقلىماق.', 'S'),
('spurn', '① v. چەتكە قاقماق، يەكلىمەك. ② ۋاز كەچمەك، تاشلىۋەتمەك.', 'S'),
('spy', 'n.Ⅰ جاسۇس. ① v.Ⅱ جاسۇسلۇق قىلماق، رازۋېدكا قىلماق. ② سەزمەك، سېزىپ قالماق.', 'S'),
('sq.', 'square.', 'S'),
('square', '① n.Ⅰ كۋادرات شەكىل، تۆت چاسا. ②مەيدان: Tien An Men  square  تيەنئەنمېن مەيدانى. ③ <ماتېماتىكا>.④ كۋادرات.⑤ تىك بۇلۇڭلۇق سىزغۇچ. ① v.Ⅱ چاسلىماق، چاسىلانماق. ① تۈزلىمەك، تۈزەلمەك. ③ <ماتېماتىكا> يۈزىنى تاپماق. ④ ھېسابنى تۈگەتمەك. ① adj.Ⅲ  چاسا، تۆت چاسا، كۋادرات. ② تىك بۇلۇڭ. ③ ئادالەتلىك، ئادىل. ① adv.Ⅳ تىك، تۈپتۈز. ئادالەتلىك بىلەن، ئادىللىق بىلەن.', 'S'),
('squeak', 'n.Ⅰ چىرىلداش، چىر-چىر (ئاۋاز) v.Ⅱ چىرىلدىماق.', 'S'),
('squees', 'v.Ⅰقىستىماق، قىستالماق؛ ئەزمەك، ئېزىلمەك؛ سىقماق، سىقىلماق. ① n.Ⅱقىستىلىش، سىقىلىش، ئېزىلىش. ② شۈلۈۋالغان پۇل.', 'S'),
('squire', 'n.( ئەنگلىيە تىلىدا) ئېسىلزادە؛ پومېشچىك.', 'S'),
('squirrel', 'n. تىيىن (بىر خىل ھايۋان).', 'S'),
('St.', 'street.', 'S'),
('stab', 'v.Ⅰ ( stab  bed؛  stab bed؛  stab bing) ① سانجىماق؛ تۈرتمەك، نوقۇماق. ② ئاغرىتماق، ئاغرىقنى قوزغىماق. ① n.Ⅱ سانجىش؛ تۈرتۈش، نوقۇش. ② ئاغرىتىش.', 'S'),
('stable 1', '① adj. مۇستەھكەم، پۇختا. ② تۇراقلىق، مۇقىم.', 'S'),
('stable 2', 'n. ئاتخانا، ئېغىل.', 'S'),
