('take', 'v. (took      ؛ taken      ) ① ئالماق؛ تۇتماق. ② (ۋاقىتنى) ئالماق، كەتمەك: It will  take  a long time. بۇ كۆپ ۋاقىتنى ئالىدۇ. ③ گىرىپتار بولماق؛  take  cld زۇكام بولۇپ قالماق. ④ ئېرىشمەك، قولغا كەلتۈرمەك، ئىشغال قىلماق. ⑤ ئېلىپ كەتمەك، ئېلىپ بارماق، ئاپارماق:  take the child to the cinema بالىنى كىنوغا ئېلىپ بارماق. ⑥ يېمەك، ئىچمەك، ئىستېمال قىلماق:  take medicine دورا ئىستېمال قىلماق. ⑦ چىقماق، چۈشمەك:  take  a bus ئاپتوبۇسقا چۈشمەك. ⑧ ئىجارىگە ئالماق؛ مۇشتەر بولماق:  take  a house بىر ئېغىز ئۆينى ئىجارىگە ئالماق. ⑨ يازماق، خاتىرىلىمەك:  take notes worker. خاتىرىلىمەك. 01 ئالماق، چۈشمەك، تارتماق (رەسىمگە). 11 چۈشەنمەك، ... دەپ قارىماق، ... دېمەك: I took him to be a worker مەن ئۇنى بىر ئىشچىمىكىن دەپتىمەن. 21 تاللىماق: Which road shall we  take ? قايسى يولغا ماڭىمىز؟  take after‖ ئوخشىماق ① take in/ قوبۇل قىلماق. ② چۈشەنمەك، ئۆزلەشتۈرمەك. ③ مۇشتەر بولماق. ④ ئۆز ئىچىگە ئالماق. ⑤ ئالدىماق  take  off/ سالماق، سېلىۋەتمەك (كىيىمنى)؛ ئالماق، ئېلىۋەتمەك (دوپپا-تۇماق قاتارلىقلارنى). كۆتۈرۈلمەك، ئۇچماق (ئايروپىلان) ①  take  on / ئۈستىگە ئالماق، قوبۇل قىلماق. ② ياللىماق  take over!/ ئۆتكۈزۈۋالماق، ئۆز ئىلكىگە ئالماق ① to / ياخشى كۆرمەك. ② ... گە ئادەتلىنىپ قالماق ①  take  up / كۆتۈرمەك، ئالماق. ② تارتماق، سۈمۈرمەك. ③ ئالماق (ۋاقىتنى)؛ ئىگىلىمەك (بىرەر بوشلۇقنى). ④ شۇغۇللانماق، مەشغۇل بولماق، ئۆگەنمەك. ⑤ داۋاملاشتۇرماق، يېڭىۋاشتىن باشلىماق.', 'T'),
