('though', 'conj.Ⅰ گەرچە: Though tired, we kept on. گەرچە ھارغان بولساقمۇ، يەنىلا ئىشنى داۋاملاشتۇردۇق i will try it,  though  I may fail. / گەرچە مەغلۇبىيەتكە ئۇچرىغان بولساممۇ، يەنە بىر قېتىم سىناپ باقماقچىمەن. dv.Ⅱ لېكىن، ئەمما، بىراق: He said he would come; he didn’t  though . ئۇ كېلىمەن دېگەنىدى، بىراق كەلمىدى.', 'T'),
('thoughtful', '①adj. چوڭقۇر ئويلانغان. ② ئىدىيىۋىلىك. ③ ھالىغا يېتىدىغان، دەردىگە دەرمان بولىدىغان.', 'T'),
