('thrash', '①v. دۇمبالىماق؛ قامچىلىماق. ② (خامان) ھەيدىمەك، تەپمەك. ③ يەڭمەك، غەلىبە قىلماق.', 'T'),
('thread', '①n.Ⅰ يىپ، شوينا. ② يىپ ئۇچى. ③ ۋىنتا بۇرمىسى. ①v.Ⅱ يىپ ئۆتكۈزمەك، يىڭنىگە يىپ ئۆتكۈزمەك. ② ئۆتمەك، كېسىپ ئۆتمەك (كوچىدىن).', 'T'),
