('thrive', 'v. (throve      ؛ thrived؛ thrived؛ thriven      ) ① ساغلام ئۆسۈپ يېتىلمەك. ② بۈك-باراقسان بولۇپ ئۆسمەك. ③ گۈللەنمەك.', 'T'),
