('through', '①prep.Ⅰ ئارقىلىق، ئارىسىدىن، ... دىن:  through  the gate دەرۋازىدىن. ② (ۋاقىتنى كۆرسىتىدۇ) ... گىچە، باشتىن-ئاياغ: from Monday  through  saturday. دۈشەنبىدىن شەنبىگىچە  through  one’s life /  ئۆمرىنىڭ ئاخىرىغىچە. ③ (مەلۇم سەۋەب ياكى ۋاسىتە ئارقىلىق بىرەر ئىش ھەرىكەتنى قىلغانلىقنى بىلدۈرىدۇ): talk  through  an interpreter تەرجىمان ئارقىلىق سۆزلەشمەك. dv.Ⅱ (ئادەم ياكى نەرسىلەرنىڭ مەلۇم جايدىن ئۆتۈشى ياكى سۇيۇق جىسىملارنىڭ بىرەر نەرسىدىن ئۆتۈپ كېتىشىنى كۆرسىتىدۇ): pierce a thing  through  تېشىپ ئۆتمەك let sb.  through  / بىراۋغا يول بەرمەك. ② باشتىن-ئاخىرغىچە، تەلتۆكۈس. تامامەن. ③ ئۇدۇل، ئۇدۇللاپ. adj.Ⅲ (مەلۇم جايدىن) ئۆتىدىغان، ئۇدۇل بارىدىغان.', 'T'),
('throughout', '①prep.Ⅰ (ۋاقىتنى كۆرسىتىدۇ)پۈتۈن...مەزگىلدە،...جەرياندا: throughout  the day كۈن بويى. ② (ئورۇننى كۆرسىتىدۇ) ھەممە يەردە، ئومۇميۈزلۈك، بويىچە:  throughout  the country مەملىكەت بويىچە، مەملىكەتنىڭ ھەممىلا يېرىدە. ① dv.Ⅱ باشتىن-ئاياغ، ئۈزۈل-كېسىل. ② ھەممە يەردە، ھەممە جايدا. ③ پۈتۈنلەي، تامامەن.', 'T'),
('throve', 'v. → thrive.', 'T'),
('throw', 'v.Ⅰ (threw      ؛        thrown) ① ئاتماق، تاشلىماق. ② چاچماق، چۈشۈرمەك (نۇر)  throw a way  c تاشلىۋەتمەك، قولدىن بەرمەك  throw  off / تاشلىۋەتمەك، چۆرۈۋەتمەك، قۇتۇلماق. n.Ⅱ ئېتىش، تاشلاش، تاشلىۋېتىش، قۇتۇلۇش.', 'T'),
('thrown', 'v. → throw.', 'T'),
