('thumb', 'n.Ⅰ باش بارماق. ①v.Ⅱ ۋاراقلىماق (كىتاب، ژۇرنال قاتارلىقلارنى). ② ۋاراقلاپ كىرالاشتۇرماق (كىتاب بەتلىرىنى).', 'T'),
('thump', 'n.Ⅰ بىر نەرسىنىڭ ئىككىنچى بىر نەرسىگە قاتتىق سوقۇلغان ئاۋازى، قاتتىق ئۇرۇلغان ئاۋاز. v.Ⅱ ئۇرماق، سوقماق، قاقماق.', 'T'),
('thunder', '①n.Ⅰ گۈلدۈرماما. ② گۈلدۈراس (ئاۋاز). ①v.Ⅱ ھاۋا گۈلدۈرلىمەك. ② ۋارقىراپ سۆزلىمەك.', 'T'),
