('tick', '①n.Ⅰ تىك-تىك ئاۋاز (سائەتنىڭ). ② كىچىك بەلگە (). ③ نېسى، نېسى سېتىۋېلىش. ①v.Ⅱ تىكىلدىماق، تىك-تىك ئاۋاز چىقارماق (سائەت) ② بەلگە قويماق.', 'T'),
