('tide', 'n.Ⅰ دولقۇن: at high        tide  يۇقىرى (تۆۋەن) دولقۇن. v.Ⅱ تۈگىتىشنىڭ ئامالىنى قىلماق؛ ئۆتكۈزمەك (قىيىنچىلىقنى).', 'T'),
