('till', '①prep.Ⅰ ... گىچە، ... كىچە، ... گە قەدەر:  till  tomorrow ئەتىگىچە. ② (جۈملىنىڭ بولۇشسىز بۆلەكلىرىنىڭ كەينىدە كېلىدۇ) ... دىن بۇرۇن، ... گىچە، ... ئاندىن . He did not come  till  nine. ئۇ سائەت توققۇز بولغاندا ئاندىن يېتىپ كەلدى (ئۇ سائەت توققۇزدىن بۇرۇن كەلمىگەن). conj.Ⅱ ... گىچە، ... كىچە، ... گە قەدەر: Wait  till  I come back. مەن قايتىپ كەلگۈچە كۈتۈڭ.', 'T'),
