('to', '①prep. (نىشان، يۆنىلىش قاتارلىقلارنى بىلدۈرۈپ، -غا، -قا، -گە، -كە قاتارلىق قوشۇمچىلار بىلەن ئىپادىلىنىدۇ) turn  to  the right ئوڭغا بۇرۇلماق fall  to  the ground / يەرگە چۈشۈپ كەتمەك. ② (دائىرە، ياكى دەرىجىنى كۆرسىتىدۇ) ... گىچە، ... كىچە، ... گە قەدەر: from beginning  to  the end بېشىدىن ئاخىرىغىچە. ③ (سېلىشتۇرۇش ياكى نىسبەتنى كۆرسىتىدۇ): ten  one ئوندا بىر. ④ ... بويىچە، ... گە ئاساسەن، ... گە قاراپ، ... گە لايىق: a dress made  to  order بۇيرۇتۇپ تىكتۈرۈلگەن كىيىم. ⑤ (مەقسەتنى ياكى نەتىجىنى بىلدۈرىدۇ):  come  to  rescue كېلىپ قۇتقۇزماق. ⑥ (قوشۇمچە ياكى تەئەللۇقلۇقنى بىلدۈرىدۇ): factories attached  to  the university داشۆگە قاراشلىق زاۋۇتلار.', 'T'),
