('together', '①dv. بىرگە، بىللە، بىرلىكتە، بىر يەردە. ② ئۇدا، ئۈزۈلمەي، ئۈزلۈكسىز with  together ‖ بىلەن بىللە.', 'T'),
('toil', '①v. جاپا چەكمەك، جاپا تارتماق. ② جاپالىق ئىشلىمەك، قاتتىق ئىشلىمەك.', 'T'),
('toilet', '①n.Ⅰ ياسىنىش، گىرىم قىلىش. ② يۇيۇنۇش ئۆيى. ③ ھاجەتخانا، خالا جاي. ①adj.Ⅱ گىرىم قىلىشقا ئىشلىتىلىدىغان. ② تازىلىققا ئىشلىتىلىدىغان، تەرەتكە ئىشلىتىلىدىغان.', 'T')
