('welfare', '① n. پاراۋانلىق. ② بەخت، بەخت-سائادەت.', 'W'),
('well-being', '① n. بەخت، بەخت-سائادەت. ② پاراۋانلىق. ③ سالامەتلىك، ساغلاملىق.', 'W'),
('well-known', 'adj. ئاتاقلىق، مەشھۇر.', 'W'),
('well 1', 'n.Ⅰ قۇدۇق، نېفىت قۇدۇقى. v.Ⅱ ئېتىلىپ چىقماق، ئۇرغۇپ چىقماق.', 'W'),
('well 2', 'adj.Ⅰ better      ؛ best      ) ① ياخشى، ساغلام: I am perfectly  well 2  تېنىم ناھايىتى ساغلام، تەن سالامەتلىكىم ناھايىتى ياخشى.  مۇۋاپىق، قانائەتلىنەرلىك. adv.Ⅱ (better؛ best) ① ياخشى، توغرا، قانائەتلىنەرلىك ھالدا، قانائەتلەنگۈدەك. ② تولۇق، ئۈزۈل-كېسىل int.Ⅲ ھوي، ھەي، ھە، ياخشى.', 'W'),
('went', 'v.→ go.', 'W'),
('wept', 'v.→ weep.', 'W'),
('were', 'v.→ be.', 'W'),
('weren’t', 'were not.', 'W'),
('weren’t', 'were not. ①ux.v.Ⅱ (ئاساسىي پېئىلنىڭ ھازىرقى زامان سۈپەتداش شەكلى بىلەن بىرگە كېلىپ، داۋام تۈس شەكىللىنىدۇ): Heis working. ئۇ ئىشلەۋاتىدۇ. ② پېئىلنىڭ ئۆتكەن زامان سۈپەتداش شەكلى بىلەن بىرگە كېلىپ، مەجھۇل دەرىجە شەكىللىنىدۇ: The letter was written yesterday بۇ خەت تۈنۈگۈن يېزىلغان. ③ (ئاساسىي پېئىلنىڭ ئىنفىنىتىۋ شەكلى بىلەن بىرگە كېلىپ مەجبۇرىيەت، ۋەزىپە، مەقسەت، ئوي-پىكىر، ۋەدە، كېلىشىم ۋە ئىمكانىيەت قاتارلىق ئۇقۇملارنى بىلدۈرىدۇ)(: Weare to meet at the schoolgate. بىز مەكتەپ دەرۋازىسى ئالدىدا كۆرۈشىدىغان بولدۇق.', 'W'),
('west', '① n.Ⅰ غەرب، كۈنپېتىش. ② غەرب مەملىكەتلىرى، غەربىي يېرىم شار. adj.Ⅱ غەرب، غەربىي. adv.Ⅲ غەرب تەرەپكە، كۈن پېتىشقا.', 'W'),
('western', 'adj. غەرب، غەربىي، غەرب مەملىكەتلىرىنىڭ.', 'W'),
('westward', 'adj. غەربكە قارىتىلغان، غەربتىكى.', 'W'),
('wet', '① adj.Ⅰ ھۆل، نەم، زەي. ② يامغۇر كۆپ ياغىدىغان. ③ خاتا قىلىنغان، ناتوغرا بولۇپ قالغان. ① n.Ⅱ نەملىك        ② يامغۇر. v.Ⅲ ھۆل قىلماق.', 'W'),
('whale', 'n. كىت.', 'W'),
('what', '① pron.Ⅰ (سوراق ئالماش بولۇپ كېلىدۇ) نېمە؛ نېمە ئىش قىلىدىغان ئادەم: What is he? ئۇ نېمە ئىش قىلىدىغان ئادەم ◇ what is the time? / سائەت قانچە بولدى؟ ◇ Wtat ’s the price? / باھاسى قانچە؟ What did you say? / نېمە دېدىڭىز؟ ② (باغلىغۇچى ئالماش بولۇپ كېلىدۇ): We can learn  what  we did not know. بىز بۇرۇن بىلمەيدىغان نەرسىلەرنى ئۆگىنىۋالالايمىز. ① adj.Ⅱ (نېمە، قانداق دېگەنگە ئوخشاش ئۇقۇملارنى بىلدۈرىدۇ): What time is it? سائەت قانچە بولدى؟ What news have you? / قانداق خەۋەر ئېلىپ كەلدىڭ؟ ② (ھەسرەتلىنىش، ئاھ ئۇرۇش، خۇرسىنىش قاتارلىقلارنى بىلدۈرۈپ، پاھ، نېمىدېگەن دېگەنگە ئوخشاش ئۇقۇملارنى بىلدۈرىدۇ): What a beautiful city! پاھ، نېمىدېگەن گۈزەل شەھەر-ھە!', 'W'),
('what’s', 'what is.', 'W'),
('whatever', 'pron.Ⅰ ئومۇمەن، نېمە بولۇشىدىن قەتئىينەزەر: ◇ Take  whatever  you like. نېمىنى خالىساڭ شۇنى ئال. ① adj.Ⅱقانداق بولۇشىدىن قەتئىينەزەر، قايسى خىلدا بولۇشىدىن قەتئىينەزەر: Whatever book you may read, read it carefully. مەيلى قانداقلا كىتاب بولمىسۇن ئوقۇساڭ تەپسىلىي ئوقۇشۇڭ كېرەك. ② ھېچنېمە.', 'W'),
('whatsoever', 'whatever.', 'W'),
('wheat', 'n. بۇغداي.', 'W'),
('wheel', '① n.Ⅰ چاق. ② (ئوڭ-سولغا) بۇرۇلۇش ھەرىكىتى. ① v.Ⅱ ھارۋا ئىتتىرمەك، ھارۋىدا توشۇماق. ② ئايلاندۇرماق.', 'W'),
('when', '① adv.Ⅰ (سوراق رەۋىش بولۇپ كېلىدۇ)قاچان: When does the meeting begin? يىغىن قاچان باشلىنىدۇ؟ ② (نىسپىي رەۋىش بولۇپ كېلىدۇ)... غان چاغدا، ... پەيتتە: He came at a time  when  we needed help. ئۇ، بىز ياردەمگە مۇھتاج بولغان چاغدا كەلگەن.  ① conj.Ⅱ ... غان (گەن) چاغدا: It was snowing  when  he arrived. ئۇ كەلگەن چاغدا يامغۇر يېغىۋاتاتتى. ② ... لا ...: We’ll start  when  the team leader comes. دۈيجاڭ كەلسىلا بىز يولغا چىقىمىز. ① pron.Ⅲ قاچان: Until  when  can you stay? قاچانغىچە تۇرالايسەن؟ ② شۇ چاغ، شۇ ۋاقىت: He left in May, since  when  I have notseen him. ئۇ مايدا (ماي ئېيىدا) كەتكەن، شۇندىن بۇيان ئۇنى كۆرمىدىم.', 'W'),
('whenever', 'adv.＆ conj. ھەر قېتىم، قاچان بولۇشىدىن قەتئىينەزەر، قاچانلا بولمىسۇن، دائىم، ھەر قاچان، ھەممە ۋاقىت: I’ll see him  whenever  he likes to come. قاچانلا بولمىسۇن، ئۇ كەلسىلا مەن كۆرۈشىمەن Whenever we met with difficulties, they come to help us./ ھەر قېتىم قىيىنچىلىققا دۇچ كەلسەك، ئۇلار بىزگە ياردەم بېرەتتى.', 'W'),
('where', '① adv. (سوراق رەۋىش بولۇپ كېلىدۇ) نەگە، قەيەردە، نەدىن: Where are you from? سىز نەدىن؟ Where are you going? نەگە بارىسىز؟ ② (باغلىغۇچى رەۋىش بولۇپ كېلىدۇ: Idon’t know  where  I can. find him ( where to find him). ئۇنى نەگە بېرىپ ئىزدەيدىغانلىقىمنى بىلمەيمەن. ③ (نىسپىي رەۋىش بولۇپ كېلىدۇ): This is the room  where  he lived. بۇ ئۇنىڭ بۇرۇن تۇرغان ئۆيى.', 'W'),
('whereas', '① conj. نەزەردە تۇتقاندا، كۆزدە تۇتقاندا؛... لىقى ئۈچۈن. ② بىراق، ئەمما، ئەكسىچە: Modesty helps one to go forward,  whereas  conceit makes one lag behind. كەمتەرلىك كىشىنى ئالغا باستۇرۇىدۇ، مەغرۇرلۇق كىشىنى ئارقىدا قالدۇرىدۇ.', 'W'),
('whereby', '① adv. نېمىنى ئاساس قىلىپ، نېمىگە ئاساسەن. ② شۇنىڭغا تايىنىپ، شۇنى ئاساس قىلىپ.', 'W'),
('wherefore', 'adv.Ⅰ نېمە ئۈچۈن. n.Ⅱ سەۋەب، ئاساس.', 'W'),
('wherein', 'adv. شۇنىڭ ئىچىدە، ئۇنىڭ ئىچىدە، شۇ نۇقتىدا، جەرياندا.', 'W'),
('wherever', '① adv. زادى نەدە، قەيەردە: Wherever did you see such a thing? سەن بۇنداق نەرسىنى زادى نەدە كۆردۈڭ؟ ② ھەرقانداق يەرگە، ھەرقانداق يەردە. ③ (باغلىغۇچى رەۋىش بولۇپ كېلىدۇ) مەيلى نەگە، مەيلى نەدە: wherever we go, we must indentify ourselves with the masses. مەيلى نەگىلا بارمايلى، شۇ جايدىكى ئامما بىلەن ئىچقويۇن-تاشقۇيۇن بولۇشىمىز كېرەك.', 'W'),
('whether', 'conj. (سوراق ئۇقۇملارنى بىلدۈرىدۇ):Ask him  whether  he can come. ئۇ كېلەلەمدۇ يوق سوراپ باقايلى. I don’ t know  whether  it will rain or not. يامغۇر ياغامدۇ ياغمامدۇ بىلمەيمەن. Whether it is true remains a question ئۇنىڭ زادى راست ياكى يالغانلىقى تېخى بىر مەسىلە.② ...گە قارىماي، مەيلى قانداقلا بولمىسۇن، ...دىن قەتئىينەزەر:  whether  We must perseverein our work  conditions are favourable or adverse. شەرت-شارائىتىمىزنىڭ ياخشى-يامان بولۇشىدىن قەتئىينەزەر، ۋەدىمىزدە چىڭ تۇرۇشىمىز كېرەك.', 'W'),
('which', '① pron.Ⅰ (سوراق ئالماش بولۇپ كېلىدۇ) قايسى: Which will you take, milk or cream? قايسىنى ئىچىسىز، سۈتنىمۇ ياكى قايماقنىمۇ؟ It’s hard to say  which  is the best item on the programme./ قايسى نومۇرنىڭ ئەڭ ياخشى ئىكەنلىكىنى بىر نەرسە دېيىش تەس. ② (نىسپىي ئالماش بولۇپ كېلىدۇ) ھېلىقى، شۇ: This is the power station  which  we buil last year. بۇ بىز بۇلتۇر قۇرغان ھېلىقى ئېلېكتر ئىستانسىسى. adj.Ⅱ قايسى: Which way sall we go? قايسى يولغا ماڭىمىز؟', 'W'),
('while', 'n.Ⅰ بىر مەزگىل، بىر دەم: Wait a  while  بىر دەم ساقلاڭ. v.Ⅱ (بىكار) ئۆتكۈزمەك:  while  the time away ۋاقىتنى بىكارغا ئۆتكۈزمەك. ① conj.Ⅲ ... چاغدا، ... بىلەن بىرلا ۋاقىتتا: While (he was) in Peking, he visited Great Wall. ئۇ بېيجىڭدا تۇرغان چاغلىرىدا سەددىچىن سېپىلىنى زىيارەت قىلغان. ② لېكىن، ئەمما. ③ گەرچە: While I find the problems very difficult, I don’t think them insoluble. گەرچە ئۇ مەسىلە قىيىن بولسىمۇ، لېكىن يەنىلا ھەل قىلغىلى بولىدۇ، دەپ ئويلايمەن.', 'W'),
('whilst', 'conj while.', 'W'),
('whip', 'n.Ⅰ قامچا. ① v.Ⅱ قامچىلىق. ② قوچۇماق، ئىلەشتۈرمەك. ③ تۇيۇقسىز يۆتكەلمەك (نەرسىلەر)؛ تۇيۇقسىز تارتىۋېلىنماق، توساتتىن بۇلاپ كېتىلمەك.', 'W'),
('whirl', '① v.Ⅰ ئايلانماق، ئايلاندۇرماق. ② ئۇچقاندەك چاپماق. ① n.Ⅱ ئايلاندۇرۇش. ② قالايمىقان قىلىش.', 'W'),
('whirlwind', 'n. قۇيۇن.', 'W'),
('whisky, whiskey', 'n. ۋىسكى ھارىقى.', 'W'),
('whisper', '① v.Ⅰ پىچىرلىماق، شىۋىرلىماق. ② پىنھان يەتكۈزۈپ قويماق (شۇم خەۋەرنى). ① n.Ⅰ غەيۋەت گەپ، ئۆسەك سۆز. ② پىچىر-پىچىر ئاۋاز. ③ (شامالنىڭ) ئۇشقىرتىش ئاۋازى.', 'W'),
('whistle', '① v.Ⅰ ئۈشتەك چالماق، غوڭۇلدىماق. ② ۋىڭىلداپ ئۇچماق. ③ پۈۋلەپ ئاۋاز چىقارماق. ① n.Ⅱ ئۈشتەك ئاۋازى؛ شامال ئاۋازى؛ گۈدۈك ئاۋازى. ② ئۈشتەك؛ گۈدۈك؛ سىگنال.', 'W'),
('white', '① adj.Ⅰ ئاق، ئاق رەڭلىك. ② ئاق تەنلىك. ① n.Ⅱ ئاق رەڭ. ② ئاق تەنلىكلەر، ئاق جىنىسلىقلار. ③ تۇخۇم ئېقى.', 'W'),
('who', 'pron. (ئىگىلىك كېلىش شەكلى        whose؛ چۈشۈم كېلىش شەكلى whom      ) ① (سوراق ئالماش بولۇپ كېلىدۇ) كىم: Who has taken my book? كىتابىمنى كىم ئالدى؟ To whom did you give the letter? / خەتنى كىمگە بەردىڭىز؟ ② (باغلىغۇچى ئالماش بولۇپ كېلىدۇ) كىم: I don’t know  who those people are. ئۇ كىشىلەرنىڭ كىملىكىنى بىلمەيمەن. ③ (نىسپىي ئالماش بولۇپ كېلىدۇ) ئاۋۇ، ھېلىقى... (ئادەم): The woman  who  is carrying fertilizer to the fields is our brigade leader. ئېتىزغا خىمىيىۋى ئوغۇت توشۇۋاتقان (ئاۋۇ) ئايال بىزنىڭ بىرىگادىر.', 'W'),
('whoever', 'pron. (ئىگىلىك كېلىش شەكلى whosever؛ چۈشۈم كېلىش شەكلى whomever) كىم بولۇشىدىن قەتئىينەزەر، كىم بولسا بولسۇن: Whoever makes mis takes must correct them. كىم بولۇشىدىن قەتئىينەزەر خاتالىق ئۆتكۈزسە تۈزىتىش كېرەك.', 'W'),
('whole', '① adj.Ⅰ پۈتۈن، ھەممە، بارلىق: the  whole  wold پۈتۈن دۇنيا. ② تولۇق:  whole  number تولۇق نومۇر. n.Ⅱ ھەممە، بارلىق، ئومۇم. ئومۇملۇق، پۈتۈنلۈك.', 'W'),
('wholehearted', 'adj.پۈتۈن ۋۇجۇدىنى بېغىشلىغان جان-دىلى بىلەن ئىشلەيدىغان.', 'W'),
('wholesome', 'adj.سالامەتلىككە پايدىلىق، سالامەتلىك.', 'W'),
('wholly', '① adv.پۈتۈنلەي، تولۇق. ② ساق، سالامەت.', 'W'),
('whom', 'pron.→ who.', 'W'),
('whose', 'pron. (who نىڭ ئىگىلىك كېلىش شەكلى) ①(سوراق ئالماش بولۇپ كېلىدۇ) كىمنىڭ: بۇ كىتاب كىمنىڭ؟ Whose book is this? I wonder  whose  hat that is. / ئۇ شەپكە كىمنىڭ ئىكەنلىكىنى بىلمەيمەن. ② (نىسپىي ئالماش بولۇپ كېلىدۇ): Is thera anyone here  whose  name is Adil? بۇ يەردە ئادىل ئىسىملىك ئادەم بارمۇ؟', 'W')
ON CONFLICT (english) DO NOTHING;

INSERT INTO public.english_uyghur_dictionary (english, uyghur, letter_group) VALUES
('why', '① adv.Ⅰ(سوراق رەۋىش بولۇپ كېلىدۇ) نېمە ئۈچۈن، نېمە سەۋەبتىن: Why did you do it? بۇ ئىشنى نېمە ئۈچۈن قىلدىڭ؟ ② (باغلىغۇچى رەۋىش بولۇپ كېلىدۇ) نېمە ئۈچۈن، نېمە سەۋەبتىن: I don’t know  why  the meeting was postphoned. يىغىننىڭ نېمە ئۈچۈن كەينىگە سۈرۈلگەنلىكىنى بىلمەيمەن. ③ (نىسپىي رەۋىش بولۇپ كېلىدۇ) نېمە ئۈچۈن: This is the reason  why  he failed. بۇ ئۇنىڭ (نېمە ئۈچۈن) مەغلۇپ بولغانلىقىنىڭ سەۋەبى. int.Ⅱ (ھەيران قېلىش، قانائەتلىنىش، ياكى قارشى تۇرۇش قاتارلىقلارنى بىلدۈرۈپ، ھەي، ھوي، ھەئە، ھە، ئەلۋەتتە، نېمە؟ دېگەنگە ئوخشاش سۆزلەر بىلەن ئىپادىلىنىدۇ): why, of course. ھە، ئەلۋەتتە. Is it true? — why, yes, I think so. شۇ راستمۇ؟ — ھەئە، راست، مېنىڭمۇ ئويۇم شۇنداق.', 'W'),
('wicked', '① adj. يامان، ئوسال، رەزىل. ② يامان نىيەتلىك، نىيىتى بۇزۇق.', 'W'),
('wickedness', '① n. يامان، قەبىھ، رەزىل. ② يامان نىيەت.', 'W'),
('wide', '① adj.Ⅰكەڭ، بىپايان.② يىراق (ئەسلى تېمىدىن). ① adv.Ⅱ كەڭ كۆلەمدە. ② يىراقتا.', 'W'),
('widely', 'adv.→wide.', 'W'),
('widow', 'n. تۇل خوتۇن.', 'W'),
('widower', 'n. بويتاق.', 'W'),
('width', 'n. كەڭلىك، ئەن.', 'W'),
('wife', '(wives       n. خوتۇن، رەپىقە.', 'W'),
('wig', 'n. يالغان چاچ.', 'W'),
('wild', '① adj.Ⅰياۋايى، ياۋايىلىق، ۋەھشىي، ۋەھشىيلىك. ② تەلۋىلىك. ③ قالايمىقان. ④ ھاپىلا-شاپىلا. ① adv.Ⅱ قالايمىقان. ② ھاپىلا-شاپىلا، قول ئۇچىدىلا. يېنىكلىك بىلەن.', 'W'),
('wilderness', 'n. چۆل، بوز يەر.', 'W'),
('wildly', 'adv. wild.', 'W'),
('will 1', '① (would      ) aux.v. (ئىككىنچى ۋە ئۈچىنچى شەخسلەر بىلەن بىرگە كېلىپ كېلىدىغان زاماننى بىلدۈرىدۇ) ... ماقچى، ... مەكچى: He will come at five o’ clock. ئۇ سائەت بەشتە كەلمەكچى. ② (ھەممە شەخسلەر بىلەن بىرگە كېلىپ خالاش، ماقۇل بولۇش، ئىرادە قىلىش قاتارلىق ئۇقۇملارنى بىلدۈرىدۇ): I  will 1  go wherever the party leads us. مەن مەڭگۈ پارتىيىگە ئەگىشىپ ماڭىمەن.', 'W'),
('will 2', 'n. ئىرادە، غايە، ئارزۇ، مەقسەت.', 'W'),
('willing', 'adj. رازىلىق بىلەن، ئىختىيارىي.', 'W'),
('willow', '① n. تال، سۆگەت. ② سۆگەت ياغىچى.', 'W'),
('wilt', '① v. تۆكۈلمەك، توزۇماق، توزۇتماق، خازان بولماق. ② چۈشكۈنلەشمەك، روھسىزلانماق، چۈشكۈنلەشتۈرمەك.', 'W'),
