('with', '① prep. (بىرەر نەرسىنىڭ مەۋجۇتلۇقىنى ياكى ئۆزىگە خاس خۇسۇسىيىتىنى كۆرسىتىدۇ):  a book  with  ullustration  رەسىملىك كىتاب  a fighter  with  prectical experience / تەجرىبىلىك جەڭچى. ② (... بىلەن توشقۇزۇش، پۈركەش قاتارلىق ئۇقۇملارنى بىلدۈرىدۇ): fill a glass  with  water سۇ بىلەن ئىستاكاننى توشقۇزماق. ③(ئۇسۇل ياكى سايماننى كۆرسىتىپ، ... بىلەن، ... نى، ... نىڭ ياردىمىدە دېگەندە ئوخشاش سۆزلەر بىلەن ئىپادىلىنىدۇ): plough the fields  with  tractors تراكتور بىلەن يەر ھەيدىمەك dig  with  a pick / جوتۇ بىلەن قازماق. ④ (قارىمۇ قارشىلىق، رەقىبى بىلەن ئېلىشىش قاتارلىقلارنى بىلدۈرىدۇ): fight  with  an enemy  رەقىبى بىلەن ئېلىشماق، دۈشمەن بىلەن جەڭ قىلماق argue  with  sb. / بىراۋ بىلەن زاكونلاشماق. ⑤ (ھەمراھ بولۇش، بىرلىشىش قاتارلىقلارنى بىلدۈرۈپ، بىللە، ... بىلەن بىللە، بىلەن دېگەنگە ئوخشاش ئۇقۇملارنى بىلدۈرىدۇ): Come  with  me مەن بىلەن بىللە كېلىڭ. ⑥ ئايرىلىش ياكى بۆلۈنۈشنى كۆرسىتىدۇ): part  with  sb. بىراۋدىن ئايرىلماق. ⑦ (سەۋەبىنى كۆرسىتىدۇ) تۈپەيلىدىن، ... لىقتىن: jump  with  joy خۇشاللىقىدىن سەكرەپ كەتمەك. ⑧ (روھىي ھالەتنى كۆرسىتىدۇ) ... بىلەن، ... ھالدا: fight  with  courage قەھرىمانلىق بىلەن جەڭ قىلماق. ⑨ ... غا قارىماي، ... بولسىمۇ: With all her merits, she was not proud. گەرچە ئۇنىڭ شۇنچە كۆپ ئارتۇقچىلىقى بولسىمۇ يەنىلا ھاكاۋۇرلۇق قىلمايدۇ.', 'W'),
('withdraw', 'v.withdrew      ؛withdrawn       ①يىغماق، يىغىۋالماق.② ئالماق (بانكىدا ئامانەت قويۇلغان پۇلنى). ③ قايتۇرۇپ كەتمەك، چېكىنمەك. ④ ئەمەلدىن قالدۇرماق، بىكار قىلماق.', 'W'),
('withdrew', 'v.→ withdraw.', 'W'),
