('without', '① prep.Ⅰ (يوقلۇقنى بىلدۈرىدۇ):  without  money پۇلسىز، پۇلى يوق He went out  without  a coat. / ئۇ چاپان كىيمەي چىقىپ كەتتى He came in  without  knoking. / ئۇ ئىشىكنى چەكمەي كىردى. ② سىرتىدا، تاشقىرىدا: wait  without  the door. ئىشىكنىڭ سىرتىدا ساقلاڭ. ③ (شەرتنى بىلدۈرىدۇ) بولمىسا، بولمىغان بولسا: Without a people’s army the people have nothing. خەلقنىڭ ئارمىيىسى بولمىسا، خەلقنىڭ ھېچ نەرسىسى بولمايدۇ. adv.Ⅱ سىرتىدا، تاشقىرىدا.', 'W'),
